CREATE OR REPLACE FUNCTION public.armer_retrait_annonce_pour(p_annonce uuid, p_chemin text, p_delai interval, p_preuve_geste boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  a      public.annonces_plateforme%ROWTYPE;
  i      public.inventaire%ROWTYPE;
  v_url  text;
  v_pf   jsonb;
  v_del  uuid;
BEGIN
  IF NOT COALESCE(p_preuve_geste, false) THEN
    RETURN NULL;
  END IF;
  SELECT * INTO a FROM public.annonces_plateforme WHERE id = p_annonce FOR UPDATE;
  IF NOT FOUND OR a.inventaire_id IS NULL OR a.disparu_le IS NOT NULL OR a.retiree_le IS NOT NULL OR a.ignoree_le IS NOT NULL
     OR length(btrim(COALESCE(a.listing_id, ''))) < 4 THEN
    RETURN NULL;
  END IF;
  SELECT * INTO i FROM public.inventaire WHERE id = a.inventaire_id AND user_id = a.user_id;
  IF NOT FOUND OR i.fusionne_dans IS NOT NULL OR i.statut IS DISTINCT FROM 'vendu'
     OR lower(COALESCE(NULLIF(i.plateforme, ''), '')) = lower(a.platform) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.ventes v
              WHERE v.user_id = a.user_id AND v.inventaire_id = a.inventaire_id
                AND lower(COALESCE(v.statut, '')) NOT IN ('annule', 'annulée', 'cancelled', 'canceled')
                AND lower(COALESCE(NULLIF(v.plateforme_code, ''), NULLIF(v.plateforme, ''), '')) = lower(a.platform)) THEN
    RETURN NULL;
  END IF;
  IF a.platform = 'opla' AND public.opla_sortie_passee() THEN
    RETURN NULL;
  END IF;
  IF COALESCE(a.transaction_plateforme, '') IN ('pending', 'sold') THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.cross_post_jobs d
              WHERE d.user_id = a.user_id AND d.platform = a.platform AND d.action = 'delete'
                AND d.status IN ('pending', 'processing', 'needs_user')
                AND public.listing_designe(a.listing_id, d.listing_url, d.platform_listing_id)) THEN
    RETURN NULL;
  END IF;
  v_url := NULLIF(btrim(COALESCE(a.url, '')), '');
  v_pf := jsonb_build_object('arme_par', jsonb_build_object(
            'chemin', p_chemin, 'le', now(), 'annonce', a.id, 'depot', a.job_id,
            'pose_par', 'armer_retrait_annonce_pour (serveur)'),
          'preuve', 'geste_deja_vendu');
  IF v_url IS NULL THEN
    v_pf := v_pf || jsonb_build_object('removal_url_missing', true);
  END IF;
  IF p_delai IS NOT NULL AND p_delai > interval '0' THEN
    v_pf := v_pf || jsonb_build_object('next_action_after', to_jsonb(now() + p_delai));
  END IF;
  INSERT INTO public.cross_post_jobs
    (user_id, inventaire_id, platform, action, status, photo_option, title, listing_url, platform_listing_id, platform_fields)
  VALUES
    (a.user_id, a.inventaire_id, a.platform, 'delete', 'pending', 'original',
     COALESCE(NULLIF(btrim(COALESCE(a.titre, '')), ''), i.titre), v_url, btrim(a.listing_id), v_pf)
  RETURNING id INTO v_del;
  IF v_del IS NOT NULL THEN
    INSERT INTO public.usage_logs (user_id, feature, metadata)
    VALUES (a.user_id, 'retrait_annonces', jsonb_build_object(
      'chemin', p_chemin, 'plateformes', jsonb_build_array(a.platform), 'n_annonces', 1, 'n_articles', 1,
      'article_id', a.inventaire_id::text, 'annonce', a.id, 'listing_id', a.listing_id));
  END IF;
  RETURN v_del;
END;
$function$

CREATE OR REPLACE FUNCTION public.armer_retrait_copie_reliee(p_job uuid, p_chemin text, p_pose text, p_marque jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  j        public.cross_post_jobs%rowtype;
  v_url    text;
  v_pf     jsonb;
  v_del    uuid;
  v_statut text;
begin
  begin
    select * into j from public.cross_post_jobs where id = p_job for update nowait;
  exception when lock_not_available then
    return jsonb_build_object('statut', 'verrou', 'job', p_job);
  end;
  if not found or j.status is distinct from 'published' or coalesce(j.action, 'publish') not in ('publish', 'republish') then
    return jsonb_build_object('statut', 'saute', 'job', p_job, 'motif', 'plus_publiee');
  end if;
  v_url := nullif(btrim(coalesce(j.listing_url, '')), '');
  if v_url is null and nullif(btrim(coalesce(j.platform_listing_id, '')), '') is null then
    return jsonb_build_object('statut', 'refus', 'job', p_job, 'motif', 'sans_numero_ni_lien');
  end if;
  if exists (
    select 1 from public.cross_post_jobs d
     where d.user_id = j.user_id and d.inventaire_id = j.inventaire_id
       and d.platform = j.platform and d.action = 'delete'
       and (d.status in ('pending', 'processing', 'needs_user')
            or (d.status = 'deleted' and d.created_at >= coalesce(j.published_at, j.created_at)))
       and (public.listing_designe(coalesce(j.platform_listing_id, v_url), d.listing_url, d.platform_listing_id)
            or (v_url is not null and d.listing_url = v_url)
            or (j.platform_listing_id is not null and d.platform_listing_id = j.platform_listing_id))
  ) then
    return jsonb_build_object('statut', 'deja', 'job', p_job);
  end if;
  if public.annonce_en_retrait_compte_relie(j.id) then
    return jsonb_build_object('statut', 'refus', 'job', p_job, 'motif', 'annonce_en_retrait_compte_relie');
  end if;

  v_pf := jsonb_build_object('arme_par', jsonb_build_object('chemin', p_chemin, 'le', now(), 'depot', j.id, 'pose_par', p_pose)
                                         || coalesce(p_marque, '{}'::jsonb));
  if v_url is null then
    v_pf := v_pf || jsonb_build_object('removal_url_missing', true);
  end if;
  if j.platform = 'depop' and coalesce(j.platform_fields ->> 'depop_product_id', '') ~ '^[0-9]+$' then
    v_pf := v_pf || jsonb_build_object('depop_product_id', j.platform_fields -> 'depop_product_id');
  end if;
  insert into public.cross_post_jobs
    (user_id, inventaire_id, platform, action, status, photo_option, title, listing_url, platform_listing_id, platform_fields)
  values
    (j.user_id, j.inventaire_id, j.platform, 'delete', 'pending', 'original',
     j.title, v_url, nullif(btrim(coalesce(j.platform_listing_id, '')), ''), v_pf)
  returning id, status into v_del, v_statut;
  if v_del is null or v_statut not in ('pending', 'needs_user') then
    return jsonb_build_object('statut', 'saute', 'job', p_job, 'motif', 'garde_insertion', 'retrait', v_del);
  end if;
  update public.cross_post_jobs
     set platform_fields = coalesce(platform_fields, '{}'::jsonb) || jsonb_build_object(
           'pending_removal', false,
           'retrait_arme', jsonb_build_object('job', v_del, 'le', now(), 'chemin', p_chemin))
   where id = j.id;
  return jsonb_build_object('statut', 'arme', 'job', p_job, 'retrait', v_del, 'platform', j.platform);
end;
$function$

CREATE OR REPLACE FUNCTION public.armer_retrait_job_pour(p_job_id uuid, p_chemin text, p_delai interval, p_preuve_geste boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  j        public.cross_post_jobs%rowtype;
  v_item   text;
  v_url    text;
  v_ident  text;
  v_sans_lien boolean;
  v_pf     jsonb;
  v_del    uuid;
  v_compte text;
begin
  select * into j from public.cross_post_jobs where id = p_job_id for update;
  if not found or j.inventaire_id is null
     or coalesce(j.action, 'publish') not in ('publish', 'republish')
     or j.status is distinct from 'published' then
    return null;
  end if;

  if not exists (
    select 1 from public.ventes v
    join public.inventaire i on i.id = v.inventaire_id and i.user_id = v.user_id
    where v.user_id = j.user_id and v.inventaire_id = j.inventaire_id
      and i.statut = 'vendu'
      and lower(coalesce(v.statut, '')) not in ('annule', 'annulée', 'cancelled', 'canceled')
      and coalesce(nullif(v.plateforme_code, ''), nullif(v.plateforme, '')) is not null
      and lower(coalesce(nullif(i.plateforme, ''), nullif(v.plateforme_code, ''), v.plateforme)) <> lower(j.platform)
    limit 1
  ) and not public.vente_prouvee_fiche_liee(j.inventaire_id, j.platform) then
    if not coalesce(p_preuve_geste, false) or not exists (
      select 1 from public.inventaire i
       where i.id = j.inventaire_id and i.user_id = j.user_id and i.statut = 'vendu'
         and lower(coalesce(nullif(i.plateforme, ''), '')) <> lower(j.platform)
    ) then
      return null;
    end if;
  end if;
  if not public.retrait_job_prouve(j.id) then
    return null;
  end if;
  if not coalesce(p_preuve_geste, false) and not public.rattachement_confirme(j.id) then
    insert into public.usage_logs (user_id, feature, metadata)
    values (j.user_id, 'retrait_refuse_rattachement_automatique', jsonb_build_object(
      'chemin', p_chemin, 'job', j.id, 'platform', j.platform, 'article_id', j.inventaire_id::text,
      'rattachement', j.platform_fields -> 'rattachement'));
    return null;
  end if;
  if public.annonce_importee(j.id) and not public.vente_apres_mise_en_ligne(j.id) then
    insert into public.usage_logs (user_id, feature, metadata)
    values (j.user_id, 'retrait_refuse_vente_avant_mise_en_ligne', jsonb_build_object(
      'chemin', p_chemin, 'job', j.id, 'platform', j.platform, 'article_id', j.inventaire_id::text,
      'mise_en_ligne', public.annonce_mise_en_ligne(j.id)));
    return null;
  end if;
  if public.fiche_annonces_vivantes(j.inventaire_id, j.platform) >= 2 and not coalesce(p_preuve_geste, false) then
    return null;
  end if;
  if coalesce(j.platform_fields ->> 'sale_signal', '') = 'sold' then
    return null;
  end if;
  if j.platform = 'opla' and public.opla_sortie_passee() then
    perform public.opla_copie_a_retirer_noter(j.id, p_chemin);
    return null;
  end if;
  v_url := nullif(btrim(coalesce(j.listing_url, '')), '');
  if j.platform = 'vinted' then
    v_item := coalesce(case when j.platform_listing_id ~ '^\d+$' then j.platform_listing_id end,
                       substring(v_url from '/items/(\d+)'));
    if v_item is not null and public.vinted_annonce_vendue(j.user_id, v_item) then
      return null;
    end if;
  end if;
  v_sans_lien := v_url is null and nullif(btrim(coalesce(j.platform_listing_id, '')), '') is null;
  if exists (
    select 1 from public.cross_post_jobs d
     where d.user_id = j.user_id and d.inventaire_id = j.inventaire_id
       and d.platform = j.platform and d.action = 'delete'
       and (d.status in ('pending', 'processing', 'needs_user')
            or (d.status = 'deleted' and d.created_at >= coalesce(j.published_at, j.created_at)))
       and (v_sans_lien
            or public.listing_designe(coalesce(j.platform_listing_id, v_item, v_url), d.listing_url, d.platform_listing_id)
            or (v_url is not null and d.listing_url = v_url)
            or (j.platform_listing_id is not null and d.platform_listing_id = j.platform_listing_id))
  ) then
    return null;
  end if;
  v_pf := jsonb_build_object('arme_par', jsonb_build_object(
            'chemin', p_chemin, 'le', now(), 'depot', j.id,
            'pose_par', 'armer_retrait_job (serveur)'));
  if coalesce(p_preuve_geste, false) then
    v_pf := v_pf || jsonb_build_object('preuve', 'geste_deja_vendu');
  end if;
  if v_url is null then
    v_pf := v_pf || jsonb_build_object('removal_url_missing', true);
  end if;
  if j.platform = 'beebs' and v_sans_lien then
    v_pf := v_pf || jsonb_build_object('retrait_attend_lien', jsonb_build_object(
              'depuis', now(), 'motif', 'depot_beebs_en_verification_a_la_vente'));
  end if;
  if j.platform = 'vinted' then
    select nullif(btrim(i.vinted_account_id::text), '') into v_compte
      from public.inventaire i where i.id = j.inventaire_id;
    if v_compte is not null then
      v_pf := v_pf || jsonb_build_object('vinted_account_id', v_compte);
    end if;
  end if;
  if j.platform = 'depop' and coalesce(j.platform_fields ->> 'depop_product_id', '') ~ '^[0-9]+$' then
    v_pf := v_pf || jsonb_build_object('depop_product_id', j.platform_fields -> 'depop_product_id');
  end if;
  if p_delai is not null and p_delai > interval '0' then
    v_pf := v_pf || jsonb_build_object('next_action_after', to_jsonb(now() + p_delai));
  end if;
  insert into public.cross_post_jobs
    (user_id, inventaire_id, platform, action, status, photo_option, title, listing_url, platform_listing_id, platform_fields)
  values
    (j.user_id, j.inventaire_id, j.platform, 'delete', 'pending', 'original',
     j.title, v_url, nullif(btrim(coalesce(j.platform_listing_id, '')), ''), v_pf)
  returning id into v_del;
  update public.cross_post_jobs
     set platform_fields = coalesce(platform_fields, '{}'::jsonb) || jsonb_build_object(
           'pending_removal', false,
           'retrait_arme', jsonb_build_object('job', v_del, 'le', now(), 'chemin', p_chemin))
   where id = j.id;
  return v_del;
end;
$function$

CREATE OR REPLACE FUNCTION public.armer_retraits_fiche_liee(p_user uuid, p_fiche bigint, p_chemin text DEFAULT 'suppression_article_compte_relie'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '1s'
AS $function$
declare
  v_debut    constant timestamptz := statement_timestamp();
  v_entree   constant timestamptz := clock_timestamp();
  v_budget   constant interval := interval '2 seconds';
  v_jum      record;
  c          record;
  t          record;
  r          jsonb;
  v_chemin   text := coalesce(nullif(btrim(p_chemin), ''), 'suppression_article_compte_relie');
  v_pose     constant text := 'armer_retraits_fiche_liee (serveur)';
  v_le       text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  v_jwt      text;
  v_sub      text;
  v_part     text[];
  v_pf       jsonb;
  v_err      text;
  v_q        uuid;
  v_retrait  record;
  v_marque   jsonb;
  v_n        integer;
  v_restent  integer;
  v_avec_num boolean;
  v_supprime boolean;
  v_msg      text;
  v_marque_neuve boolean;
  v_sans     text;
  v_fait     boolean;
  v_jumelles integer := 0;
  v_hors     integer := 0;
  v_armes    integer := 0;
  v_pl       text[] := '{}';
  v_refus    integer := 0;
  v_questions integer := 0;
  v_deja     integer := 0;
  v_pub      integer := 0;
  v_repub    integer := 0;
  v_remises  integer := 0;
  v_marquees integer := 0;
  v_laissees jsonb := '[]'::jsonb;
  v_erreurs  jsonb := '[]'::jsonb;
  v_armes_j  integer;
  v_pl_j     text[];
  v_refus_j  integer;
  v_q_j      integer;
  v_deja_j   integer;
  v_pub_j    integer;
  v_repub_j  integer;
  v_eng_j    integer;
  v_ech_j    integer;
  v_rem_j    integer;
  v_mar_j    integer;
  v_hp_j     integer;
  v_lais_j   jsonb;
  v_num_j    jsonb;
  v_err_j    jsonb;
  v_encours_j integer;
  v_doute_j  text[];
  v_gard_j   jsonb;
begin
  if p_user is null or p_fiche is null then
    return jsonb_build_object('jumelles', 0, 'armes', 0);
  end if;
  if not exists (select 1 from public.fiches_liees_comptes f where f.fiche_a = p_fiche or f.fiche_b = p_fiche) then
    return jsonb_build_object('jumelles', 0, 'armes', 0);
  end if;
  if v_chemin ~ '^vente_' then
    raise exception 'armer_retraits_fiche_liee : un chemin « vente_… » est réservé au circuit de la vente (%).', v_chemin;
  end if;

  for v_jum in
    select distinct x.compte, x.fiche
      from public.fiches_liees_comptes f
      cross join lateral (select case when f.fiche_a = p_fiche then f.fiche_b else f.fiche_a end as fiche,
                                 case when f.fiche_a = p_fiche then f.user_b else f.user_a end as compte,
                                 case when f.fiche_a = p_fiche then f.user_a else f.user_b end as moi) x
      join public.inventaire i on i.id = x.fiche and i.user_id = x.compte
     where (f.fiche_a = p_fiche or f.fiche_b = p_fiche)
       and x.moi = p_user and x.compte <> p_user
       and public.comptes_sont_lies(p_user, x.compte)
       and i.fusionne_dans is null
       and i.statut is distinct from 'vendu' and not (i.quantite is not null and i.quantite <= 0)
     order by x.compte, x.fiche
  loop
    v_part := array(select p from unnest(array['leboncoin', 'beebs', 'depop', 'ebay', 'opla']) as p
                     where public.boutique_partagee_compte_relie(p_user, v_jum.compte, p) order by p);
    if cardinality(v_part) = 0 then
      v_hors := v_hors + 1;
      continue;
    end if;
    v_jumelles := v_jumelles + 1;
    v_armes_j := 0; v_pl_j := '{}'; v_refus_j := 0; v_q_j := 0; v_deja_j := 0; v_pub_j := 0; v_repub_j := 0; v_eng_j := 0;
    v_ech_j := 0; v_rem_j := 0; v_mar_j := 0; v_hp_j := 0; v_lais_j := '[]'::jsonb; v_num_j := '[]'::jsonb; v_err_j := '[]'::jsonb;
    v_encours_j := 0; v_doute_j := '{}'; v_gard_j := '[]'::jsonb;
    v_marque := jsonb_build_object('le', now(), 'chemin', v_chemin, 'de_fiche', p_fiche::text, 'de_compte', p_user, 'pose_par', v_pose);
    v_jwt := current_setting('request.jwt.claims', true);
    v_sub := current_setting('request.jwt.claim.sub', true);
    perform set_config('request.jwt.claims', jsonb_build_object('sub', v_jum.compte::text, 'role', 'authenticated')::text, true);
    perform set_config('request.jwt.claim.sub', v_jum.compte::text, true);

    for c in
      select k.job, k.platform, k.rang, k.motif_refus, k.etat_refus, k.partagee
        from public.copies_fiche_liee(p_user, p_fiche) k
       where k.compte = v_jum.compte and k.fiche = v_jum.fiche
         and (k.rang = 1 or k.rang is null)
       order by k.platform, k.mise_en_ligne desc
    loop
      if not c.partagee then
        v_hp_j := v_hp_j + 1;
        continue;
      end if;
      if clock_timestamp() - v_debut > v_budget then
        v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'retrait', 'job', c.job, 'platform', c.platform, 'erreur', 'budget'));
        continue;
      end if;
      begin
        if c.motif_refus = 'opla_quittee' then
          perform public.opla_copie_a_retirer_noter(c.job, v_chemin);
          continue;
        end if;
        v_q := null; v_sans := null;
        if c.motif_refus in ('rattachement_non_confirme', 'deux_annonces_vivantes', 'deux_annonces_paire')
           and not (c.platform = any(v_doute_j)) then
          v_doute_j := v_doute_j || c.platform;
        end if;
        if c.motif_refus in ('rattachement_non_confirme', 'deux_annonces_paire') and c.etat_refus is null then
          insert into public.inventaire_doublons (user_id, garde, absorbe, niveau, statut, motif, preuves, source)
          select v_jum.compte, v_jum.fiche, v_jum.fiche, 'probable', 'proposee', 'copie_non_prouvee',
                 jsonb_build_object(
                   'job', x.id, 'annonce_id', ap.id, 'platform', x.platform,
                   'url', coalesce(nullif(btrim(coalesce(ap.url, '')), ''), nullif(btrim(coalesce(x.listing_url, '')), '')),
                   'titre', coalesce(nullif(btrim(coalesce(ap.titre, '')), ''), nullif(btrim(coalesce(x.title, '')), '')),
                   'vendu_sur', null,
                   'rattachement', x.platform_fields -> 'rattachement',
                   'rattachement_automatique', c.motif_refus = 'rattachement_non_confirme',
                   'doute', c.motif_refus,
                   'retrait_partout', v_marque),
                 'retrait_partout_compte_relie'
            from public.cross_post_jobs x
            join lateral (
              select a.id, a.url, a.titre from public.annonces_plateforme a
               where a.job_id = x.id and a.user_id = x.user_id
                 and a.disparu_le is null and a.retiree_le is null and a.ignoree_le is null
                 and public.listing_designe(a.listing_id, x.listing_url, x.platform_listing_id)
               order by a.vu_le desc nulls last
               limit 1) ap on true
           where x.id = c.job and x.status = 'published'
             and not exists (select 1 from public.cross_post_jobs d
                              where d.user_id = x.user_id and d.inventaire_id = x.inventaire_id and d.platform = x.platform
                                and d.action = 'delete' and d.status in ('pending', 'processing', 'needs_user'))
             and not public.annonce_en_retrait_compte_relie(x.id)
          on conflict do nothing
          returning id into v_q;
          if v_q is not null then
            v_q_j := v_q_j + 1;
          else
            v_sans := case
              when exists (select 1 from public.cross_post_jobs d
                            where d.user_id = v_jum.compte and d.inventaire_id = v_jum.fiche and d.platform = c.platform
                              and d.action = 'delete' and d.status in ('pending', 'processing', 'needs_user'))
                   or public.annonce_en_retrait_compte_relie(c.job) then 'retrait_en_cours'
              when exists (select 1 from public.inventaire_doublons qd
                            where qd.user_id = v_jum.compte and qd.motif = 'copie_non_prouvee' and qd.preuves ->> 'job' = c.job::text) then 'deja_posee'
              when not exists (select 1 from public.annonces_plateforme a
                                where a.job_id = c.job and a.user_id = v_jum.compte
                                  and a.disparu_le is null and a.retiree_le is null and a.ignoree_le is null) then 'annonce_non_vivante'
              else 'annonce_non_designee' end;
            if v_sans = 'retrait_en_cours' then
              v_encours_j := v_encours_j + 1;
            end if;
          end if;
        end if;
        if c.motif_refus is not null then
          insert into public.usage_logs (user_id, feature, metadata)
          select v_jum.compte, 'retrait_refuse_compte_relie', jsonb_build_object(
                   'chemin', v_chemin, 'job', x.id, 'platform', x.platform, 'article_id', v_jum.fiche::text,
                   'motif', c.motif_refus, 'rattachement', x.platform_fields -> 'rattachement', 'question', v_q,
                   'sans_question', v_sans, 'de_fiche', p_fiche::text, 'de_compte', p_user)
            from public.cross_post_jobs x where x.id = c.job;
          v_refus_j := v_refus_j + 1;
          continue;
        end if;

        r := public.armer_retrait_copie_reliee(c.job, v_chemin, v_pose,
               jsonb_build_object('de_fiche', p_fiche::text, 'de_compte', p_user));
        if r ->> 'statut' = 'arme' then
          v_armes_j := v_armes_j + 1;
          v_pl_j := v_pl_j || c.platform;
        elsif r ->> 'statut' = 'deja' then
          v_deja_j := v_deja_j + 1;
        elsif r ->> 'statut' = 'refus' then
          insert into public.usage_logs (user_id, feature, metadata)
          values (v_jum.compte, 'retrait_refuse_compte_relie', jsonb_build_object(
            'chemin', v_chemin, 'job', c.job, 'platform', c.platform, 'article_id', v_jum.fiche::text,
            'motif', r ->> 'motif', 'de_fiche', p_fiche::text, 'de_compte', p_user));
          v_refus_j := v_refus_j + 1;
          if r ->> 'motif' = 'annonce_en_retrait_compte_relie' then
            v_encours_j := v_encours_j + 1;
          end if;
        elsif r ->> 'statut' = 'verrou' then
          v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'retrait', 'job', c.job, 'platform', c.platform, 'erreur', 'verrou'));
        end if;
      exception when others then
        get stacked diagnostics v_err = message_text;
        raise warning 'armer_retraits_fiche_liee (fiche %, dépôt %) : %', v_jum.fiche, c.job, v_err;
        v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'retrait', 'job', c.job, 'platform', c.platform, 'erreur', left(v_err, 300)));
      end;
    end loop;

    for t in
      select x.id, x.platform, coalesce(x.action, 'publish') as action, x.status, x.error, x.platform_listing_id, x.listing_url,
             coalesce(x.platform_fields, '{}'::jsonb) as pf
        from public.cross_post_jobs x
       where x.user_id = v_jum.compte and x.inventaire_id = v_jum.fiche
         and coalesce(x.action, 'publish') in ('publish', 'republish')
         and x.status in ('pending', 'processing', 'needs_user', 'failed')
       order by x.created_at, x.id
    loop
      if not (t.platform = any(v_part)) then
        v_hp_j := v_hp_j + 1;
        continue;
      end if;
      if t.platform = any(v_doute_j) then
        v_gard_j := v_gard_j || jsonb_build_array(jsonb_build_object('job', t.id, 'platform', t.platform, 'action', t.action, 'statut', t.status));
        continue;
      end if;
      v_avec_num := nullif(btrim(coalesce(t.listing_url, '')), '') is not null
                    or nullif(btrim(coalesce(t.platform_listing_id, '')), '') is not null;
      if t.status = 'processing' then
        v_lais_j := v_lais_j || jsonb_build_array(jsonb_build_object('job', t.id, 'platform', t.platform, 'action', t.action, 'statut', t.status, 'motif', 'en_cours'));
        continue;
      end if;
      if clock_timestamp() - v_debut > v_budget then
        v_lais_j := v_lais_j || jsonb_build_array(jsonb_build_object('job', t.id, 'platform', t.platform, 'action', t.action, 'statut', t.status, 'motif', 'budget'));
        v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'taches_en_attente', 'job', t.id, 'erreur', 'budget'));
        continue;
      end if;
      begin
        perform 1 from public.cross_post_jobs y where y.id = t.id and y.status = t.status for update skip locked;
        if not found then
          v_lais_j := v_lais_j || jsonb_build_array(jsonb_build_object('job', t.id, 'platform', t.platform, 'action', t.action, 'statut', t.status, 'motif', 'verrouillee'));
          v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'taches_en_attente', 'job', t.id, 'erreur', 'verrou'));
          continue;
        end if;
        v_pf := t.pf
          || jsonb_build_object('arret_utilisateur', v_le,
               'needsUserAttempts', greatest(99, case when (t.pf ->> 'needsUserAttempts') ~ '^[0-9]{1,9}$' then (t.pf ->> 'needsUserAttempts')::integer else 0 end),
               'retrait_partout_compte_relie', v_marque || jsonb_build_object('statut_avant', t.status))
          || case when nullif(btrim(coalesce(t.error, '')), '') is not null
                  then jsonb_build_object('erreurs_archivees', (case when jsonb_typeof(t.pf -> 'erreurs_archivees') = 'array' then t.pf -> 'erreurs_archivees' else '[]'::jsonb end)
                         || jsonb_build_array(jsonb_build_object('le', now(), 'statut', t.status, 'erreur', left(t.error, 600), 'par', v_pose)))
                  else '{}'::jsonb end;
        if t.action = 'publish' then
          v_msg := case when v_avec_num
                        then 'Annulée : article retiré partout depuis ton autre compte — vérifie qu''aucune annonce n''est restée en ligne.'
                        else 'Annulée à ta demande — rien n''a été publié.' end;
          update public.cross_post_jobs
             set status = 'cancelled', error = v_msg,
                 platform_fields = v_pf || jsonb_build_object('annulee_dans_la_file', jsonb_build_object('le', v_le, 'par', v_pose))
           where id = t.id and status = t.status;
          get diagnostics v_n = row_count;
          v_pub_j := v_pub_j + v_n;
          if t.status = 'failed' then v_ech_j := v_ech_j + v_n; end if;
          if v_avec_num and v_n > 0 then
            v_num_j := v_num_j || jsonb_build_array(jsonb_build_object('job', t.id, 'platform', t.platform, 'statut_avant', t.status));
          end if;
        else
          v_pf := v_pf || jsonb_build_object('hors_quota', true);
          v_supprime := public.republication_retrait_engage(t.pf);
          select d.id, coalesce(nullif(btrim(d.platform_listing_id), ''), public.annonce_id_de_job(d.platform_listing_id, d.listing_url)) as numero
            into v_retrait
            from public.cross_post_jobs d
           where d.user_id = v_jum.compte and d.platform = t.platform
             and d.action = 'delete' and d.status in ('pending', 'processing', 'needs_user', 'deleted')
             and d.created_at > now() - interval '30 days'
             and public.listing_designe(public.annonce_id_de_job(t.platform_listing_id, t.listing_url), d.listing_url, d.platform_listing_id)
           order by d.created_at desc
           limit 1;
          if v_supprime then
            update public.cross_post_jobs
               set status = 'cancelled',
                   error = 'Annulée : article retiré partout depuis ton autre compte — l''ancienne annonce est supprimée, la nouvelle ne sera pas publiée.',
                   platform_fields = v_pf || jsonb_build_object('republication_arretee_retrait_partout', jsonb_build_object(
                     'le', v_le, 'etape', coalesce(t.pf ->> 'republish_step', ''), 'par', v_pose))
             where id = t.id and status = t.status;
          elsif v_retrait.id is not null then
            update public.cross_post_jobs
               set status = 'cancelled',
                   error = 'Annonce retirée à ta demande : cette republication n''a plus d''objet. Rien n''a été retiré par elle, rien n''a été recréé.',
                   platform_fields = v_pf || jsonb_build_object('republication_retrait_demande', jsonb_build_object(
                     'le', v_le, 'retrait', v_retrait.id::text, 'annonce', coalesce(v_retrait.numero, ''), 'par', v_pose))
             where id = t.id and status = t.status;
          else
            update public.cross_post_jobs
               set status = 'cancelled', error = 'Annulée à ta demande — ton annonce est restée en ligne.',
                   platform_fields = v_pf || jsonb_build_object('annulee_dans_la_file', jsonb_build_object('le', v_le, 'par', v_pose))
             where id = t.id and status = t.status;
          end if;
          get diagnostics v_n = row_count;
          v_repub_j := v_repub_j + v_n;
          if coalesce(t.pf ->> 'republish_step', '') not in ('', 'a_capturer') or v_supprime then v_eng_j := v_eng_j + v_n; end if;
          if t.status = 'failed' then v_ech_j := v_ech_j + v_n; end if;
        end if;
        if v_n = 0 then
          v_lais_j := v_lais_j || jsonb_build_array(jsonb_build_object('job', t.id, 'platform', t.platform, 'action', t.action, 'statut', t.status, 'motif', 'changee_pendant_le_geste'));
        end if;
      exception when others then
        get stacked diagnostics v_err = message_text;
        raise warning 'armer_retraits_fiche_liee (fiche %, tâche %) : %', v_jum.fiche, t.id, v_err;
        v_lais_j := v_lais_j || jsonb_build_array(jsonb_build_object('job', t.id, 'platform', t.platform, 'action', t.action, 'statut', t.status, 'motif', 'erreur'));
        v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'taches_en_attente', 'job', t.id, 'erreur', left(v_err, 300)));
      end;
    end loop;

    if clock_timestamp() - v_debut > v_budget then
      v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'remises_en_vente', 'erreur', 'budget'));
    else
      begin
        update public.remises_en_vente r
           set statut = 'abandonnee', motif = 'retrait_partout_compte_relie', traite_le = now()
         where r.id in (select y.id from public.remises_en_vente y
                         where y.user_id = v_jum.compte and y.inventaire_id = v_jum.fiche and y.statut = 'a_faire'
                           and y.platform = any(v_part) and not (y.platform = any(v_doute_j))
                         for update skip locked);
        get diagnostics v_rem_j = row_count;
        select count(*) into v_restent from public.remises_en_vente y
         where y.user_id = v_jum.compte and y.inventaire_id = v_jum.fiche and y.statut = 'a_faire' and y.platform = any(v_part)
           and not (y.platform = any(v_doute_j));
        if v_restent > 0 then
          v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'remises_en_vente', 'erreur', 'verrou', 'restent', v_restent));
        end if;
        if 'leboncoin' = any(v_part) and not ('leboncoin' = any(v_doute_j)) then
          update public.cross_post_jobs x
             set platform_fields = coalesce(x.platform_fields, '{}'::jsonb)
                   || jsonb_build_object('arret_utilisateur', v_le, 'retrait_partout_compte_relie', v_marque || jsonb_build_object('statut_avant', x.status))
           where x.id in (select y.id from public.cross_post_jobs y
                           where y.user_id = v_jum.compte and y.inventaire_id = v_jum.fiche
                             and y.platform = 'leboncoin' and coalesce(y.action, 'publish') = 'publish'
                             and y.status in ('cancelled', 'failed')
                             and coalesce(y.platform_fields, '{}'::jsonb) ? 'remise_en_vente'
                             and not (coalesce(y.platform_fields, '{}'::jsonb) ? 'arret_utilisateur')
                             and y.created_at > now() - interval '14 days'
                           for update skip locked);
          get diagnostics v_mar_j = row_count;
        end if;
      exception when others then
        get stacked diagnostics v_err = message_text;
        raise warning 'armer_retraits_fiche_liee (fiche %, remises en vente) : %', v_jum.fiche, v_err;
        v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'remises_en_vente', 'erreur', left(v_err, 300)));
        v_rem_j := 0; v_mar_j := 0;
      end;
    end if;

    v_marque_neuve := false;
    v_fait := v_armes_j + v_deja_j + v_encours_j + v_pub_j + v_repub_j + v_rem_j > 0;
    begin
      if v_fait then
        insert into public.jumelles_retirees_partout (user_id, inventaire_id, de_compte, de_fiche, chemin, plateformes)
        values (v_jum.compte, v_jum.fiche, p_user, p_fiche, v_chemin, v_part)
        on conflict (user_id, inventaire_id) do nothing;
        get diagnostics v_n = row_count;
        v_marque_neuve := v_n > 0;
      end if;
    exception when others then
      get stacked diagnostics v_err = message_text;
      raise warning 'armer_retraits_fiche_liee (fiche %, marque) : %', v_jum.fiche, v_err;
      v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'marque', 'erreur', left(v_err, 300)));
    end;

    begin
      if v_armes_j > 0 then
        insert into public.usage_logs (user_id, feature, metadata)
        values (v_jum.compte, 'retrait_annonces', jsonb_build_object(
          'chemin', v_chemin,
          'plateformes', (select coalesce(jsonb_agg(p order by p), '[]'::jsonb) from unnest(v_pl_j) as p),
          'n_annonces', v_armes_j, 'n_articles', 1, 'article_id', v_jum.fiche::text,
          'de_fiche', p_fiche::text, 'de_compte', p_user,
          'publications_annulees', v_pub_j + v_repub_j));
      end if;
    exception when others then
      get stacked diagnostics v_err = message_text;
      raise warning 'armer_retraits_fiche_liee (fiche %, journal) : %', v_jum.fiche, v_err;
      v_err_j := v_err_j || jsonb_build_array(jsonb_build_object('etape', 'journal', 'erreur', left(v_err, 300)));
    end;
    begin
      if v_marque_neuve or v_armes_j + v_refus_j + v_q_j + v_pub_j + v_repub_j + v_rem_j + v_mar_j + v_hp_j
                           + jsonb_array_length(v_lais_j) + jsonb_array_length(v_gard_j) + jsonb_array_length(v_err_j) > 0 then
        insert into public.usage_logs (user_id, feature, metadata)
        values (v_jum.compte, 'retrait_partout_compte_relie', jsonb_build_object(
          'chemin', v_chemin, 'article_id', v_jum.fiche::text, 'de_fiche', p_fiche::text, 'de_compte', p_user,
          'plateformes_partagees', to_jsonb(v_part),
          'retraits', v_armes_j, 'refus', v_refus_j, 'questions', v_q_j, 'deja', v_deja_j,
          'publications_annulees', v_pub_j, 'republications_annulees', v_repub_j,
          'republications_engagees_annulees', v_eng_j, 'echouees_annulees', v_ech_j,
          'remises_closes', v_rem_j, 'remises_marquees', v_mar_j, 'hors_portee', v_hp_j,
          'plateformes_en_doute', to_jsonb(v_doute_j), 'taches_gardees_doute', v_gard_j, 'retrait_en_cours', v_encours_j,
          'retiree_partout', v_fait, 'marque', v_marque_neuve,
          'taches_laissees', v_lais_j, 'annulees_avec_numero', v_num_j, 'erreurs', v_err_j,
          'attente_avant_ms', round(extract(epoch from v_entree - v_debut) * 1000),
          'duree_ms', round(extract(epoch from clock_timestamp() - v_debut) * 1000)));
      end if;
    exception when others then
      get stacked diagnostics v_err = message_text;
      raise warning 'armer_retraits_fiche_liee (fiche %, bilan) : %', v_jum.fiche, v_err;
    end;

    perform set_config('request.jwt.claims', coalesce(v_jwt, ''), true);
    perform set_config('request.jwt.claim.sub', coalesce(v_sub, ''), true);

    v_armes := v_armes + v_armes_j; v_pl := v_pl || v_pl_j; v_refus := v_refus + v_refus_j; v_questions := v_questions + v_q_j;
    v_deja := v_deja + v_deja_j; v_pub := v_pub + v_pub_j; v_repub := v_repub + v_repub_j;
    v_remises := v_remises + v_rem_j; v_marquees := v_marquees + v_mar_j;
    v_laissees := v_laissees || v_lais_j; v_erreurs := v_erreurs || v_err_j;
  end loop;

  return jsonb_build_object('jumelles', v_jumelles, 'hors_portee', v_hors, 'armes', v_armes, 'plateformes', to_jsonb(v_pl),
    'refus', v_refus, 'questions', v_questions, 'deja', v_deja, 'publications_annulees', v_pub, 'republications_annulees', v_repub,
    'remises_closes', v_remises, 'remises_marquees', v_marquees, 'taches_laissees', v_laissees, 'erreurs', v_erreurs,
    'attente_avant_ms', round(extract(epoch from v_entree - v_debut) * 1000),
    'duree_ms', round(extract(epoch from clock_timestamp() - v_debut) * 1000));
end;
$function$

CREATE OR REPLACE FUNCTION public.cloud_etat(p_user uuid, p_maintenant timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_exige_un_palier CONSTANT boolean := false;
  v_now timestamptz := date_trunc('milliseconds', p_maintenant);
  v_is_cloud boolean; v_debut timestamptz; v_fin timestamptz; v_arrete boolean;
  v_periode timestamptz; v_arret_fp boolean;
  v_business boolean; v_pro boolean; v_premium boolean; v_comped boolean;
  v_essai_pris boolean; v_en_cours boolean; v_paye boolean; v_avec_formule boolean; v_palier_ok boolean;
  v_base jsonb;
BEGIN
  SELECT p.is_cloud, date_trunc('milliseconds', p.cloud_essai_debut), date_trunc('milliseconds', p.cloud_essai_fin),
         p.cloud_essai_arrete, date_trunc('milliseconds', p.cloud_periode_fin), p.cloud_arret_fin_periode,
         p.is_business, p.is_pro, p.is_premium, p.is_comped
    INTO v_is_cloud, v_debut, v_fin, v_arrete, v_periode, v_arret_fp, v_business, v_pro, v_premium, v_comped
    FROM public.profiles p WHERE p.id = p_user;
  v_essai_pris := v_debut IS NOT NULL;
  v_en_cours := v_debut IS NOT NULL AND v_fin IS NOT NULL AND v_debut <= v_now AND v_now < v_fin AND v_arrete IS NOT TRUE;
  v_paye := v_is_cloud IS TRUE;
  v_avec_formule := (v_business IS TRUE OR v_pro IS TRUE OR v_premium IS TRUE OR v_comped IS TRUE);
  v_palier_ok := NOT c_exige_un_palier OR v_avec_formule;
  v_base := jsonb_build_object(
    'essaiPris', v_essai_pris,
    'essaiArrete', v_essai_pris AND v_arrete IS TRUE,
    'essaiFin', CASE WHEN v_fin IS NULL THEN NULL
                     ELSE to_char(v_fin AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'joursRestants', NULL,
    'avecFormule', v_avec_formule,
    'periodeFin', CASE WHEN v_paye AND v_periode IS NOT NULL
                       THEN to_char(v_periode AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'arretPrevuLe', CASE WHEN v_paye AND v_arret_fp IS TRUE AND v_periode IS NOT NULL
                         THEN to_char(v_periode AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END);
  IF (v_paye OR v_en_cours) AND NOT v_palier_ok THEN
    RETURN v_base || jsonb_build_object('etat', 'suspendu', 'actif', false);
  END IF;
  IF v_paye THEN
    RETURN v_base || jsonb_build_object('etat', 'paye', 'actif', true);
  END IF;
  IF v_en_cours THEN
    RETURN v_base || jsonb_build_object('etat', 'essai', 'actif', true,
      'joursRestants', GREATEST(1, CEIL(EXTRACT(EPOCH FROM (v_fin - v_now)) / 86400)::integer));
  END IF;
  IF v_essai_pris AND (v_arrete IS TRUE OR (v_fin IS NOT NULL AND v_now >= v_fin)) THEN
    RETURN v_base || jsonb_build_object('etat', 'essai_termine', 'actif', false);
  END IF;
  RETURN v_base || jsonb_build_object('etat', 'aucun', 'actif', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.commandes_beebs_noter(p_rows jsonb, p_user uuid DEFAULT NULL::uuid, p_lecture jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '20s'
AS $function$
DECLARE
  v_user uuid;
  v_ecrit boolean;
  v_row jsonb;
  v_ref text;
  v_statut text;
  v_classe text;
  v_date timestamptz;
  v_produits jsonb;
  v_id text;
  v_jobs uuid[];
  v_job uuid;
  v_pf jsonb;
  v_stock boolean;
  v_lecture jsonb := '{}'::jsonb;
  v_bilan jsonb;
  c_recues int := 0; c_prouvees int := 0; c_deja int := 0; c_doute int := 0; c_sans_job int := 0;
  c_forme int := 0; c_annulees int := 0; c_levees int := 0; c_annulee_apres int := 0; c_inconnu int := 0;
  c_fiche_vendue int := 0; c_produits int := 0;
  v_detail jsonb := '[]'::jsonb; v_cmd jsonb; v_verdict text; v_fiche bigint; v_titre text; v_build text;
BEGIN
  IF auth.uid() IS NOT NULL AND p_user IS NOT NULL AND p_user <> auth.uid() THEN
    RAISE EXCEPTION 'utilisateur non autorisé';
  END IF;
  v_user := coalesce(auth.uid(), p_user);
  IF v_user IS NULL THEN RAISE EXCEPTION 'utilisateur inconnu'; END IF;
  v_ecrit := coalesce((SELECT c.value FROM coin_config c WHERE c.key = 'ventes_beebs_commandes'), 0) = 1;

  IF jsonb_typeof(p_lecture) = 'object' THEN
    SELECT coalesce(jsonb_object_agg(k, (p_lecture ->> k)::int), '{}'::jsonb) INTO v_lecture
      FROM unnest(ARRAY['liens', 'illisibles', 'requetes']) k
     WHERE coalesce(p_lecture ->> k, '') ~ '^[0-9]{1,6}$';
  END IF;

  IF jsonb_typeof(p_rows) = 'array' THEN
    FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows) LIMIT 10 LOOP
      c_recues := c_recues + 1;
      IF jsonb_typeof(v_row) IS DISTINCT FROM 'object' THEN
        c_forme := c_forme + 1;
        v_detail := v_detail || jsonb_build_array(jsonb_build_object('classe', 'forme_inconnue', 'motif', 'pas_un_objet'));
        CONTINUE;
      END IF;
      v_ref := btrim(coalesce(v_row ->> 'ref', ''));
      IF v_ref !~ '^[A-Za-z0-9_-]{1,80}$' THEN
        c_forme := c_forme + 1;
        v_detail := v_detail || jsonb_build_array(jsonb_build_object('ref', left(v_ref, 80), 'classe', 'forme_inconnue', 'motif', 'numero_de_commande'));
        CONTINUE;
      END IF;
      v_statut := left(btrim(coalesce(v_row ->> 'statut', v_row ->> 'etat_plateforme', '')), 60);
      v_classe := public.beebs_commande_classe(v_statut);
      v_date := coalesce(_ts_ou_null(v_row ->> 'date'), _ts_ou_null(v_row ->> 'vendue_le'));
      v_produits := CASE WHEN jsonb_typeof(v_row -> 'produits') = 'array' THEN v_row -> 'produits'
                         WHEN nullif(btrim(coalesce(v_row ->> 'annonce_ref', '')), '') IS NOT NULL
                           THEN jsonb_build_array(v_row ->> 'annonce_ref')
                         ELSE '[]'::jsonb END;
      v_cmd := jsonb_strip_nulls(jsonb_build_object('ref', v_ref, 'statut', v_statut, 'classe', v_classe, 'date', v_date,
                 'produits', '[]'::jsonb));

      IF v_classe = 'annulee' THEN
        c_annulees := c_annulees + 1;
        FOR v_job IN SELECT j.id FROM cross_post_jobs j
                      WHERE j.user_id = v_user AND j.platform = 'beebs' AND j.status = 'published'
                        AND j.platform_fields #>> '{sale_evidence,source}' = 'commande_beebs'
                        AND j.platform_fields #>> '{sale_evidence,commande}' = v_ref LOOP
          IF NOT v_ecrit THEN c_levees := c_levees + 1;
          ELSIF signal_vente_lever(v_job, 'commande_beebs_annulee', jsonb_build_object('commande', v_ref, 'statut', v_statut)) THEN
            c_levees := c_levees + 1;
          END IF;
        END LOOP;
        c_annulee_apres := c_annulee_apres + (SELECT count(*) FROM cross_post_jobs j
          WHERE j.user_id = v_user AND j.platform = 'beebs' AND j.status = 'sold'
            AND j.platform_fields #>> '{sale_evidence,source}' = 'commande_beebs'
            AND j.platform_fields #>> '{sale_evidence,commande}' = v_ref)::int;
        v_detail := v_detail || jsonb_build_array(v_cmd || jsonb_build_object('produits', v_produits));
        CONTINUE;
      END IF;
      IF v_classe <> 'vente' THEN
        c_inconnu := c_inconnu + 1;
        v_detail := v_detail || jsonb_build_array(v_cmd || jsonb_build_object('produits', v_produits));
        CONTINUE;
      END IF;

      FOR v_id IN SELECT btrim(x) FROM jsonb_array_elements_text(v_produits) x LIMIT 10 LOOP
        c_produits := c_produits + 1;
        v_verdict := NULL; v_job := NULL; v_fiche := NULL; v_titre := NULL;
        IF v_id !~ '^[0-9]{6,}$' THEN c_forme := c_forme + 1; v_verdict := 'forme_inconnue';
        ELSE
        SELECT array_agg(j.id) INTO v_jobs FROM cross_post_jobs j
         WHERE j.user_id = v_user AND j.platform = 'beebs' AND j.status = 'published'
           AND coalesce(j.action, 'publish') IN ('publish', 'republish')
           AND btrim(coalesce(j.platform_listing_id, '')) = v_id;
        IF coalesce(array_length(v_jobs, 1), 0) = 0 THEN
          IF EXISTS (SELECT 1 FROM cross_post_jobs j WHERE j.user_id = v_user AND j.platform = 'beebs'
                      AND j.status = 'sold' AND btrim(coalesce(j.platform_listing_id, '')) = v_id) THEN
            c_deja := c_deja + 1; v_verdict := 'deja_vendue';
          ELSE
            c_sans_job := c_sans_job + 1; v_verdict := 'sans_job';
          END IF;
        ELSIF array_length(v_jobs, 1) > 1 THEN c_doute := c_doute + 1; v_verdict := 'doute';
        ELSE
        v_job := v_jobs[1];
        SELECT j.platform_fields, (i.id IS NOT NULL AND i.statut = 'stock' AND i.fusionne_dans IS NULL), j.inventaire_id, left(j.title, 80)
          INTO v_pf, v_stock, v_fiche, v_titre
          FROM cross_post_jobs j LEFT JOIN inventaire i ON i.id = j.inventaire_id AND i.user_id = j.user_id
         WHERE j.id = v_job;
        IF coalesce(v_pf ->> 'sale_signal', '') = 'sold' AND v_pf #>> '{sale_evidence,listing_id}' = v_id
           AND v_pf #>> '{sale_evidence,platform}' = 'beebs' THEN
          c_deja := c_deja + 1; v_verdict := 'deja_prouvee';
        ELSIF NOT coalesce(v_stock, false) THEN c_fiche_vendue := c_fiche_vendue + 1; v_verdict := 'fiche_deja_vendue';
        ELSE
        c_prouvees := c_prouvees + 1;
        v_verdict := CASE WHEN v_ecrit THEN 'prouvee' ELSE 'aurait_prouve' END;
        IF v_ecrit THEN
          UPDATE cross_post_jobs c
             SET platform_fields = coalesce(c.platform_fields, '{}'::jsonb) || jsonb_build_object(
                   'sale_signal', 'sold',
                   'unavailable_since', coalesce(c.platform_fields ->> 'unavailable_since',
                                                 to_char(coalesce(v_date, now()) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')),
                   'sale_evidence', jsonb_build_object('platform', 'beebs', 'listing_id', v_id, 'state', 'sold', 'exact', true,
                     'source', 'commande_beebs', 'commande', v_ref, 'statut', v_statut, 'lu_le', now(), 'par', 'page_ventes_beebs'))
           WHERE c.id = v_job AND c.status = 'published';
        END IF;
        END IF;
        END IF;
        END IF;
        v_cmd := jsonb_set(v_cmd, '{produits}', coalesce(v_cmd -> 'produits', '[]'::jsonb) || jsonb_build_array(jsonb_strip_nulls(
                   jsonb_build_object('id', v_id, 'verdict', v_verdict, 'job', v_job, 'fiche', v_fiche::text, 'titre', v_titre))));
      END LOOP;
      v_detail := v_detail || jsonb_build_array(v_cmd);
    END LOOP;
  END IF;

  v_bilan := jsonb_build_object('mode', CASE WHEN v_ecrit THEN 'ecrit' ELSE 'fantome' END,
    'recues', c_recues, 'produits', c_produits, 'prouvees_ou_auraient', c_prouvees, 'deja', c_deja, 'doute', c_doute,
    'sans_job', c_sans_job, 'fiche_deja_vendue', c_fiche_vendue, 'forme_inconnue', c_forme, 'statut_inconnu', c_inconnu,
    'annulees', c_annulees, 'preuves_levees', c_levees, 'annulee_apres_vente', c_annulee_apres) || v_lecture;
  SELECT p.extension_build INTO v_build FROM profiles p WHERE p.id = v_user;
  IF jsonb_array_length(v_detail) > 0 THEN v_bilan := v_bilan || jsonb_build_object('commandes', v_detail); END IF;
  IF v_build IS NOT NULL THEN v_bilan := v_bilan || jsonb_build_object('build', left(v_build, 60)); END IF;
  IF c_recues > 0 OR NOT EXISTS (SELECT 1 FROM usage_logs u WHERE u.user_id = v_user AND u.feature = 'ventes_beebs_commandes'
                                    AND u.created_at > now() - interval '6 hours') THEN
    INSERT INTO usage_logs (user_id, feature, metadata) VALUES (v_user, 'ventes_beebs_commandes', v_bilan);
  END IF;
  RETURN v_bilan;
END;
$function$

CREATE OR REPLACE FUNCTION public.controler_job_extension(p_user uuid, p_poste text, p_job uuid, p_statut text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '2s'
 SET lock_timeout TO '500ms'
AS $function$
DECLARE j cross_post_jobs%ROWTYPE; r jobs_reservations_extension%ROWTYPE;
BEGIN
 IF p_user IS NULL OR nullif(p_poste,'') IS NULL OR length(p_poste)>180 THEN
  RETURN jsonb_build_object('ok',false,'reason','Session de ce poste indisponible. Reconnecte FillSell.'); END IF;
 SELECT * INTO j FROM cross_post_jobs WHERE id=p_job AND user_id=p_user FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','Job introuvable.'); END IF;
 IF j.status = 'cancelled' AND COALESCE(j.platform_fields, '{}'::jsonb) ? 'arret_utilisateur' THEN
  RETURN jsonb_build_object('ok',false,'reason','Arrêtée à ta demande : rien à faire.'); END IF;
 IF j.status = 'pending' AND COALESCE(j.platform_fields, '{}'::jsonb) ? 'attente_lecture_origine'
    AND p_statut IN ('processing', 'failed', 'needs_user', 'pending') THEN
  RETURN jsonb_build_object('ok',false,'reason','En cours de lecture de ton annonce d''origine : elle partira toute seule avec toutes ses photos. Rien à faire.'); END IF;
 IF j.status NOT IN ('pending','processing') THEN
  IF p_statut='processing' THEN RETURN jsonb_build_object('ok',false,'reason','Ce job n’est plus à exécuter. Actualise la file.'); END IF;
  RETURN jsonb_build_object('ok',true,'reservation',null,'statut',j.status);
 END IF;
 SELECT * INTO r FROM jobs_reservations_extension WHERE job_id=p_job FOR UPDATE;
 IF FOUND AND r.poste<>p_poste THEN
  RETURN jsonb_build_object('ok',false,'reason','Ce job est réservé à un autre poste. Rien à exécuter ici.'); END IF;
 IF r.job_id IS NULL THEN
  INSERT INTO jobs_reservations_extension(job_id,user_id,poste) VALUES(p_job,p_user,p_poste)
   RETURNING * INTO r;
 END IF;
 RETURN jsonb_build_object('ok',true,'reservation',r.reservation,'statut',j.status);
END;
$function$

CREATE OR REPLACE FUNCTION public.cross_post_job_settle_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.reservation_id IS NULL OR NEW.reservation_settled_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  IF NEW.status = 'published' THEN
    PERFORM settle_publish_reservation(NEW.reservation_id, 'capture');
    NEW.reservation_settled_at := now();
  ELSIF NEW.status IN ('failed', 'cancelled', 'sold') THEN
    PERFORM settle_publish_reservation(NEW.reservation_id, 'release');
    NEW.reservation_settled_at := now();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_alerte_tenue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_constat boolean;
  v_rep uuid;
  v_suiv record;
  v_jum record;
  v_retire text[] := array['unavailable_since', 'sale_signal', 'unavailable_pending_since', 'detected_price'];
  v_nom text;
begin
  if coalesce(current_setting('fillsell.restauration', true), '') = 'on' then return new; end if;
  if not (coalesce(new.platform_fields, '{}'::jsonb) ? 'unavailable_since')
     or coalesce(old.platform_fields, '{}'::jsonb) ? 'unavailable_since'
     or coalesce(new.platform_fields ->> 'sale_signal', 'unavailable') <> 'unavailable'
     or new.status is distinct from 'published'
     or coalesce(new.action, 'publish') not in ('publish', 'republish')
     or new.inventaire_id is null then
    return new;
  end if;
  v_nom := case new.platform when 'leboncoin' then 'Leboncoin' when 'beebs' then 'Beebs' when 'ebay' then 'eBay'
                             when 'depop' then 'Depop' when 'vinted' then 'Vinted' when 'opla' then 'Opla' else new.platform end;
  v_constat := new.platform_fields ? 'absence_releves'
               and (new.platform_fields -> 'absence_releves') is distinct from (coalesce(old.platform_fields, '{}'::jsonb) -> 'absence_releves');

  v_rep := coalesce(public.republication_engagee(new.user_id, new.inventaire_id, new.platform),
                    public.republication_engagee_numero(new.user_id, new.platform, public.annonce_id_de_job(new.platform_listing_id, new.listing_url)));
  if v_rep is not null and v_rep <> new.id then
    new.platform_fields := (new.platform_fields - v_retire - 'absence_releves')
      || jsonb_build_object('alerte_ecartee', jsonb_build_object('le', now(), 'motif', 'republication_en_cours',
           'republication', v_rep, 'constat', v_constat));
    return new;
  end if;

  v_rep := public.republication_recreee_non_confirmee(new.user_id, new.platform, new.inventaire_id,
             public.annonce_id_de_job(new.platform_listing_id, new.listing_url), new.id);
  if v_rep is not null then
    new.platform_fields := (new.platform_fields - v_retire - 'absence_releves')
      || jsonb_build_object('alerte_ecartee', jsonb_build_object('le', now(), 'motif', 'recreation_non_confirmee',
           'republication', v_rep, 'constat', v_constat));
    return new;
  end if;

  select r.id, btrim(r.platform_listing_id) as annonce into v_suiv
    from public.cross_post_jobs r
   where r.user_id = new.user_id and r.inventaire_id = new.inventaire_id and r.platform = new.platform
     and r.action = 'republish' and r.status = 'published' and r.id <> new.id
     and r.platform_fields ->> 'republish_source_job_id' = new.id::text
     and nullif(btrim(coalesce(r.platform_listing_id, '')), '') is not null
     and btrim(r.platform_listing_id) is distinct from nullif(btrim(coalesce(new.platform_listing_id, '')), '')
   order by r.created_at desc limit 1;
  if v_suiv.id is not null then
    new.platform_fields := (new.platform_fields - v_retire - 'absence_releves')
      || jsonb_build_object('republished_pending', true,
           'remplacee_par_republication', jsonb_build_object('le', now(), 'job', v_suiv.id, 'annonce', v_suiv.annonce));
    new.status := 'cancelled';
    new.error := 'Annonce remplacée par sa republication (nouvelle annonce ' || v_suiv.annonce || ') — ce n''est pas une vente.';
    return new;
  end if;

  if new.platform <> 'vinted' then
    select o.listing_id, o.compte into v_jum
      from public.jumelle_occupe_plateformes(new.user_id, new.inventaire_id) o
     where o.platform = new.platform and o.statut in ('en_ligne', 'en_verification', 'published')
       and o.listing_id is distinct from nullif(btrim(coalesce(new.platform_listing_id, '')), '')
     limit 1;
    if v_jum.listing_id is not null then
      if v_constat then
        new.platform_fields := (new.platform_fields - v_retire)
          || jsonb_build_object('copie_remplacee_par_compte_relie', jsonb_build_object('le', now(),
               'annonce', v_jum.listing_id, 'compte', v_jum.compte));
        new.status := 'cancelled';
        new.error := 'Cette annonce ' || v_nom || ' n''est plus en ligne ; ton article reste en vente sur ' || v_nom
          || ' sous l''annonce ' || v_jum.listing_id || ' de ton compte FillSell relié (même boutique). Rien à refaire.';
      else
        new.platform_fields := (new.platform_fields - array['unavailable_since', 'sale_signal', 'detected_price'])
          || jsonb_build_object('unavailable_pending_since', new.platform_fields ->> 'unavailable_since',
               'alerte_a_confirmer_par_releve', jsonb_build_object('le', now(), 'motif', 'jumelle_en_ligne',
                 'annonce', v_jum.listing_id));
      end if;
      return new;
    end if;
  end if;

  if not v_constat and new.platform <> 'vinted'
     and coalesce(old.platform_fields, '{}'::jsonb) ? 'revue_en_ligne_par_releve' then
    new.platform_fields := (new.platform_fields - array['unavailable_since', 'sale_signal', 'detected_price'])
      || jsonb_build_object('unavailable_pending_since', new.platform_fields ->> 'unavailable_since',
           'alerte_a_confirmer_par_releve', jsonb_build_object('le', now(), 'motif', 'dementie_par_releve',
             'dementie_le', old.platform_fields #>> '{revue_en_ligne_par_releve,at}'));
    return new;
  end if;
  return new;
exception when others then
  raise warning 'cross_post_jobs_alerte_tenue : job % : % — écriture inchangée', new.id, sqlerrm;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_compte_signal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  BEGIN
    IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.user_id IS NOT NULL
       AND (TG_OP = 'DELETE' OR OLD.user_id IS DISTINCT FROM NEW.user_id
            OR OLD.status IS DISTINCT FROM NEW.status OR OLD.action IS DISTINCT FROM NEW.action) THEN
      PERFORM public.compte_signal_ajuster(OLD.user_id, COALESCE(OLD.action, '?') || '|' || COALESCE(OLD.status, '?'), -1);
    END IF;
    IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.user_id IS NOT NULL
       AND (TG_OP = 'INSERT' OR OLD.user_id IS DISTINCT FROM NEW.user_id
            OR OLD.status IS DISTINCT FROM NEW.status OR OLD.action IS DISTINCT FROM NEW.action) THEN
      PERFORM public.compte_signal_ajuster(NEW.user_id, COALESCE(NEW.action, '?') || '|' || COALESCE(NEW.status, '?'), 1);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      UPDATE public.compte_signal SET jobs = NULL, maj_le = now()
       WHERE user_id IN (COALESCE(NEW.user_id, OLD.user_id), COALESCE(OLD.user_id, NEW.user_id));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RAISE WARNING 'cross_post_jobs_compte_signal : % — compteurs du compte mis à inconnu', SQLERRM;
  END;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_lbc_vendu_avant_suivi()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_premiere timestamptz;
BEGIN
  IF TG_OP = 'UPDATE' AND COALESCE(OLD.platform_fields ->> 'sale_signal', '') = 'sold' THEN RETURN NEW; END IF;
  IF NULLIF(btrim(COALESCE(NEW.platform_listing_id, '')), '') IS NULL THEN RETURN NEW; END IF;
  IF NOT (COALESCE(NEW.platform_fields ->> 'source', '') = 'releve'
          OR COALESCE(NEW.platform_fields #>> '{rattachement,import}', '') = 'true') THEN
    RETURN NEW;
  END IF;
  BEGIN
    IF public.leboncoin_vendu_avant_suivi(NEW.user_id, NEW.platform_listing_id) THEN
      SELECT min(u.created_at) INTO v_premiere FROM public.usage_logs u
       WHERE u.user_id = NEW.user_id AND u.feature = 'vente_leboncoin_transaction'
         AND u.metadata ->> 'listing_id' = btrim(NEW.platform_listing_id);
      NEW.platform_fields := (NEW.platform_fields
          - ARRAY['sale_signal', 'unavailable_since', 'unavailable_pending_since', 'detected_price', 'sale_evidence'])
        || jsonb_build_object('vendu_avant_suivi', jsonb_build_object(
             'le', now(), 'listing_id', btrim(NEW.platform_listing_id), 'premiere_lecture', v_premiere,
             'motif', 'leboncoin_vendu_des_la_premiere_lecture'));
      IF TG_OP = 'INSERT' OR NOT (COALESCE(OLD.platform_fields, '{}'::jsonb) ? 'vendu_avant_suivi') THEN
        INSERT INTO public.usage_logs (user_id, feature, metadata)
        VALUES (NEW.user_id, 'vente_leboncoin_ancienne_ecartee', jsonb_build_object(
          'job', NEW.id, 'listing_id', btrim(NEW.platform_listing_id), 'premiere_lecture', v_premiere));
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'cross_post_jobs_lbc_vendu_avant_suivi (job %) : %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_lien_jamais_croise()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_new   text;
  v_old   text;
  v_cert  text;
  v_motif text;
BEGIN
  IF NEW.inventaire_id IS NULL OR COALESCE(NEW.action, 'publish') NOT IN ('publish', 'republish') THEN RETURN NEW; END IF;
  IF COALESCE(current_setting('fillsell.lien_decide_par_utilisateur', true), '') = 'on' THEN RETURN NEW; END IF;
  v_new := COALESCE(annonce_id_job(NEW.platform, NEW.listing_url), NULLIF(btrim(NEW.platform_listing_id), ''));
  v_old := COALESCE(annonce_id_job(OLD.platform, OLD.listing_url), NULLIF(btrim(OLD.platform_listing_id), ''));
  IF v_new IS NULL OR v_new IS NOT DISTINCT FROM v_old THEN RETURN NEW; END IF;

  IF NEW.platform = 'leboncoin' THEN
    v_cert := COALESCE(NULLIF(btrim(NEW.platform_fields #>> '{lbc_depot,adsubmit,id}'), ''),
                       NULLIF(btrim(NEW.platform_fields #>> '{lbc_depot,sans_adsubmit,id}'), ''));
    IF v_cert IS NOT NULL AND v_cert !~ '^\d{6,}$' THEN v_cert := NULL; END IF;
  END IF;

  IF v_cert IS NOT NULL THEN
    IF v_new = v_cert THEN RETURN NEW; END IF;
    v_motif := 'identifiant_certain_different';
  ELSIF EXISTS (SELECT 1 FROM annonces_plateforme a
                 WHERE a.user_id = NEW.user_id AND a.platform = NEW.platform AND a.listing_id = v_new
                   AND a.inventaire_id IS NOT NULL AND a.inventaire_id <> NEW.inventaire_id
                   AND a.disparu_le IS NULL AND a.retiree_le IS NULL) THEN
    v_motif := 'annonce_rattachee_a_un_autre_article';
  ELSIF EXISTS (SELECT 1 FROM cross_post_jobs o
                 WHERE o.user_id = NEW.user_id AND o.platform = NEW.platform AND o.id <> NEW.id
                   AND o.inventaire_id IS NOT NULL AND o.inventaire_id <> NEW.inventaire_id
                   AND o.status = 'published' AND COALESCE(o.action, 'publish') IN ('publish', 'republish')
                   AND listing_designe(v_new, o.listing_url, o.platform_listing_id)) THEN
    v_motif := 'annonce_portee_par_un_autre_article';
  ELSE
    RETURN NEW;
  END IF;

  IF NEW.action = 'republish' AND NEW.status = 'published' AND OLD.status IS DISTINCT FROM 'published' THEN
    NEW.listing_url := NULL;
    NEW.platform_listing_id := v_cert;
  ELSE
    NEW.listing_url := OLD.listing_url;
    NEW.platform_listing_id := COALESCE(v_cert, OLD.platform_listing_id);
  END IF;
  NEW.platform_fields := COALESCE(NEW.platform_fields, '{}'::jsonb)
    || jsonb_build_object('lien_refuse', jsonb_build_object('le', now(), 'id_propose', v_new, 'motif', v_motif));
  RAISE WARNING 'cross_post_jobs_lien_jamais_croise : job % — annonce % refusée (%)', NEW.id, v_new, v_motif;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_lien_numero_beebs()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_url text;
BEGIN
  v_url := 'https://www.beebs.app/fr/p/' || btrim(NEW.platform_listing_id);
  IF NULLIF(btrim(COALESCE(NEW.listing_url, '')), '') IS NULL THEN
    NEW.listing_url := v_url;
    NEW.platform_fields := COALESCE(NEW.platform_fields, '{}'::jsonb)
      || jsonb_build_object('lien_depuis_numero', jsonb_build_object('le', now(), 'numero', btrim(NEW.platform_listing_id)));
  END IF;
  IF NEW.action = 'republish' AND NULLIF(btrim(COALESCE(NEW.platform_fields ->> 'new_listing_url', '')), '') IS NULL THEN
    NEW.platform_fields := COALESCE(NEW.platform_fields, '{}'::jsonb) || jsonb_build_object('new_listing_url', v_url);
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_lien_suit_identifiant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_url_id     text;
  v_pid        text;
  v_cert       text;
  v_url        text;
  v_lien_avant text;
  v_url_change boolean;
  v_pid_change boolean;
BEGIN
  IF COALESCE(NEW.action, 'publish') NOT IN ('publish', 'republish') THEN RETURN NEW; END IF;
  v_url_id := annonce_id_job(NEW.platform, NEW.listing_url);
  v_pid := NULLIF(btrim(NEW.platform_listing_id), '');
  IF v_url_id IS NULL OR v_pid IS NULL OR v_url_id = v_pid THEN RETURN NEW; END IF;

  IF TG_OP = 'UPDATE' THEN
    v_url_change := NEW.listing_url IS DISTINCT FROM OLD.listing_url;
    v_pid_change := NEW.platform_listing_id IS DISTINCT FROM OLD.platform_listing_id;
  ELSE
    v_url_change := true; v_pid_change := true;
  END IF;

  IF NEW.platform = 'leboncoin' THEN
    v_cert := COALESCE(NULLIF(btrim(NEW.platform_fields #>> '{lbc_depot,adsubmit,id}'), ''),
                       NULLIF(btrim(NEW.platform_fields #>> '{lbc_depot,sans_adsubmit,id}'), ''));
    IF v_cert IS NOT NULL AND v_cert !~ '^\d{6,}$' THEN v_cert := NULL; END IF;
  END IF;
  IF v_cert IS NULL THEN
    v_cert := CASE WHEN v_url_change AND NOT v_pid_change THEN v_url_id ELSE v_pid END;
  END IF;

  v_lien_avant := NEW.listing_url;
  IF v_url_id <> v_cert THEN
    SELECT a.url INTO v_url
      FROM annonces_plateforme a
     WHERE a.user_id = NEW.user_id AND a.platform = NEW.platform AND a.listing_id = v_cert
       AND NULLIF(btrim(a.url), '') IS NOT NULL
     ORDER BY a.vu_le DESC NULLS LAST
     LIMIT 1;
    NEW.listing_url := v_url;
  END IF;
  IF v_pid <> v_cert THEN NEW.platform_listing_id := v_cert; END IF;
  NEW.platform_fields := COALESCE(NEW.platform_fields, '{}'::jsonb) || jsonb_build_object('lien_suit_identifiant',
    jsonb_build_object('le', now(), 'op', TG_OP, 'retenu', v_cert, 'identifiant_avant', v_pid,
                       'lien_avant', v_lien_avant, 'lien_apres', NEW.listing_url));
  RAISE WARNING 'cross_post_jobs_lien_suit_identifiant : job % — lien % / identifiant % → %', NEW.id, v_url_id, v_pid, v_cert;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_needs_user_motif()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pf     jsonb;
  v_champ  boolean;
  v_source text;
BEGIN
  IF NEW.status IS DISTINCT FROM 'needs_user' THEN RETURN NEW; END IF;
  v_pf := COALESCE(NEW.platform_fields, '{}'::jsonb);
  IF NULLIF(btrim(v_pf ->> 'needs_user_source'), '') IS NOT NULL THEN RETURN NEW; END IF;
  v_champ :=
       NULLIF(btrim(v_pf #>> '{needsUserField,field_key}'), '') IS NOT NULL
    OR (jsonb_typeof(v_pf -> 'needsUserFields') = 'array' AND jsonb_array_length(v_pf -> 'needsUserFields') > 0)
    OR (jsonb_typeof(v_pf -> 'champs_a_completer') = 'array' AND jsonb_array_length(v_pf -> 'champs_a_completer') > 0)
    OR (jsonb_typeof(v_pf -> 'server_required_fields') = 'array' AND jsonb_array_length(v_pf -> 'server_required_fields') > 0);
  v_source := CASE WHEN v_champ THEN 'champ_a_choisir' ELSE 'relancer' END;
  NEW.platform_fields := v_pf || jsonb_build_object(
    'needs_user_source', v_source,
    'needs_user_sans_motif', jsonb_build_object(
      'le', now(), 'source_posee', v_source, 'message', left(COALESCE(NEW.error, ''), 300),
      'par', 'trigger cross_post_jobs_needs_user_motif'));
  RAISE LOG 'cross_post_jobs_needs_user_motif : job % (% %) needs_user SANS MOTIF — source « % » posée par défaut : %',
    NEW.id, NEW.platform, COALESCE(NEW.action, 'publish'), v_source, left(COALESCE(NEW.error, ''), 160);
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_preuve_vente_retire_copies()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_q   integer;
  v_fus bigint;
begin
  if coalesce(current_setting('fillsell.sans_retrait', true), '') = '1' then
    return new;
  end if;
  begin
    select i.quantite, i.fusionne_dans into v_q, v_fus
      from public.inventaire i where i.id = new.inventaire_id;
    if not found or v_fus is not null then
      return new;
    end if;
    if coalesce(v_q, 1) > 1 then
      return new;
    end if;
    perform public.armer_retraits_copies(new.inventaire_id, 'preuve_vente_serveur', new.id, new.platform, interval '0');
  exception when others then
    raise warning 'cross_post_jobs_preuve_vente_retire_copies (job %) : %', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_publie_sur_article_vendu()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_vendu boolean;
begin
  if coalesce(current_setting('fillsell.sans_retrait', true), '') = '1' then
    return new;
  end if;
  if public.annonce_importee(new.id) then
    return new;
  end if;
  begin
    v_vendu := public.article_vendu(new.inventaire_id);
    if not v_vendu then
      select exists (
        select 1 from public.cross_post_jobs s
          join public.inventaire i on i.id = s.inventaire_id
         where s.inventaire_id = new.inventaire_id and s.id <> new.id
           and s.status = 'published'
           and coalesce(s.action, 'publish') in ('publish', 'republish')
           and (s.platform_fields ->> 'sale_signal') = 'sold'
           and coalesce(i.quantite, 1) <= 1
           and i.fusionne_dans is null)
        into v_vendu;
    end if;
    if v_vendu then
      if public.armer_retrait_job(new.id, 'publie_apres_vente_serveur', interval '0') is not null then
        insert into public.usage_logs (user_id, feature, metadata)
        values (new.user_id, 'retrait_annonces', jsonb_build_object(
          'chemin', 'publie_apres_vente_serveur', 'plateformes', jsonb_build_array(new.platform),
          'n_annonces', 1, 'n_articles', 1, 'article_id', new.inventaire_id::text, 'job_publie', new.id));
      end if;
    end if;
  exception when others then
    raise warning 'cross_post_jobs_publie_sur_article_vendu (job %) : %', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_rattacher_republication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pf      text := lower(COALESCE(NEW.platform, ''));
  v_neuf    text;
  v_ancien  text;
  v_titre   text;
BEGIN
  IF NEW.action <> 'republish' OR NEW.status <> 'published' THEN RETURN NEW; END IF;
  IF v_pf NOT IN ('leboncoin', 'beebs', 'opla', 'depop') THEN RETURN NEW; END IF;

  BEGIN
    v_neuf := COALESCE(NULLIF(trim(NEW.platform_listing_id), ''),
                       annonce_id_depuis_url(v_pf, NEW.listing_url));
    IF v_neuf IS NULL THEN RETURN NEW; END IF;

    v_ancien := COALESCE(
      NULLIF(trim(NEW.platform_fields ->> 'old_platform_listing_id'), ''),
      annonce_id_depuis_url(v_pf, NEW.platform_fields ->> 'old_listing_url'));

    IF v_ancien IS NOT NULL AND v_ancien <> v_neuf THEN
      UPDATE annonces_plateforme
         SET disparu_le = COALESCE(disparu_le, now()), updated_at = now()
       WHERE user_id = NEW.user_id AND platform = v_pf AND listing_id = v_ancien;
    END IF;

    SELECT i.titre INTO v_titre FROM inventaire i WHERE i.id = NEW.inventaire_id;

    INSERT INTO annonces_plateforme
      (user_id, platform, listing_id, url, titre, prix, statut_plateforme,
       inventaire_id, job_id, source_rapprochement, proposition, vu_le, disparu_le)
    VALUES
      (NEW.user_id, v_pf, v_neuf, NEW.listing_url, COALESCE(NEW.title, v_titre), NEW.price,
       'en_ligne', NEW.inventaire_id, NEW.id, 'job', NULL, now(), NULL)
    ON CONFLICT (user_id, platform, listing_id) DO UPDATE SET
      url                  = COALESCE(EXCLUDED.url, annonces_plateforme.url),
      titre                = COALESCE(EXCLUDED.titre, annonces_plateforme.titre),
      prix                 = COALESCE(EXCLUDED.prix, annonces_plateforme.prix),
      statut_plateforme    = 'en_ligne',
      inventaire_id        = EXCLUDED.inventaire_id,
      job_id               = EXCLUDED.job_id,
      source_rapprochement = 'job',
      proposition          = NULL,
      vu_le                = now(),
      disparu_le           = NULL,
      updated_at           = now();
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'rattachement republication job % (%): %', NEW.id, v_pf, SQLERRM;
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_retrait_apres_publication_lien()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '3s'
AS $function$
declare
  v_pose    constant text := 'cross_post_jobs_retrait_apres_publication_lien (serveur)';
  v_chemin  constant text := 'publication_apres_retrait';
  v_le      text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  v_pfn     jsonb := coalesce(new.platform_fields, '{}'::jsonb);
  v_pfo     jsonb := coalesce(old.platform_fields, '{}'::jsonb);
  v_att     jsonb := coalesce(v_pfn -> 'retrait_apres_publication_attendu', v_pfo -> 'retrait_apres_publication_attendu', '{}'::jsonb);
  v_url     text := nullif(btrim(coalesce(new.listing_url, '')), '');
  v_num     text := nullif(btrim(coalesce(new.platform_listing_id, '')), '');
  v_anciens text[];
  v_preuve  text;
  v_existant uuid;
  v_del     uuid;
  v_statut  text;
  v_pfr     jsonb;
begin
  begin
    if v_url is not null then
      v_num := coalesce(nullif(btrim(coalesce(public.identifiant_annonce_depuis_lien(new.platform, v_url), '')), ''), v_num);
    end if;
    v_anciens := array_remove(array[
      nullif(btrim(coalesce(v_pfn ->> 'old_platform_listing_id', v_pfo ->> 'old_platform_listing_id', '')), ''),
      public.identifiant_annonce_depuis_lien(new.platform, coalesce(v_pfn ->> 'old_listing_url', v_pfo ->> 'old_listing_url')),
      nullif(btrim(coalesce(v_pfn -> 'republish_snapshot' ->> 'platform_listing_id', v_pfo -> 'republish_snapshot' ->> 'platform_listing_id', '')), ''),
      public.identifiant_annonce_depuis_lien(new.platform, coalesce(v_pfn -> 'republish_snapshot' ->> 'listing_url', v_pfo -> 'republish_snapshot' ->> 'listing_url'))
    ], null);
    if v_num is null or v_num = any (v_anciens) then
      return null;
    end if;
    v_preuve := case
      when (v_pfn -> 'lien_retrouve_par_identifiant') is not null
           and (v_pfn -> 'lien_retrouve_par_identifiant') is distinct from (v_pfo -> 'lien_retrouve_par_identifiant') then 'lien_retrouve_par_identifiant'
      when (v_pfn -> 'preuve_identifiant_beebs_acceptee') is not null
           and (v_pfn -> 'preuve_identifiant_beebs_acceptee') is distinct from (v_pfo -> 'preuve_identifiant_beebs_acceptee') then 'preuve_identifiant_beebs_acceptee'
    end;
    if v_preuve is null then
      update public.cross_post_jobs
         set platform_fields = coalesce(platform_fields, '{}'::jsonb) || jsonb_build_object('retrait_apres_publication_attendu',
               v_att || jsonb_build_object('lien_non_prouve', jsonb_build_object('le', v_le, 'numero', v_num,
                 'titre', (v_pfn -> 'listing_url_recovery') is distinct from (v_pfo -> 'listing_url_recovery'))))
       where id = new.id;
      return null;
    end if;
    if v_url is null and new.platform = 'leboncoin' and v_num ~ '^\d{6,}$' then
      v_url := 'https://www.leboncoin.fr/ad/vetements/' || v_num;
    elsif v_url is null and new.platform = 'vinted' and v_num ~ '^\d{6,}$' then
      v_url := 'https://www.vinted.fr/items/' || v_num;
    end if;
    select d.id into v_existant
      from public.cross_post_jobs d
     where d.user_id = new.user_id and d.platform = new.platform and d.action = 'delete'
       and d.status in ('pending', 'processing', 'needs_user')
       and (d.platform_listing_id = v_num or (v_url is not null and d.listing_url = v_url))
     limit 1;
    if v_existant is null then
      v_pfr := jsonb_build_object('arme_par', jsonb_build_object('chemin', v_chemin, 'motif', coalesce(v_att ->> 'motif', ''),
                 'le', now(), 'depot', new.id, 'pose_par', v_pose, 'preuve_identite', v_preuve));
      if new.platform = 'vinted' and nullif(btrim(coalesce(v_pfn ->> 'vinted_account_id', '')), '') is not null then
        v_pfr := v_pfr || jsonb_build_object('vinted_account_id', btrim(v_pfn ->> 'vinted_account_id'));
      end if;
      if new.platform = 'depop' and coalesce(v_pfn ->> 'depop_product_id', '') ~ '^[0-9]+$' then
        v_pfr := v_pfr || jsonb_build_object('depop_product_id', v_pfn -> 'depop_product_id');
      end if;
      insert into public.cross_post_jobs
        (user_id, inventaire_id, platform, action, status, photo_option, title, listing_url, platform_listing_id, platform_fields)
      values
        (new.user_id, new.inventaire_id, new.platform, 'delete', 'pending', 'original', left(coalesce(new.title, ''), 200), v_url, v_num, v_pfr)
      returning id, status into v_del, v_statut;
      if v_del is null or v_statut not in ('pending', 'needs_user') then
        update public.cross_post_jobs
           set platform_fields = coalesce(platform_fields, '{}'::jsonb) || jsonb_build_object('retrait_apres_publication_attendu',
                 v_att || jsonb_build_object('retrait_ne_clos', jsonb_build_object('le', v_le, 'retrait', v_del, 'statut', v_statut)))
         where id = new.id;
        return null;
      end if;
    else
      v_del := v_existant;
    end if;
    update public.cross_post_jobs
       set platform_fields = (coalesce(platform_fields, '{}'::jsonb) - 'retrait_apres_publication_attendu')
             || jsonb_build_object('pending_removal', false,
                  'retrait_arme', jsonb_build_object('job', v_del, 'le', v_le, 'chemin', v_chemin),
                  'retrait_apres_publication', jsonb_build_object('le', v_le, 'motif', coalesce(v_att ->> 'motif', ''), 'retrait', v_del,
                    'par', v_pose, 'preuve_identite', v_preuve, 'deja_ouvert', v_existant is not null))
     where id = new.id;
    if v_existant is null then
      insert into public.usage_logs (user_id, feature, metadata)
      values (new.user_id, 'retrait_annonces', jsonb_build_object('chemin', v_chemin, 'plateformes', jsonb_build_array(new.platform),
        'n_annonces', 1, 'n_articles', 1, 'article_id', new.inventaire_id::text, 'motif', coalesce(v_att ->> 'motif', ''),
        'depot', new.id, 'retrait', v_del, 'par', v_pose, 'preuve_identite', v_preuve));
    end if;
  exception when others then
    raise warning 'cross_post_jobs_retrait_apres_publication_lien (tâche %) : %', new.id, sqlerrm;
  end;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_retrait_vinted_ferme_fiche()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item text;
begin
  begin
    v_item := coalesce(case when new.platform_listing_id ~ '^\d+$' then new.platform_listing_id end,
                       substring(new.listing_url from '/items/(\d+)'));
    if v_item is null or new.inventaire_id is null then
      return new;
    end if;
    update public.inventaire i
       set disparu_le = coalesce(i.disparu_le, now()),
           vinted_status = case when i.vinted_status = 'sold' then i.vinted_status else 'closed' end
     where i.id = new.inventaire_id and i.user_id = new.user_id and i.vinted_item_id = v_item;
  exception when others then
    raise warning 'cross_post_jobs_retrait_vinted_ferme_fiche (job %) : %', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_signal_vente_vu_en_ligne()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_lid text; v_snap record;
BEGIN
  BEGIN
    IF NEW.status IS DISTINCT FROM 'published' OR coalesce(NEW.action, 'publish') NOT IN ('publish', 'republish') THEN RETURN NEW; END IF;
    IF coalesce(OLD.platform_fields ->> 'sale_signal', '') = 'sold' THEN RETURN NEW; END IF;
    v_lid := nullif(btrim(coalesce(NEW.platform_listing_id, '')), '');
    IF v_lid IS NULL THEN RETURN NEW; END IF;
    SELECT s.status, s.captured_at INTO v_snap FROM public.vinted_listing_snapshots s
     WHERE s.user_id = NEW.user_id AND s.vinted_item_id = v_lid
     ORDER BY s.captured_at DESC LIMIT 1;
    IF v_snap.status IS DISTINCT FROM 'active' THEN RETURN NEW; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.vinted_sync_runs r
                    WHERE r.user_id = NEW.user_id AND r.kind = 'dressing' AND r.status = 'running'
                      AND r.started_at <= v_snap.captured_at) THEN
      RETURN NEW;
    END IF;
    NEW.platform_fields := (NEW.platform_fields
        - ARRAY['sale_signal', 'unavailable_since', 'unavailable_pending_since', 'detected_price'])
      || jsonb_build_object('signal_refuse_annonce_en_ligne', jsonb_build_object(
           'le', now(), 'releve_le', v_snap.captured_at, 'signal', 'sold',
           'depuis', NEW.platform_fields ->> 'unavailable_since',
           'motif', 'la synchro du dressing en cours voit cette annonce en ligne'));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'cross_post_jobs_signal_vente_vu_en_ligne (job %) : % — écriture d''origine conservée', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$function$

