CREATE OR REPLACE FUNCTION public.cross_post_jobs_voie_ebay()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_flag boolean;
  v_ok boolean;
  v_ident text;
  v_import boolean;
  v_api boolean;
BEGIN
  IF NEW.platform IS DISTINCT FROM 'ebay' THEN RETURN NEW; END IF;

  v_ident := COALESCE(substring(btrim(COALESCE(NEW.platform_listing_id, '')) from '^(\d{9,})$'),
                      substring(COALESCE(NEW.listing_url, '') from '/itm/(?:[^/?#]*/)?(\d{9,})'));

  IF COALESCE(NEW.action, 'publish') = 'publish' THEN
    v_import := COALESCE(NEW.handler_build, '') NOT ILIKE 'ebay-api-worker%'
            AND (COALESCE(NEW.handler_build, '') ~* 'sync-dressing|releve-annonces'
                 OR COALESCE(NEW.platform_fields ->> 'source', '') = 'releve'
                 OR COALESCE(NEW.platform_fields #>> '{rattachement,import}', '') = 'true'
                 OR COALESCE(NEW.status, 'pending') NOT IN ('pending', 'needs_user'));
    IF v_import THEN
      NEW.voie := CASE WHEN ebay_annonce_creee_par_api(NEW.user_id, v_ident) THEN 'api' ELSE 'extension' END;
      RETURN NEW;
    END IF;
    IF NEW.voie IS DISTINCT FROM 'extension' THEN RETURN NEW; END IF;
    SELECT p.ebay_voie_api INTO v_flag FROM profiles p WHERE p.id = NEW.user_id;
    IF NOT COALESCE(v_flag, false) THEN RETURN NEW; END IF;
    SELECT (a.revoked_at IS NULL)
      INTO v_ok
      FROM ebay_accounts a WHERE a.user_id = NEW.user_id;
    IF COALESCE(v_ok, false) THEN NEW.voie := 'api'; END IF;

  ELSIF NEW.action IN ('delete', 'republish') THEN
    IF v_ident IS NOT NULL THEN
      v_api := ebay_annonce_creee_par_api(NEW.user_id, v_ident);
    ELSIF NEW.inventaire_id IS NOT NULL THEN
      SELECT (j.voie = 'api' AND COALESCE(j.handler_build, '') ILIKE 'ebay-api-worker%')
        INTO v_api
        FROM cross_post_jobs j
       WHERE j.user_id = NEW.user_id
         AND j.platform = 'ebay'
         AND j.inventaire_id = NEW.inventaire_id
         AND j.action IN ('publish', 'republish')
         AND j.status IN ('published', 'sold', 'cancelled', 'deleted')
       ORDER BY COALESCE(j.published_at, j.created_at) DESC
       LIMIT 1;
    END IF;
    NEW.voie := CASE WHEN COALESCE(v_api, false) THEN 'api' ELSE 'extension' END;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_voie_stable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.voie IS NOT DISTINCT FROM OLD.voie THEN RETURN NEW; END IF;
  IF OLD.voie = 'extension' AND NEW.voie = 'api' AND OLD.status IN ('pending', 'needs_user') THEN
    RETURN NEW;
  END IF;
  IF current_setting('fillsell.voie_reetiquetage', true) = 'on' THEN
    RETURN NEW;
  END IF;
  RAISE WARNING 'cross_post_jobs_voie_stable : job % — bascule % → % refusée (statut %)', OLD.id, OLD.voie, NEW.voie, OLD.status;
  NEW.voie := OLD.voie;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.cross_post_jobs_vue_ou_pas_encore_visible()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pev jsonb;
begin
  if coalesce(current_setting('fillsell.restauration', true), '') = 'on' then return new; end if;
  if new.platform_fields ? 'pas_encore_visible' and new.vu_en_ligne_le is not null then
    new.platform_fields := new.platform_fields - 'pas_encore_visible';
    return new;
  end if;
  if new.platform_fields ? 'unavailable_since'
     and not (coalesce(old.platform_fields, '{}'::jsonb) ? 'unavailable_since')
     and coalesce(new.platform_fields ->> 'sale_signal', 'unavailable') = 'unavailable'
     and new.status = 'published' and coalesce(new.action, 'publish') = 'publish'
     and public.job_jamais_vu_en_ligne(new.id, new.user_id, new.platform, new.vu_en_ligne_le,
                                       new.platform_listing_id, new.listing_url, new.platform_fields) then
    v_pev := coalesce(old.platform_fields -> 'pas_encore_visible', '{}'::jsonb);
    new.platform_fields := (new.platform_fields - array['unavailable_since', 'sale_signal', 'unavailable_pending_since'])
      || jsonb_build_object('pas_encore_visible', jsonb_build_object(
           'depuis', coalesce(v_pev -> 'depuis', to_jsonb(now())),
           'lectures', coalesce((v_pev ->> 'lectures')::int, 0) + 1,
           'derniere', now(),
           'regle', 'jamais_vue_en_ligne_2010'));
  end if;
  return new;
exception when others then
  raise warning 'cross_post_jobs_vue_ou_pas_encore_visible : job % : % — écriture inchangée', new.id, sqlerrm;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.deja_vendu_retrait_echoue_defait()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d inventaire_doublons%ROWTYPE; r jsonb;
BEGIN
  BEGIN
    SELECT * INTO d FROM inventaire_doublons q
     WHERE q.user_id = NEW.user_id AND q.statut = 'fusionnee' AND q.fusion_id IS NOT NULL
       AND q.preuves ? 'retraits_oui' AND (q.preuves -> 'retraits_oui') ? NEW.id::text
     LIMIT 1;
    IF d.id IS NULL THEN RETURN NULL; END IF;
    r := inventaire_defusionner_pour(d.user_id, d.fusion_id, 'retrait_echoue');
    IF NOT COALESCE((r ->> 'ok')::boolean, false) THEN
      RAISE WARNING 'deja_vendu_retrait_echoue_defait (job %): %', NEW.id, r;
    ELSE
      UPDATE cross_post_jobs SET status = 'cancelled'
       WHERE user_id = NEW.user_id AND id <> NEW.id AND status IN ('pending', 'processing')
         AND id::text IN (SELECT jsonb_array_elements_text(d.preuves -> 'retraits_oui'));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'deja_vendu_retrait_echoue_defait (job %): %', NEW.id, SQLERRM;
  END;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.doublon_attribut_distinctif(p_titre_a text, p_titre_b text, p_attr_a jsonb DEFAULT NULL::jsonb, p_attr_b jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  ca jsonb := public.doublon_couleurs(p_titre_a, p_attr_a #>> '{couleur,v}');
  cb jsonb := public.doublon_couleurs(p_titre_b, p_attr_b #>> '{couleur,v}');
  a_tout text[]; b_tout text[]; a_seul text[]; b_seul text[];
  na text[] := public.doublon_nombres(p_titre_a); nb text[] := public.doublon_nombres(p_titre_b);
  ta text := NULLIF(regexp_replace(regexp_replace(lower(COALESCE(p_attr_a #>> '{taille,v}', '')), '\(.*?\)|taille|eu|fr|uk|us|\s', '', 'g'), '[^a-z0-9.,]', '', 'g'), '');
  tb text := NULLIF(regexp_replace(regexp_replace(lower(COALESCE(p_attr_b #>> '{taille,v}', '')), '\(.*?\)|taille|eu|fr|uk|us|\s', '', 'g'), '[^a-z0-9.,]', '', 'g'), '');
  v_voisines jsonb := '{"blanc":["beige","gris"],"beige":["blanc","marron","jaune","orange","rose","gris"],
    "marron":["beige","orange","jaune","rouge","vert","gris","noir"],"noir":["gris","marron","bleu"],
    "gris":["noir","blanc","beige","bleu","vert","marron"],"bleu":["gris","noir","vert","violet"],
    "rouge":["rose","orange","marron","violet"],"rose":["rouge","violet","orange","beige"],
    "vert":["bleu","jaune","marron","gris","beige"],"jaune":["orange","beige","vert","marron"],
    "orange":["rouge","jaune","marron","rose","beige"],"violet":["rose","bleu","rouge"]}'::jsonb;
BEGIN
  IF NOT (ca ->> 'multi')::boolean AND NOT (cb ->> 'multi')::boolean THEN
    a_tout := ARRAY(SELECT jsonb_array_elements_text(ca -> 'base') UNION SELECT jsonb_array_elements_text(ca -> 'nuance'));
    b_tout := ARRAY(SELECT jsonb_array_elements_text(cb -> 'base') UNION SELECT jsonb_array_elements_text(cb -> 'nuance'));
    IF cardinality(a_tout) > 0 AND cardinality(b_tout) > 0 THEN
      a_seul := ARRAY(SELECT unnest(a_tout) EXCEPT SELECT unnest(b_tout));
      b_seul := ARRAY(SELECT unnest(b_tout) EXCEPT SELECT unnest(a_tout));
      IF cardinality(a_seul) > 0 AND cardinality(b_seul) > 0 THEN
        IF NOT (cardinality(a_tout) = 1 AND cardinality(b_tout) = 1
                AND COALESCE((v_voisines -> a_tout[1]) ? b_tout[1], false)
                AND (jsonb_array_length(ca -> 'nuance') = 1 OR jsonb_array_length(cb -> 'nuance') = 1)) THEN
          RETURN 'couleur';
        END IF;
      END IF;
    END IF;
  END IF;
  IF cardinality(na) > 0 AND cardinality(nb) > 0
     AND EXISTS (SELECT 1 FROM unnest(na) x WHERE NOT x = ANY (nb))
     AND EXISTS (SELECT 1 FROM unnest(nb) x WHERE NOT x = ANY (na)) THEN
    RETURN 'nombre';
  END IF;
  IF ta IS NOT NULL AND tb IS NOT NULL AND ta <> tb
     AND ((ta ~ '^\d+([.,]\d+)?$' AND tb ~ '^\d+([.,]\d+)?$')
          OR (ta ~ '^(xxxs|xxs|xs|s|m|l|xl|xxl|xxxl|[2-6]xl)$' AND tb ~ '^(xxxs|xxs|xs|s|m|l|xl|xxl|xxxl|[2-6]xl)$')) THEN
    RETURN 'taille';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.doublon_couleurs(p_titre text, p_attr text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v text := public.doublon_norm(COALESCE(p_titre, '') || ' ' || COALESCE(p_attr, ''));
  v_dico jsonb := '{
    "blanc":  ["blanc","blanche","blancs","blanches"],
    "noir":   ["noir","noire","noirs","noires"],
    "gris":   ["gris","grise","grises"],
    "bleu":   ["bleu","bleue","bleus","bleues"],
    "rouge":  ["rouge","rouges"],
    "rose":   ["rose","roses","pink"],
    "vert":   ["vert","verte","verts","vertes"],
    "jaune":  ["jaune","jaunes"],
    "orange": ["orange","oranges"],
    "violet": ["violet","violette","violets","violettes"],
    "marron": ["marron","marrons","brun","brune"],
    "beige":  ["beige","beiges"]
  }'::jsonb;
  v_nuances jsonb := '{
    "blanc":  ["ecru","ivoire","creme","vanille"],
    "beige":  ["sable","nude","camel","taupe","chameau"],
    "marron": ["chocolat","cognac","caramel","noisette","chataigne","tabac"],
    "gris":   ["anthracite","chine","argent","argente","argentee","acier"],
    "bleu":   ["marine","turquoise","ciel","azur","indigo","denim","cobalt","navy"],
    "rouge":  ["bordeaux","carmin","cerise","grenat"],
    "rose":   ["fuchsia","framboise","saumon","poudre","magenta"],
    "vert":   ["kaki","olive","emeraude","menthe","sapin","pistache","anis"],
    "jaune":  ["moutarde","citron","ocre","curry","dore","doree"],
    "orange": ["corail","abricot","rouille","brique","terracotta","cuivre"],
    "violet": ["mauve","lilas","prune","lavande","parme","aubergine","pourpre"]
  }'::jsonb;
  v_base text[] := '{}'; v_nu text[] := '{}'; k text; m text;
  v_multi boolean := v ~ ' (multicolore|multicolor|motifs?|fleuri|fleurs?|imprime|rayures?|raye|rayee|carreaux|leopard|pois|camouflage|arc en ciel) ';
BEGIN
  FOR k IN SELECT jsonb_object_keys(v_dico) LOOP
    FOR m IN SELECT jsonb_array_elements_text(v_dico -> k) LOOP
      IF position(' ' || m || ' ' IN v) > 0 AND NOT (k = ANY (v_base)) THEN v_base := v_base || k; END IF;
    END LOOP;
  END LOOP;
  FOR k IN SELECT jsonb_object_keys(v_nuances) LOOP
    FOR m IN SELECT jsonb_array_elements_text(v_nuances -> k) LOOP
      IF position(' ' || m || ' ' IN v) > 0 AND NOT (k = ANY (v_nu)) AND NOT (k = ANY (v_base)) THEN v_nu := v_nu || k; END IF;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('base', to_jsonb(v_base), 'nuance', to_jsonb(v_nu), 'multi', v_multi);
END;
$function$

CREATE OR REPLACE FUNCTION public.doublon_ecarte_par_regle(p_user uuid, p_garde bigint, p_absorbe bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g record; a record; v_raison text; v_refus integer;
BEGIN
  SELECT id, titre, statut, quantite, attributs INTO g FROM inventaire WHERE id = p_garde;
  SELECT id, titre, statut, quantite, attributs INTO a FROM inventaire WHERE id = p_absorbe;
  IF g.id IS NULL OR a.id IS NULL OR g.id = a.id THEN RETURN NULL; END IF;
  v_raison := doublon_attribut_distinctif(g.titre, a.titre, g.attributs, a.attributs);
  IF v_raison IS NOT NULL THEN RETURN v_raison; END IF;
  IF (g.statut = 'vendu' AND a.statut <> 'vendu' AND COALESCE(a.quantite, 1) > 1)
     OR (a.statut = 'vendu' AND g.statut <> 'vendu' AND COALESCE(g.quantite, 1) > 1) THEN
    RETURN 'plusieurs_exemplaires';
  END IF;
  IF regexp_replace(doublon_norm(g.titre), '^[^a-z]*', '') IS DISTINCT FROM regexp_replace(doublon_norm(a.titre), '^[^a-z]*', '') THEN
    SELECT count(*) INTO v_refus FROM inventaire_doublons d
    WHERE d.user_id = p_user AND d.statut = 'refusee' AND d.decide_par = 'utilisateur'
      AND (d.garde IN (p_garde, p_absorbe) OR d.absorbe IN (p_garde, p_absorbe));
    IF v_refus >= 2 THEN RETURN 'variantes_deja_refusees'; END IF;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.ecrire_statut_job_extension(p_user uuid, p_poste text, p_job uuid, p_reservation uuid, p_avant text, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '3s'
 SET lock_timeout TO '1s'
AS $function$
DECLARE j cross_post_jobs%ROWTYPE; r jobs_reservations_extension%ROWTYPE; nouveau cross_post_jobs%ROWTYPE;
BEGIN
 SELECT * INTO j FROM cross_post_jobs WHERE id=p_job AND user_id=p_user FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','Job introuvable.'); END IF;
 IF j.status IS DISTINCT FROM p_avant THEN
  RETURN jsonb_build_object('ok',false,'reason','Le job a changé entre-temps. Actualise la file.'); END IF;
 IF p_reservation IS NOT NULL THEN
  SELECT * INTO r FROM jobs_reservations_extension WHERE job_id=p_job FOR UPDATE;
  IF r.reservation IS DISTINCT FROM p_reservation OR r.poste IS DISTINCT FROM p_poste THEN
   RETURN jsonb_build_object('ok',false,'reason','La réservation de ce poste a changé. Actualise la file.'); END IF;
  IF j.status NOT IN ('pending','processing') AND p_patch->>'status'='processing' THEN
   RETURN jsonb_build_object('ok',false,'reason','Ce job a été arrêté entre-temps.'); END IF;
 ELSIF j.status IS DISTINCT FROM p_avant THEN
  RETURN jsonb_build_object('ok',false,'reason','Le job a changé entre-temps. Actualise la file.');
 END IF;
 SELECT * INTO nouveau FROM jsonb_populate_record(j,p_patch);
 UPDATE cross_post_jobs SET status=nouveau.status,error=nouveau.error,
  platform_fields=nouveau.platform_fields,handler_build=nouveau.handler_build,
  listing_url=nouveau.listing_url,platform_listing_id=nouveau.platform_listing_id,
  published_at=nouveau.published_at WHERE id=p_job;
 IF nouveau.status='processing' THEN
  UPDATE jobs_reservations_extension SET commence=true WHERE job_id=p_job AND reservation=p_reservation;
 ELSE
  DELETE FROM jobs_reservations_extension WHERE job_id=p_job AND reservation=p_reservation;
 END IF;
 RETURN jsonb_build_object('ok',true,'job',jsonb_build_object('id',p_job,'status',nouveau.status));
END;
$function$

CREATE OR REPLACE FUNCTION public.enregistrer_vente_atomique(p_user uuid, p_cle text, p_inventaire bigint DEFAULT NULL::bigint, p_job uuid DEFAULT NULL::uuid, p_prix numeric DEFAULT NULL::numeric, p_frais numeric DEFAULT 0, p_quantite integer DEFAULT 1, p_quantite_attendue integer DEFAULT NULL::integer, p_plateforme text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '1500ms'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
 j cross_post_jobs%ROWTYPE; i inventaire%ROWTYPE; copie record;
 v_inv bigint:=p_inventaire; v_cle text; precedent jsonb; v_resultat jsonb;
 v_prix numeric; v_pa numeric; v_benef numeric; v_pct numeric; v_frais numeric:=coalesce(p_frais,0);
 v_pf text:=p_plateforme; v_code text; v_libelle text; v_q integer:=coalesce(p_quantite,1); v_restant integer;
 v_vente bigint; v_ids bigint[]:='{}'; v_historique bigint; v_n integer;
 v_retraits integer:=0; v_annules integer:=0; v_proof boolean:=false;
 v_snap record; v_succ record;
 v_alerte timestamptz; v_fin_ebay timestamptz; v_vu_ebay timestamptz; v_revue_le timestamptz;
 v_saisie bigint; v_sans_stock boolean:=false;
 v_none jsonb:=jsonb_build_object('ok',false,'venteCreated',false,'inventaireUpdated',false,
  'siblingsCancelled',0,'pendingRemoval',0,'retraitsArmes',0,'emailSent',false,'venteNotee',false);
BEGIN
 IF p_user IS NULL OR (auth.uid() IS NOT NULL AND auth.uid()<>p_user) THEN
  RAISE EXCEPTION 'Compte non autorisé' USING ERRCODE='42501'; END IF;
 IF p_job IS NOT NULL THEN
  SELECT * INTO j FROM cross_post_jobs WHERE id=p_job AND user_id=p_user;
  IF j.id IS NULL OR coalesce(j.action,'publish') NOT IN ('publish','republish') THEN
   RETURN v_none||jsonb_build_object('reason','Annonce introuvable pour cette vente.'); END IF;
  v_inv:=j.inventaire_id;
  v_cle:=CASE WHEN nullif(btrim(j.platform_listing_id),'') IS NOT NULL
    THEN 'annonce:'||j.platform||':'||btrim(j.platform_listing_id) ELSE 'job:'||j.id::text END;
  v_q:=1;
  IF v_inv IS NULL AND nullif(btrim(j.platform_listing_id),'') IS NOT NULL AND EXISTS(
     SELECT 1 FROM cross_post_jobs k WHERE k.user_id=p_user AND k.platform=j.platform AND k.id<>j.id
       AND k.inventaire_id IS NOT NULL AND coalesce(k.action,'publish') IN ('publish','republish')
       AND btrim(k.platform_listing_id)=btrim(j.platform_listing_id)) THEN
   RETURN v_none||jsonb_build_object('code','job_sans_fiche','reason',
    'Cette annonce appartient à un article de ton stock : sa vente s’enregistre depuis cet article, jamais deux fois.');
  END IF;
 ELSE
  IF nullif(btrim(p_cle),'') IS NULL OR length(p_cle)>150 OR v_inv IS NULL THEN
   RETURN v_none||jsonb_build_object('reason','La référence de cette confirmation de vente manque.'); END IF;
  v_cle:='manuel:'||p_cle;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text||':'||coalesce(v_inv::text,v_cle),0));
 SELECT o.resultat INTO precedent FROM ventes_operations o WHERE o.user_id=p_user AND o.cle=v_cle;
 IF FOUND THEN RETURN precedent||jsonb_build_object('rejouee',true,'venteCreated',false,'inventaireUpdated',false); END IF;
 IF v_inv IS NOT NULL THEN
  SELECT * INTO i FROM inventaire WHERE id=v_inv AND user_id=p_user FOR UPDATE;
  IF i.id IS NULL OR i.fusionne_dans IS NOT NULL THEN
   RETURN v_none||jsonb_build_object('reason','La fiche de cet exemplaire doit être confirmée avant d’enregistrer la vente.'); END IF;
 END IF;
 IF p_job IS NOT NULL THEN
  SELECT * INTO j FROM cross_post_jobs WHERE id=p_job AND user_id=p_user FOR UPDATE;
  IF j.inventaire_id IS DISTINCT FROM v_inv THEN RAISE EXCEPTION 'La fiche a changé ; réessaie.'; END IF;
  IF nullif(j.platform_fields->>'vente_operation_cle','') IS NOT NULL THEN
   SELECT o.resultat INTO precedent FROM ventes_operations o
    WHERE o.user_id=p_user AND o.cle=j.platform_fields->>'vente_operation_cle';
   IF FOUND THEN RETURN precedent||jsonb_build_object('rejouee',true,'venteCreated',false,'inventaireUpdated',false); END IF;
  END IF;
  IF j.status='sold' THEN
   RETURN v_none||jsonb_build_object('reason','Cette ancienne vente doit être vérifiée dans tes ventes avant toute nouvelle confirmation. Aucun stock n’a été recompté.'); END IF;
  IF j.status<>'published' THEN RETURN v_none||jsonb_build_object('reason','Cette annonce n’est plus à confirmer comme vendue.'); END IF;
  IF j.platform='vinted' AND nullif(btrim(j.platform_listing_id),'') IS NOT NULL THEN
   SELECT s.status, s.captured_at INTO v_snap FROM vinted_listing_snapshots s
    WHERE s.user_id=p_user AND s.vinted_item_id=btrim(j.platform_listing_id) ORDER BY s.captured_at DESC LIMIT 1;
   IF v_snap.status='active' AND (v_snap.captured_at>=coalesce(_ts_ou_null(j.platform_fields->>'unavailable_since'),j.published_at,j.created_at)
      OR EXISTS(SELECT 1 FROM vinted_sync_runs r WHERE r.user_id=p_user AND r.kind='dressing'
        AND r.started_at<=LEAST(v_snap.captured_at,_ts_ou_null(j.platform_fields->>'unavailable_since'))
        AND coalesce(r.finished_at,now())>=GREATEST(v_snap.captured_at,_ts_ou_null(j.platform_fields->>'unavailable_since')))) THEN
    PERFORM public.signal_vente_lever(j.id, 'signal_dementi_a_la_confirmation',
      jsonb_build_object('releve_le', v_snap.captured_at, 'par', 'enregistrer_vente_atomique'));
    RETURN v_none||jsonb_build_object('code','annonce_en_ligne','signal_leve',true,'reason','Cette annonce est toujours en ligne sur Vinted (relevé du dressing du '
      ||to_char(v_snap.captured_at AT TIME ZONE 'Europe/Paris','DD/MM à HH24:MI')||') : aucune vente n’est enregistrée.');
   END IF;
   IF coalesce(j.platform_fields->>'sale_signal','')<>'sold' AND i.id IS NOT NULL
      AND nullif(btrim(i.vinted_item_id),'') IS NOT NULL AND btrim(i.vinted_item_id)<>btrim(j.platform_listing_id)
      AND coalesce(i.vinted_status,'')='active' AND i.disparu_le IS NULL
      AND EXISTS(SELECT 1 FROM vinted_listing_snapshots s WHERE s.user_id=p_user AND s.vinted_item_id=btrim(i.vinted_item_id)
                  AND s.status='active' AND s.captured_at>now()-interval '26 hours') THEN
    RETURN v_none||jsonb_build_object('reason','Cet article est en ligne sur Vinted sous une autre annonce ('||btrim(i.vinted_item_id)
      ||') : celle-ci a été remplacée, ce n’est pas une vente.');
   END IF;
  END IF;
  IF NOT retrait_job_prouve(j.id) OR (v_inv IS NOT NULL AND fiche_annonces_vivantes(v_inv,j.platform)>1) THEN
   RETURN v_none||jsonb_build_object('reason','Plusieurs exemplaires sont possibles. Confirme la fiche de cette annonce avant d’enregistrer sa vente.'); END IF;
  v_proof:=coalesce(j.platform_fields->>'sale_signal','')='sold';
  IF NOT v_proof AND j.platform='vinted' AND nullif(j.platform_listing_id,'') IS NOT NULL THEN
   SELECT s.status='sold' INTO v_proof FROM vinted_listing_snapshots s
    WHERE s.user_id=p_user AND s.vinted_item_id=j.platform_listing_id ORDER BY s.captured_at DESC LIMIT 1;
  END IF;
  IF NOT coalesce(v_proof,false) AND j.platform='vinted' AND nullif(btrim(j.platform_listing_id),'') IS NOT NULL
     AND COALESCE((SELECT c.value FROM coin_config c WHERE c.key='vente_garde_remise_en_ligne'),1)<>0 THEN
   SELECT n.id, n.vinted_item_id, s.le INTO v_succ
     FROM inventaire n
     CROSS JOIN LATERAL (SELECT max(x.captured_at) le FROM vinted_listing_snapshots x
                          WHERE x.user_id=p_user AND x.vinted_item_id=btrim(n.vinted_item_id) AND x.status='active') s
    WHERE n.user_id=p_user AND n.id IS DISTINCT FROM v_inv AND n.fusionne_dans IS NULL AND n.statut='stock'
      AND nullif(btrim(n.vinted_item_id),'') IS NOT NULL AND btrim(n.vinted_item_id)<>btrim(j.platform_listing_id)
      AND coalesce(n.vinted_status,'')='active' AND n.disparu_le IS NULL
      AND coalesce(n.vinted_account_id,'')=coalesce(i.vinted_account_id,n.vinted_account_id,'')
      AND length(titre_norm(n.titre))>=6 AND titre_norm(n.titre) IN (titre_norm(i.titre),titre_norm(j.title))
      AND n.first_seen_at>coalesce((SELECT max(x.captured_at) FROM vinted_listing_snapshots x
                                     WHERE x.user_id=p_user AND x.vinted_item_id=btrim(j.platform_listing_id) AND x.status='active'),
                                    j.published_at,j.created_at)
      AND s.le>now()-interval '72 hours'
    ORDER BY s.le DESC LIMIT 1;
   IF v_succ.id IS NOT NULL THEN
    RETURN v_none||jsonb_build_object('code','remise_en_ligne','successeur',v_succ.id::text,
      'reason','Cet article est de nouveau en ligne sur Vinted sous une autre annonce (n° '||btrim(v_succ.vinted_item_id)
      ||', vue le '||to_char(v_succ.le AT TIME ZONE 'Europe/Paris','DD/MM à HH24:MI')
      ||') : l’ancienne annonce a été remplacée, ce n’est pas une vente. Si l’article est vendu, enregistre la vente depuis sa fiche en ligne.');
   END IF;
  END IF;
  IF v_inv IS NULL AND NOT coalesce(v_proof,false) THEN
   RETURN v_none||jsonb_build_object('code','job_sans_fiche','reason',
    'Cette annonce n’est liée à aucun article de ton stock : aucune vente n’est enregistrée ici. Si tu l’as vendu, enregistre la vente depuis l’article.');
  END IF;
  IF NOT coalesce(v_proof,false) THEN
   v_alerte:=_ts_ou_null(j.platform_fields->>'unavailable_since');
   IF j.platform='ebay' THEN
    IF j.platform_fields#>>'{fin_ebay,format}'='AUCTION' OR j.platform_fields#>>'{format_ebay,format}'='AUCTION' THEN
     RETURN v_none||jsonb_build_object('code','enchere','reason',
      'C’est une enchère eBay : elle n’est vendue que si eBay le dit (enchère gagnée). Aucune vente n’est enregistrée et aucune autre annonce n’est retirée. Si l’article est vendu ailleurs, enregistre la vente depuis sa fiche.');
    END IF;
    v_fin_ebay:=_ts_ou_null(j.platform_fields#>>'{fin_ebay,fin}');
    IF v_fin_ebay>now() THEN
     RETURN v_none||jsonb_build_object('code','annonce_en_ligne','reason',
      'Cette annonce est toujours en ligne sur eBay (fin prévue le '||to_char(v_fin_ebay AT TIME ZONE 'Europe/Paris','DD/MM à HH24:MI')
      ||') : aucune vente n’est enregistrée. Si l’article est vendu ailleurs, enregistre la vente depuis sa fiche.');
    END IF;
    v_vu_ebay:=_ts_ou_null(j.platform_fields#>>'{quantite_ebay,vu_le}');
    IF v_alerte IS NOT NULL AND v_vu_ebay>v_alerte AND coalesce(j.platform_fields#>>'{quantite_ebay,terminee}','')<>'true' THEN
     RETURN v_none||jsonb_build_object('code','annonce_en_ligne','reason',
      'eBay montre cette annonce en vente (lue le '||to_char(v_vu_ebay AT TIME ZONE 'Europe/Paris','DD/MM à HH24:MI')
      ||') : aucune vente n’est enregistrée. Si l’article est vendu ailleurs, enregistre la vente depuis sa fiche.');
    END IF;
   END IF;
   IF v_alerte IS NOT NULL AND j.platform<>'vinted' AND nullif(btrim(j.platform_listing_id),'') IS NOT NULL THEN
    SELECT max(a.vu_le) INTO v_revue_le FROM annonces_plateforme a
     WHERE a.user_id=p_user AND a.platform=j.platform AND a.listing_id=btrim(j.platform_listing_id)
       AND a.statut_plateforme='en_ligne' AND a.disparu_le IS NULL AND a.vu_le>v_alerte;
    IF v_revue_le IS NOT NULL THEN
     RETURN v_none||jsonb_build_object('code','annonce_en_ligne','reason',
      'Cette annonce a été revue en ligne sur '||CASE j.platform WHEN 'leboncoin' THEN 'Leboncoin' WHEN 'ebay' THEN 'eBay'
        WHEN 'beebs' THEN 'Beebs' WHEN 'opla' THEN 'Opla' WHEN 'depop' THEN 'Depop' ELSE j.platform END
      ||' le '||to_char(v_revue_le AT TIME ZONE 'Europe/Paris','DD/MM à HH24:MI')
      ||', après l’alerte : aucune vente n’est enregistrée. Si l’article est vendu ailleurs, enregistre la vente depuis sa fiche.');
    END IF;
   END IF;
  END IF;
  v_pf:=CASE WHEN coalesce(v_proof,false) OR j.platform='beebs' THEN j.platform ELSE 'ailleurs' END;
  v_prix:=coalesce(p_prix,j.price); v_frais:=0;
 ELSE
  v_prix:=p_prix;
 END IF;
 v_code:=coalesce(plateforme_normalisee(v_pf),'ailleurs');
 IF v_code='autre' THEN v_code:='ailleurs'; END IF;
 v_libelle:=CASE WHEN p_job IS NOT NULL OR v_pf IS NULL OR v_pf=v_code THEN
   CASE v_code WHEN 'vinted' THEN 'Vinted' WHEN 'ebay' THEN 'eBay' WHEN 'leboncoin' THEN 'Leboncoin'
     WHEN 'beebs' THEN 'Beebs' WHEN 'opla' THEN 'Opla' WHEN 'depop' THEN 'Depop' ELSE 'Ailleurs' END ELSE v_pf END;
 IF v_prix IS NULL OR v_prix<=0 OR v_prix::text IN ('NaN','Infinity','-Infinity') OR v_frais<0 OR v_frais::text IN ('NaN','Infinity','-Infinity')
    OR v_q<1 OR v_q>1000 THEN RETURN v_none||jsonb_build_object('reason','Vérifie le prix, les frais et la quantité vendue.'); END IF;
 IF v_inv IS NOT NULL THEN
  IF p_job IS NOT NULL AND coalesce(v_proof,false) AND (i.statut='vendu' OR coalesce(i.quantite,1)<v_q) THEN
   v_saisie:=public.vente_saisie_meme_cession(j.id);
   IF v_saisie IS NOT NULL THEN
    RETURN public.signal_vente_clore_meme_cession(j.id, v_saisie, 'enregistrer_vente_atomique');
   END IF;
   IF i.statut='vendu' AND NOT EXISTS(SELECT 1 FROM ventes v WHERE v.user_id=p_user AND v.inventaire_id=v_inv) THEN
    v_sans_stock:=true;
   ELSE
    RETURN v_none||jsonb_build_object('code','deja_vendue','reason','Cet article est déjà vendu : si c’est cette vente-là, touche « Déjà enregistrée » ; rien ne sera compté deux fois.');
   END IF;
  END IF;
  IF NOT v_sans_stock AND (i.statut='vendu' OR coalesce(i.quantite,1)<v_q) THEN
   RETURN v_none||jsonb_build_object('reason','Ce stock a déjà été vendu ou modifié. Actualise-le avant de confirmer.'); END IF;
  IF p_job IS NULL AND (p_quantite_attendue IS NULL OR coalesce(i.quantite,1) IS DISTINCT FROM p_quantite_attendue) THEN
   RETURN v_none||jsonb_build_object('reason','La quantité en stock a changé. Actualise-la avant de confirmer la vente.'); END IF;
  IF EXISTS(SELECT 1 FROM ventes v WHERE v.user_id=p_user AND v.inventaire_id=v_inv
    AND (p_job IS NULL OR v.created_at>=coalesce(j.published_at,j.created_at))
    AND NOT EXISTS(SELECT 1 FROM ventes_operations o WHERE o.user_id=p_user AND o.inventaire_id=v_inv
      AND o.resultat->'ventes_ids' @> to_jsonb(ARRAY[v.id])) LIMIT 1) THEN
   RETURN v_none||jsonb_build_object('code','vente_deja_liee','reason','Une vente est déjà liée à cette fiche. Vérifie-la dans tes ventes pour éviter de la compter deux fois.'); END IF;
  v_pa:=CASE WHEN i.prix_achat_inconnu THEN NULL ELSE i.prix_achat END;
  v_benef:=CASE WHEN v_pa IS NOT NULL THEN v_prix-v_pa-coalesce(i.purchase_costs,0)-v_frais END;
  v_pct:=v_benef/v_prix*100; v_restant:=CASE WHEN v_sans_stock THEN 0 ELSE coalesce(i.quantite,1)-v_q END;
 END IF;
 INSERT INTO ventes_operations(user_id,cle,inventaire_id,job_id,resultat) VALUES(p_user,v_cle,v_inv,p_job,'{}');
 IF p_job IS NOT NULL THEN
  UPDATE cross_post_jobs SET status='sold',sold_at=now(),last_checked_at=now(),
   platform_fields=coalesce(platform_fields,'{}')||jsonb_build_object('vente_operation_cle',v_cle)
   WHERE id=j.id;
 END IF;
 FOR v_n IN 1..v_q LOOP
  INSERT INTO ventes(user_id,inventaire_id,titre,prix_achat,prix_vente,benefice,marque,type,description,
    emplacement,date,plateforme,plateforme_code,annonce_id,quantite,statut,selling_fees)
   VALUES(p_user,v_inv,coalesce(j.title,i.titre),v_pa,v_prix,v_benef,i.marque,i.type,i.description,
    i.emplacement,CASE WHEN v_sans_stock THEN coalesce((_ts_ou_null(j.platform_fields->>'unavailable_since') AT TIME ZONE 'Europe/Paris')::date,
      (now() AT TIME ZONE 'Europe/Paris')::date) ELSE (now() AT TIME ZONE 'Europe/Paris')::date END,v_libelle,v_code,
    CASE WHEN p_job IS NOT NULL THEN nullif(btrim(j.platform_listing_id),'') END,1,'vendu',v_frais) RETURNING id INTO v_vente;
  v_ids:=array_append(v_ids,v_vente);
 END LOOP;
 IF v_inv IS NOT NULL THEN
  IF v_restant>0 THEN
   UPDATE inventaire SET quantite=v_restant WHERE id=v_inv;
   LOOP
    v_historique:=(extract(epoch FROM clock_timestamp())*1000)::bigint+(random()*9999)::int;
    EXIT WHEN NOT EXISTS(SELECT 1 FROM inventaire WHERE id=v_historique);
   END LOOP;
   INSERT INTO inventaire(id,user_id,titre,prix_achat,prix_achat_inconnu,purchase_costs,prix_vente,margin,margin_pct,
    selling_fees,statut,quantite,marque,type,description,emplacement,plateforme,date)
   VALUES(v_historique,p_user,i.titre,v_pa,v_pa IS NULL,0,v_prix,v_benef,v_pct,v_frais,'vendu',v_q,
    i.marque,i.type,i.description,i.emplacement,v_libelle,to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  ELSE
   UPDATE inventaire SET quantite=CASE WHEN p_job IS NULL THEN v_q ELSE 0 END,
    statut='vendu',prix_vente=v_prix,margin=v_benef,margin_pct=v_pct,
    selling_fees=v_frais,plateforme=v_libelle,date=to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') WHERE id=v_inv;
  END IF;
  FOR copie IN SELECT c.id,c.status,c.platform FROM cross_post_jobs c
    WHERE c.user_id=p_user AND c.inventaire_id=v_inv AND c.id IS DISTINCT FROM p_job
      AND c.action IN ('publish','republish') AND c.status IN ('pending','processing','needs_user','published')
      AND (p_job IS NULL OR c.platform IS DISTINCT FROM j.platform
           OR (v_restant=0 AND c.status IN ('pending','processing','needs_user')))
      AND (v_restant=0 OR (p_job IS NULL AND c.platform=v_code AND c.status='published'))
      AND retrait_job_prouve(c.id) AND fiche_annonces_vivantes(v_inv,c.platform)<2
    ORDER BY c.id LIMIT 25 FOR UPDATE OF c
  LOOP
   UPDATE cross_post_jobs SET platform_fields=coalesce(platform_fields,'{}')||jsonb_build_object('vente_operation_cle',v_cle) WHERE id=copie.id;
   IF p_job IS NULL AND copie.platform=v_code AND copie.status='published' THEN
    UPDATE cross_post_jobs SET status='sold',sold_at=now() WHERE id=copie.id;
   ELSIF copie.status='published' THEN
    IF armer_retrait_job(copie.id,'vente_copie_prouvee','0 seconds') IS NOT NULL THEN v_retraits:=v_retraits+1; END IF;
   ELSE
    UPDATE cross_post_jobs SET status='cancelled',error='Cet exemplaire a été vendu ; cette publication est arrêtée.' WHERE id=copie.id;
    v_annules:=v_annules+1;
   END IF;
  END LOOP;
 END IF;
 IF p_job IS NOT NULL THEN
  INSERT INTO usage_logs(user_id,feature,metadata) VALUES(p_user,'vente_a_annoncer',
   jsonb_build_object('job_id',j.id,'inventaire_id',v_inv::text,'plateforme',v_code,'plateforme_annonce',j.platform,
    'titre',coalesce(j.title,i.titre),'prix_vente',v_prix,'benefice',v_benef,'retraits_a_cliquer',0,
    'retrait_beebs_auto',v_retraits,'vendu_le',now()));
 END IF;
 v_resultat:=v_none||jsonb_build_object('ok',true,'venteCreated',true,'inventaireUpdated',v_inv IS NOT NULL,
  'siblingsCancelled',v_annules,'retraitsArmes',v_retraits,'venteNotee',p_job IS NOT NULL,
  'ventes_ids',to_jsonb(v_ids),'restant',v_restant,'rejouee',false);
 UPDATE ventes_operations SET resultat=v_resultat WHERE user_id=p_user AND cle=v_cle;
 RETURN v_resultat;
END;
$function$

CREATE OR REPLACE FUNCTION public.enregistrer_vente_prouvee(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c record;
  r jsonb;
BEGIN
  SELECT x.* INTO c FROM ventes_prouvees_a_enregistrer('-infinity'::timestamptz, 1, NULL, p_job, true) x;
  IF c.job_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'issue', 'plus_a_enregistrer', 'job', p_job);
  END IF;
  IF EXISTS (SELECT 1 FROM vinted_sync_runs WHERE user_id = c.user_id AND status = 'running' LIMIT 1) THEN
    RETURN jsonb_build_object('ok', false, 'issue', 'releve_en_cours', 'job', p_job);
  END IF;
  BEGIN
    r := enregistrer_vente_atomique(c.user_id, NULL, p_job := c.job_id, p_prix := c.prix);
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO ventes_prouvees_refus AS f (job_id, user_id, inventaire_id, preuve_le, raison, reessayer_apres)
    VALUES (c.job_id, c.user_id, c.inventaire_id, c.preuve_le, left('erreur : ' || SQLERRM, 300), now() + interval '15 minutes')
    ON CONFLICT (job_id) DO UPDATE SET raison = excluded.raison, essais = f.essais + 1, le = now(),
      reessayer_apres = excluded.reessayer_apres, preuve_le = excluded.preuve_le;
    RETURN jsonb_build_object('ok', false, 'issue', 'erreur', 'job', p_job, 'reason', left(SQLERRM, 300));
  END;
  IF coalesce(r ->> 'ok', 'false') = 'true' THEN
    DELETE FROM ventes_prouvees_refus WHERE job_id = c.job_id;
    RETURN r || jsonb_build_object('issue', CASE WHEN coalesce(r ->> 'rejouee', 'false') = 'true' THEN 'rejouee' ELSE 'enregistree' END,
                                   'job', p_job, 'preuve', c.preuve, 'preuve_le', c.preuve_le);
  END IF;
  INSERT INTO ventes_prouvees_refus AS f (job_id, user_id, inventaire_id, preuve_le, raison, reessayer_apres)
  VALUES (c.job_id, c.user_id, c.inventaire_id, c.preuve_le, left(coalesce(r ->> 'reason', 'refusée'), 300), now() + interval '6 hours')
  ON CONFLICT (job_id) DO UPDATE SET raison = excluded.raison, essais = f.essais + 1, le = now(),
    reessayer_apres = excluded.reessayer_apres, preuve_le = excluded.preuve_le;
  RETURN r || jsonb_build_object('issue', 'refusee', 'job', p_job);
END;
$function$

CREATE OR REPLACE FUNCTION public.garde_depop_acces()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.platform IS DISTINCT FROM 'depop' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.platform = 'depop' AND OLD.user_id IS NOT DISTINCT FROM NEW.user_id THEN RETURN NEW; END IF;
  IF NEW.user_id IS NOT NULL AND public.depop_autorise(NEW.user_id) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'depop_non_ouvert : Depop n''est pas ouverte pour ce compte' USING ERRCODE = 'P0001';
END
$function$

CREATE OR REPLACE FUNCTION public.garde_fou_jour(p_user uuid, p_jauge text, p_ajout integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_garde  integer;
  v_minuit timestamptz;
  v_faites integer;
  v_nom    text;
BEGIN
  IF NOT jauges_actives() THEN
    RETURN NULL;
  END IF;
  SELECT NULLIF(value, 0) INTO v_garde FROM coin_config WHERE key = 'garde_jour_' || p_jauge;
  IF v_garde IS NULL THEN
    RETURN NULL;
  END IF;
  v_minuit := date_trunc('day', now() AT TIME ZONE 'Europe/Paris') AT TIME ZONE 'Europe/Paris';
  v_faites := CASE p_jauge
    WHEN 'publications' THEN publications_du_cycle(p_user, v_minuit)
    WHEN 'remontees'    THEN remontees_du_cycle(p_user, v_minuit)
    WHEN 'annonces'     THEN quota_annonces_consommees(p_user, v_minuit)
  END;
  IF v_faites IS NULL OR v_faites + GREATEST(COALESCE(p_ajout, 1), 0) <= v_garde THEN
    RETURN NULL;
  END IF;
  v_nom := CASE p_jauge WHEN 'remontees' THEN 'remontées' ELSE p_jauge END;
  RETURN jsonb_build_object(
    'allowed', false, 'reason', 'garde_fou_jour', 'jauge', p_jauge,
    'garde', v_garde, 'faites', v_faites, 'reprise_le', v_minuit + interval '1 day',
    'message', format('Pause de sécurité jusqu''à minuit : tu as fait %s %s aujourd''hui. Au-delà, les plateformes risquent de restreindre ton compte. Rien n''est perdu : tout reprend demain.',
                      replace(to_char(v_faites, 'FM999,999,999'), ',', ' '), v_nom));
END;
$function$

CREATE OR REPLACE FUNCTION public.garde_opla_sortie_jobs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_avant text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.status ELSE NEW.status END;
  v_pf    jsonb := coalesce(NEW.platform_fields, '{}'::jsonb);
BEGIN
  IF NOT public.opla_sortie_passee() THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' AND NEW.action = 'delete' THEN
    PERFORM public.opla_copie_a_retirer_noter(c.id, 'retrait_demande')
       FROM public.cross_post_jobs c
      WHERE c.user_id = NEW.user_id AND c.platform = 'opla' AND c.status = 'published'
        AND coalesce(c.action, 'publish') IN ('publish', 'republish')
        AND ((NEW.inventaire_id IS NOT NULL AND c.inventaire_id = NEW.inventaire_id)
             OR public.listing_designe(coalesce(nullif(btrim(c.platform_listing_id), ''), c.listing_url), NEW.listing_url, NEW.platform_listing_id));
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND nullif(btrim(coalesce(OLD.error, '')), '') IS NOT NULL THEN
    v_pf := jsonb_set(v_pf, '{erreurs_archivees}',
      coalesce(v_pf -> 'erreurs_archivees', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
        'erreur', OLD.error, 'statut', OLD.status, 'archive_le', now(), 'par', 'garde_opla_sortie_jobs (sortie d''Opla)')));
  END IF;
  NEW.platform_fields := (v_pf - 'needs_user_source' - 'next_action_after') || jsonb_build_object('opla_sortie', jsonb_build_object(
    'le', now(), 'par', 'garde_opla_sortie_jobs', 'statut_avant', v_avant,
    'source_avant', v_pf ->> 'needs_user_source', 'operation', TG_OP));
  NEW.status := 'cancelled';
  NEW.error := public.opla_message_cloture(coalesce(NEW.action, 'publish'));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.garde_plateforme_ecartee_jobs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.action NOT IN ('publish', 'republish') OR NEW.status IS DISTINCT FROM 'pending' THEN RETURN NEW; END IF;
  IF NOT plateforme_ecartee_pour(NEW.user_id, NEW.platform) THEN RETURN NEW; END IF;
  NEW.status := 'needs_user';
  NEW.error := plateforme_ecartee_message(NEW.platform);
  NEW.platform_fields := COALESCE(NEW.platform_fields, '{}'::jsonb) || jsonb_build_object(
    'needs_user_source', 'plateforme_ecartee',
    'plateforme_ecartee', jsonb_build_object('le', now(), 'statut_avant', 'pending'));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.grant_monthly_coins(p_user_id uuid, p_tier text, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source text DEFAULT 'auto'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_amount      integer;
  v_override    integer;
  v_wallet      coin_wallets%ROWTYPE;
  v_anchor      int;
  v_created     timestamptz;
  v_has_billing boolean;
  v_is_comped   boolean;
  v_due         timestamptz;
  v_next        timestamptz;
  v_new_inc     integer;
  v_delta       integer;
  v_ref         text;
begin
  if p_tier not in ('free','premium','pro','business') then
    return jsonb_build_object('granted', false, 'reason', 'invalid_tier');
  end if;

  if p_source in ('sweep', 'lazy') then
    if exists (select 1 from profiles p
                where p.id = p_user_id
                  and p.cloud_formule is not null
                  and p.is_cloud is not true
                  and p.cloud_essai_arrete is not true
                  and p.cloud_canal is distinct from 'offert'
                  and p.cloud_essai_debut is not null and p.cloud_essai_fin is not null
                  and p.cloud_essai_debut <= now() and now() < p.cloud_essai_fin) then
      return jsonb_build_object('granted', false, 'reason', 'essai_formule_en_cours', 'tier', p_tier);
    end if;
  end if;

  select value into v_amount from coin_config where key = 'monthly_grant_' || p_tier;
  if v_amount is null then
    return jsonb_build_object('granted', false, 'reason', 'grant_not_configured');
  end if;

  select monthly_grant_override, created_at,
         (stripe_customer_id is not null
          or apple_original_transaction_id is not null
          or google_purchase_token is not null),
         coalesce(is_comped, false)
    into v_override, v_created, v_has_billing, v_is_comped
  from profiles where id = p_user_id;

  if v_override is not null and v_override > 0 then
    v_amount := v_override;
  end if;

  insert into coin_wallets (user_id) values (p_user_id) on conflict (user_id) do nothing;
  select * into v_wallet from coin_wallets where user_id = p_user_id for update;

  v_anchor := coalesce(v_wallet.grant_anchor_day,
                       extract(day from coalesce(v_created, now()))::int);
  v_due := v_wallet.next_grant_at;

  if v_due is not null then
    if p_source = 'payment' then
      if v_due > now() + interval '2 days' then
        return jsonb_build_object('granted', false, 'reason', 'already_granted',
                                  'next_grant_at', v_due);
      end if;
    elsif v_due > now() then
      return jsonb_build_object('granted', false, 'reason', 'already_granted',
                                'next_grant_at', v_due);
    end if;
  end if;

  if p_source <> 'payment' and v_has_billing and not v_is_comped and p_tier <> 'free'
     and v_due is not null and v_due < now() - interval '3 days' then
    return jsonb_build_object('granted', false, 'reason', 'awaiting_payment_event',
                              'next_grant_at', v_due, 'tier', p_tier);
  end if;

  v_new_inc := v_amount;
  v_delta   := v_new_inc - v_wallet.included_balance;

  if p_period_end is not null and p_period_end > now() then
    v_next := p_period_end;
  else
    v_next := grant_next_due(now(), v_anchor);
  end if;

  v_ref := 'grant_monthly:' || p_user_id || ':' || to_char(coalesce(v_due, now()), 'YYYY-MM-DD');
  begin
    insert into coin_ledger (user_id, delta, included_after, purchased_after, kind, ref, metadata)
    values (
      p_user_id, v_delta, v_new_inc, v_wallet.purchased_balance,
      'grant_monthly', v_ref,
      jsonb_build_object('tier', p_tier, 'override', v_override,
                         'source', p_source,
                         'solde_avant', v_wallet.included_balance,
                         'montant_theorique', v_amount,
                         'remplacement', true,
                         'next_grant_at', v_next)
    );
  exception when unique_violation then
    return jsonb_build_object('granted', false, 'reason', 'already_granted', 'ref', v_ref);
  end;

  update coin_wallets set
    included_balance = v_new_inc,
    next_grant_at    = v_next,
    grant_anchor_day = v_anchor,
    updated_at       = now()
  where user_id = p_user_id;

  return jsonb_build_object('granted', true, 'amount', v_delta,
                            'montant_theorique', v_amount,
                            'solde_avant', v_wallet.included_balance,
                            'included_after', v_new_inc,
                            'next_grant_at', v_next,
                            'source', p_source);
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_next_due(p_after timestamp with time zone, p_anchor_day integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_ref    date := p_after::date;
  v_first  date;
  v_last   int;
  v_cand   date;
  v_anchor int := least(greatest(coalesce(p_anchor_day, 1), 1), 31);
  i        int;
begin
  v_first := make_date(extract(year from v_ref)::int, extract(month from v_ref)::int, 1);
  for i in 0..1 loop
    v_last := extract(day from (v_first + interval '1 month' - interval '1 day'))::int;
    v_cand := v_first + (least(v_anchor, v_last) - 1);
    if v_cand > v_ref then
      return v_cand::timestamptz;
    end if;
    v_first := (v_first + interval '1 month')::date;
  end loop;
  return v_cand::timestamptz;
end;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_arme_retraits_avant_suppression()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role        text;
  v_pub         record;
  v_n           integer := 0;
  v_annules     integer := 0;
  v_plateformes text[] := '{}';
begin
  if coalesce(current_setting('fillsell.sans_retrait', true), '') = '1' then
    return old;
  end if;
  if pg_trigger_depth() > 1 then
    return old;
  end if;
  begin
    v_role := nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role';
  exception when others then
    v_role := null;
  end;
  if v_role = 'service_role' then
    return old;
  end if;

  begin
    if public.opla_sortie_passee() then
      perform public.opla_copie_a_retirer_noter(c.id, 'suppression_article')
         from public.cross_post_jobs c
        where c.user_id = old.user_id and c.inventaire_id = old.id and c.platform = 'opla'
          and coalesce(c.action, 'publish') in ('publish', 'republish') and c.status = 'published';
    end if;
    for v_pub in
      select distinct on (j.platform) j.platform, j.id, j.listing_url, j.title
        from public.cross_post_jobs j
       where j.user_id = old.user_id
         and j.inventaire_id = old.id
         and coalesce(j.action, 'publish') in ('publish', 'republish')
         and j.status = 'published'
         and nullif(btrim(j.listing_url), '') is not null
         and not (j.platform = 'opla' and public.opla_sortie_passee())
         and not exists (
           select 1 from public.cross_post_jobs d
            where d.user_id = old.user_id
              and d.inventaire_id = old.id
              and d.action = 'delete'
              and d.platform = j.platform
              and d.status in ('pending', 'processing', 'needs_user'))
       order by j.platform, coalesce(j.published_at, j.created_at) desc, j.created_at desc
    loop
      insert into public.cross_post_jobs
        (user_id, inventaire_id, platform, action, status, photo_option, title, listing_url, platform_fields)
      values
        (old.user_id, old.id, v_pub.platform, 'delete', 'pending', 'original',
         coalesce(v_pub.title, old.titre), v_pub.listing_url,
         jsonb_build_object('filet_suppression_serveur', jsonb_build_object(
           'le', now(),
           'job_publication', v_pub.id,
           'motif', 'annonce en ligne non couverte par le plan de suppression de l''app'))
         || case when v_pub.platform = 'vinted' and nullif(btrim(old.vinted_account_id::text), '') is not null
                 then jsonb_build_object('vinted_account_id', btrim(old.vinted_account_id::text))
                 else '{}'::jsonb end);
      v_n := v_n + 1;
      v_plateformes := v_plateformes || v_pub.platform;
    end loop;

    update public.cross_post_jobs
       set status = 'cancelled',
           error  = 'Annulé : l''article a été supprimé du stock'
     where user_id = old.user_id
       and inventaire_id = old.id
       and coalesce(action, 'publish') <> 'delete'
       and status in ('pending', 'processing', 'needs_user');
    get diagnostics v_annules = row_count;

    if v_n > 0 then
      insert into public.usage_logs (user_id, feature, metadata)
      values (old.user_id, 'retrait_annonces', jsonb_build_object(
        'chemin', 'suppression_article_filet_serveur',
        'plateformes', (select coalesce(jsonb_agg(p order by p), '[]'::jsonb) from unnest(v_plateformes) as p),
        'n_annonces', v_n,
        'n_articles', 1,
        'article_id', old.id::text,
        'publications_annulees', v_annules));
    end if;
  exception when others then
    raise warning 'inventaire_arme_retraits_avant_suppression (article %) : % — suppression poursuivie', old.id, sqlerrm;
  end;
  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_arme_retraits_fiche_liee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role text;
begin
  if coalesce(current_setting('fillsell.sans_retrait', true), '') = '1' then
    return old;
  end if;
  if pg_trigger_depth() > 1 then
    return old;
  end if;
  begin
    v_role := nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role';
  exception when others then
    v_role := null;
  end;
  if v_role = 'service_role' then
    return old;
  end if;

  begin
    if not exists (select 1 from public.fiches_liees_comptes f where f.fiche_a = old.id or f.fiche_b = old.id) then
      return old;
    end if;
    if exists (select 1 from public.cross_post_jobs x
                where x.user_id = old.user_id and x.inventaire_id = old.id
                  and coalesce(x.platform_fields, '{}'::jsonb) ? 'annonces_laissees_en_ligne') then
      return old;
    end if;
    if exists (select 1 from public.cross_post_jobs d
                where d.user_id = old.user_id and d.inventaire_id = old.id and d.action = 'delete'
                  and d.status in ('pending', 'processing', 'needs_user')
                  and d.created_at > now() - interval '2 minutes')
       or exists (select 1 from public.cross_post_jobs j
                   where j.user_id = old.user_id and j.inventaire_id = old.id
                     and coalesce(j.action, 'publish') in ('publish', 'republish') and j.status = 'published'
                     and nullif(btrim(j.listing_url), '') is not null
                     and not (j.platform = 'opla' and public.opla_sortie_passee())
                     and not exists (select 1 from public.cross_post_jobs d
                                      where d.user_id = old.user_id and d.inventaire_id = old.id and d.action = 'delete'
                                        and d.platform = j.platform and d.status in ('pending', 'processing', 'needs_user'))) then
      perform public.armer_retraits_fiche_liee(old.user_id, old.id, 'suppression_article_compte_relie');
    end if;
  exception when others then
    raise warning 'inventaire_arme_retraits_fiche_liee (article %) : % — suppression poursuivie', old.id, sqlerrm;
    begin
      insert into public.usage_logs (user_id, feature, metadata)
      values (old.user_id, 'retrait_partout_compte_relie_erreur', jsonb_build_object(
        'article_id', old.id::text, 'erreur', left(sqlerrm, 300)));
    exception when others then
      null;
    end;
  end;
  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_attributs_avant_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.attributs IS DISTINCT FROM OLD.attributs THEN
    NEW.attributs := public.inventaire_attributs_fusion(OLD.attributs, NEW.attributs);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_attributs_fusion(p_existants jsonb, p_nouveaux jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_out jsonb := COALESCE(p_existants, '{}'::jsonb);
  v_cle text;
  v_nouveau jsonb;
  v_ancien jsonb;
BEGIN
  IF p_nouveaux IS NULL OR jsonb_typeof(p_nouveaux) <> 'object' THEN RETURN v_out; END IF;
  FOR v_cle, v_nouveau IN SELECT key, value FROM jsonb_each(p_nouveaux) LOOP
    IF jsonb_typeof(v_nouveau) <> 'object' THEN CONTINUE; END IF;
    IF v_nouveau->'v' IS NULL OR jsonb_typeof(v_nouveau->'v') = 'null' THEN CONTINUE; END IF;
    v_ancien := v_out->v_cle;
    IF v_ancien IS NULL OR jsonb_typeof(v_ancien) <> 'object'
       OR v_ancien->'v' IS NULL OR jsonb_typeof(v_ancien->'v') = 'null'
       OR public.inventaire_attributs_rang(v_nouveau->>'source') >= public.inventaire_attributs_rang(v_ancien->>'source')
    THEN
      v_out := jsonb_set(v_out, ARRAY[v_cle], v_nouveau, true);
    END IF;
  END LOOP;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_defusionner_pour(p_user uuid, p_fusion_id uuid, p_par text DEFAULT 'utilisateur'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := p_user;
  f inventaire_fusions%ROWTYPE;
  v_ids bigint[];
  v_uids uuid[];
  v_cle text;
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'unauthorized'); END IF;
  SELECT * INTO f FROM inventaire_fusions WHERE id = p_fusion_id AND user_id = v_user FOR UPDATE;
  IF f.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'fusion_introuvable'); END IF;
  IF f.defait_le IS NOT NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'deja_defaite'); END IF;

  SELECT array_agg((x)::bigint) INTO v_ids FROM jsonb_array_elements_text(COALESCE(f.deplacements -> 'ventes', '[]'::jsonb)) x;
  IF v_ids IS NOT NULL THEN UPDATE ventes SET inventaire_id = f.absorbe WHERE id = ANY (v_ids) AND user_id = v_user; END IF;
  SELECT array_agg((x)::bigint) INTO v_ids FROM jsonb_array_elements_text(COALESCE(f.deplacements -> 'push_ventes', '[]'::jsonb)) x;
  IF v_ids IS NOT NULL THEN UPDATE push_ventes SET inventaire_id = f.absorbe WHERE id = ANY (v_ids) AND user_id = v_user; END IF;
  SELECT array_agg((x)::bigint) INTO v_ids FROM jsonb_array_elements_text(COALESCE(f.deplacements -> 'remises_en_vente', '[]'::jsonb)) x;
  IF v_ids IS NOT NULL THEN UPDATE remises_en_vente SET inventaire_id = f.absorbe WHERE id = ANY (v_ids) AND user_id = v_user; END IF;
  SELECT array_agg((x)::bigint) INTO v_ids FROM jsonb_array_elements_text(COALESCE(f.deplacements -> 'vinted_listing_snapshots', '[]'::jsonb)) x;
  IF v_ids IS NOT NULL THEN UPDATE vinted_listing_snapshots SET inventaire_id = f.absorbe WHERE id = ANY (v_ids); END IF;
  SELECT array_agg((x)::bigint) INTO v_ids FROM jsonb_array_elements_text(COALESCE(f.deplacements -> 'vinted_republish_captures', '[]'::jsonb)) x;
  IF v_ids IS NOT NULL THEN UPDATE vinted_republish_captures SET inventaire_id = f.absorbe WHERE id = ANY (v_ids); END IF;
  IF f.deplacements ? 'fiches_annonce' THEN
    UPDATE fiches_annonce SET inventaire_id = f.absorbe WHERE inventaire_id = f.garde AND user_id = v_user;
  END IF;
  SELECT array_agg((x)::uuid) INTO v_uids FROM jsonb_array_elements_text(COALESCE(f.deplacements -> 'cross_post_jobs', '[]'::jsonb)) x;
  IF v_uids IS NOT NULL THEN UPDATE cross_post_jobs SET inventaire_id = f.absorbe WHERE id = ANY (v_uids) AND user_id = v_user; END IF;
  SELECT array_agg((x)::uuid) INTO v_uids FROM jsonb_array_elements_text(COALESCE(f.deplacements -> 'annonces_plateforme', '[]'::jsonb)) x;
  IF v_uids IS NOT NULL THEN UPDATE annonces_plateforme SET inventaire_id = f.absorbe, updated_at = now() WHERE id = ANY (v_uids) AND user_id = v_user; END IF;
  SELECT array_agg((x)::uuid) INTO v_uids FROM jsonb_array_elements_text(COALESCE(f.deplacements -> 'rapprochements', '[]'::jsonb)) x;
  IF v_uids IS NOT NULL THEN UPDATE rapprochements SET inventaire_id = f.absorbe WHERE id = ANY (v_uids) AND user_id = v_user; END IF;

  FOR v_cle IN SELECT k FROM jsonb_object_keys(COALESCE(f.champs_repris, '{}'::jsonb)) k LOOP
    IF v_cle = 'prix_achat' THEN
      UPDATE inventaire SET prix_achat = NULLIF(f.champs_repris -> 'prix_achat' ->> 'avant', '')::numeric WHERE id = f.garde;
    ELSIF v_cle = 'prix_achat_inconnu' THEN
      UPDATE inventaire SET prix_achat_inconnu = NULLIF(f.champs_repris -> 'prix_achat_inconnu' ->> 'avant', '')::boolean WHERE id = f.garde;
    ELSIF v_cle = 'description' THEN
      UPDATE inventaire SET description = f.champs_repris -> 'description' ->> 'avant' WHERE id = f.garde;
    ELSIF v_cle = 'marque' THEN
      UPDATE inventaire SET marque = f.champs_repris -> 'marque' ->> 'avant' WHERE id = f.garde;
    ELSIF v_cle = 'photos' THEN
      UPDATE inventaire SET photos = CASE WHEN jsonb_typeof(f.champs_repris -> 'photos' -> 'avant') = 'null'
                                          THEN NULL ELSE f.champs_repris -> 'photos' -> 'avant' END WHERE id = f.garde;
    ELSIF v_cle = 'vinted_identite' AND COALESCE((f.champs_repris -> 'vinted_identite' ->> 'echange')::boolean, false) THEN
      UPDATE inventaire SET vinted_item_id = NULL, vinted_status = NULL, vinted_account_id = NULL WHERE id = f.absorbe;
      UPDATE inventaire SET vinted_item_id = NULL, vinted_status = NULL, vinted_account_id = NULL WHERE id = f.garde;
      UPDATE inventaire
         SET vinted_item_id = f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_item_id',
             vinted_status = f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_status',
             vinted_account_id = f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_account_id',
             vinted_catalog_id = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_catalog_id', '')::integer,
             vinted_view_count = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_view_count', '')::integer,
             vinted_favourite_count = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_favourite_count', '')::integer,
             listed_at_guess = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'listed_at_guess', '')::timestamptz,
             disparu_le = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'disparu_le', '')::timestamptz,
             last_synced_at = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'last_synced_at', '')::timestamptz
       WHERE id = f.garde;
      UPDATE inventaire
         SET vinted_item_id = f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_item_id',
             vinted_status = f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_status',
             vinted_account_id = f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_account_id',
             vinted_catalog_id = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_catalog_id', '')::integer,
             vinted_view_count = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_view_count', '')::integer,
             vinted_favourite_count = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_favourite_count', '')::integer,
             listed_at_guess = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'listed_at_guess', '')::timestamptz,
             disparu_le = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'disparu_le', '')::timestamptz,
             last_synced_at = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'last_synced_at', '')::timestamptz
       WHERE id = f.absorbe;
    ELSIF v_cle = 'vinted_identite' THEN
      UPDATE inventaire
         SET vinted_item_id = f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_item_id',
             vinted_status = f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_status',
             vinted_account_id = f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_account_id',
             vinted_catalog_id = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_catalog_id', '')::integer,
             vinted_view_count = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_view_count', '')::integer,
             vinted_favourite_count = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'vinted_favourite_count', '')::integer,
             listed_at_guess = NULLIF(f.champs_repris -> 'vinted_identite' -> 'avant' ->> 'listed_at_guess', '')::timestamptz
       WHERE id = f.garde;
      UPDATE inventaire
         SET vinted_item_id = f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_item_id',
             vinted_status = f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_status',
             vinted_account_id = f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_account_id',
             vinted_catalog_id = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_catalog_id', '')::integer,
             vinted_view_count = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_view_count', '')::integer,
             vinted_favourite_count = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'vinted_favourite_count', '')::integer,
             listed_at_guess = NULLIF(f.champs_repris -> 'vinted_identite' -> 'apres' ->> 'listed_at_guess', '')::timestamptz
       WHERE id = f.absorbe;
    ELSIF v_cle = 'attributs' THEN
      UPDATE inventaire SET attributs = CASE WHEN jsonb_typeof(f.champs_repris -> 'attributs' -> 'avant') = 'null'
                                             THEN NULL ELSE f.champs_repris -> 'attributs' -> 'avant' END WHERE id = f.garde;
    END IF;
  END LOOP;

  UPDATE inventaire SET fusionne_dans = NULL, fusionne_le = NULL WHERE id = f.absorbe AND user_id = v_user;
  UPDATE inventaire_fusions SET defait_le = now() WHERE id = f.id;
  UPDATE inventaire_doublons SET statut = 'defaite', decide_le = now(), decide_par = COALESCE(NULLIF(p_par, ''), 'utilisateur')
   WHERE user_id = v_user AND least(garde, absorbe) = least(f.garde, f.absorbe) AND greatest(garde, absorbe) = greatest(f.garde, f.absorbe);
  RETURN jsonb_build_object('ok', true, 'fusion_id', f.id, 'garde', f.garde, 'absorbe', f.absorbe);
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_disparu_garde_republication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_rep uuid;
begin
  if coalesce(current_setting('fillsell.restauration', true), '') = 'on' then return new; end if;
  if new.disparu_le is null or old.disparu_le is not null then return new; end if;
  v_rep := coalesce(public.republication_engagee(new.user_id, new.id, 'vinted'),
                    public.republication_engagee_numero(new.user_id, 'vinted', new.vinted_item_id::text));
  v_rep := coalesce(v_rep, public.republication_recreee_non_confirmee(new.user_id, 'vinted', new.id, new.vinted_item_id::text, null));
  if v_rep is not null then
    raise log 'inventaire_disparu_garde_republication : fiche % — republication Vinted % en cours, disparition non datée', new.id, v_rep;
    new.disparu_le := null;
  end if;
  return new;
exception when others then
  raise warning 'inventaire_disparu_garde_republication : fiche % : % — écriture inchangée', new.id, sqlerrm;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.inventaire_doublon_decider(p_id uuid, p_decision text, p_annonce_montree uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'unauthorized'); END IF;
  RETURN public.inventaire_doublon_decider_corps(v_user, p_id, p_decision, p_annonce_montree);
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_doublon_decider_corps(p_user uuid, p_id uuid, p_decision text, p_annonce_montree uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := p_user;
  d inventaire_doublons%ROWTYPE;
  r jsonb;
  v_job uuid; v_del uuid; v_retraits jsonb; v_sans int; v_geste boolean; v_pf_sans jsonb; v_detail text;
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'unauthorized'); END IF;
  SELECT * INTO d FROM inventaire_doublons WHERE id = p_id AND user_id = v_user FOR UPDATE;
  IF d.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'introuvable'); END IF;
  IF d.statut <> 'proposee' THEN RETURN jsonb_build_object('ok', false, 'reason', 'deja_tranchee', 'statut', d.statut); END IF;
  IF d.motif = 'copie_non_prouvee' THEN
    v_job := NULLIF(d.preuves ->> 'job', '')::uuid;
    IF p_decision = 'non' THEN
      UPDATE inventaire_doublons SET statut = 'refusee', decide_le = now(), decide_par = 'utilisateur' WHERE id = d.id;
      RETURN jsonb_build_object('ok', true, 'decision', 'non');
    ELSIF p_decision IS DISTINCT FROM 'oui' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'decision_inconnue');
    END IF;
    IF p_annonce_montree IS NULL OR p_annonce_montree::text IS DISTINCT FROM (d.preuves ->> 'annonce_id') THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'annonce_non_montree');
    END IF;
    IF v_job IS NULL OR EXISTS (
         SELECT 1 FROM cross_post_jobs j, annonces_plateforme a
          WHERE j.id = v_job AND a.id = p_annonce_montree
            AND (NULLIF(btrim(COALESCE(j.platform_listing_id, '')), '') IS NOT NULL OR NULLIF(btrim(COALESCE(j.listing_url, '')), '') IS NOT NULL)
            AND NOT listing_designe(a.listing_id, j.listing_url, j.platform_listing_id)) THEN
      IF NOT EXISTS (SELECT 1 FROM annonces_plateforme a JOIN inventaire i ON i.id = a.inventaire_id AND i.user_id = a.user_id
                      WHERE a.id = p_annonce_montree AND a.user_id = v_user AND a.inventaire_id = d.garde
                        AND a.disparu_le IS NULL AND a.retiree_le IS NULL AND i.fusionne_dans IS NULL AND i.statut = 'vendu') THEN
        UPDATE inventaire_doublons SET statut = 'caduque', decide_le = now(), decide_par = 'utilisateur' WHERE id = d.id;
        RETURN jsonb_build_object('ok', false, 'reason', 'sans_objet');
      END IF;
      v_del := armer_retrait_annonce_pour(p_annonce_montree, 'copie_confirmee_vendue', interval '0', true);
      IF v_del IS NULL THEN
        SELECT dj.id INTO v_del
          FROM cross_post_jobs dj, annonces_plateforme a
         WHERE a.id = p_annonce_montree AND dj.user_id = v_user AND dj.platform = a.platform AND dj.action = 'delete'
           AND dj.status IN ('pending', 'processing', 'needs_user') AND listing_designe(a.listing_id, dj.listing_url, dj.platform_listing_id)
         ORDER BY dj.created_at LIMIT 1;
      END IF;
      IF v_del IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'retrait_impossible', 'decision', 'oui',
                                  'plateformes', jsonb_build_array(d.preuves ->> 'platform'));
      END IF;
      UPDATE inventaire_doublons SET statut = 'confirmee', decide_le = now(), decide_par = 'utilisateur',
                                     preuves = COALESCE(preuves, '{}'::jsonb) || jsonb_build_object('retrait', v_del, 'retrait_par', 'annonce')
       WHERE id = d.id;
      RETURN jsonb_build_object('ok', true, 'decision', 'oui', 'retraits', 1, 'plateformes', jsonb_build_array(d.preuves ->> 'platform'));
    END IF;
    IF v_job IS NULL
       OR NOT EXISTS (SELECT 1 FROM inventaire i WHERE i.id = d.garde AND i.user_id = v_user AND i.fusionne_dans IS NULL AND i.statut = 'vendu')
       OR NOT EXISTS (SELECT 1 FROM cross_post_jobs j WHERE j.id = v_job AND j.user_id = v_user AND j.inventaire_id = d.garde
                       AND j.status = 'published' AND COALESCE(j.action, 'publish') IN ('publish', 'republish')) THEN
      UPDATE inventaire_doublons SET statut = 'caduque', decide_le = now(), decide_par = 'utilisateur' WHERE id = d.id;
      RETURN jsonb_build_object('ok', false, 'reason', 'sans_objet');
    END IF;
    BEGIN
      UPDATE cross_post_jobs
         SET platform_fields = COALESCE(platform_fields, '{}'::jsonb) || jsonb_build_object('rattachement',
               COALESCE(platform_fields -> 'rattachement', '{}'::jsonb) || jsonb_build_object(
                 'par', 'utilisateur', 'motif', 'meme_article_confirme',
                 'confirme', jsonb_build_object('question', d.id, 'le', now(),
                   'avant', jsonb_build_object('par', platform_fields #> '{rattachement,par}',
                                               'motif', platform_fields #> '{rattachement,motif}'))))
       WHERE id = v_job;
      v_del := armer_retrait_job_pour(v_job, 'copie_confirmee_vendue', interval '0', true);
      IF v_del IS NULL THEN
        SELECT dj.id INTO v_del
          FROM cross_post_jobs j JOIN cross_post_jobs dj ON dj.id = NULLIF(j.platform_fields -> 'retrait_arme' ->> 'job', '')::uuid
         WHERE j.id = v_job AND dj.action = 'delete' AND dj.status IN ('pending', 'processing', 'needs_user');
      END IF;
      IF v_del IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0R01', MESSAGE = 'retrait_impossible', DETAIL = jsonb_build_array(d.preuves ->> 'platform')::text;
      END IF;
      UPDATE inventaire_doublons SET statut = 'confirmee', decide_le = now(), decide_par = 'utilisateur',
                                     preuves = COALESCE(preuves, '{}'::jsonb) || jsonb_build_object('retrait', v_del)
       WHERE id = d.id;
      RETURN jsonb_build_object('ok', true, 'decision', 'oui', 'retraits', 1, 'plateformes', jsonb_build_array(d.preuves ->> 'platform'));
    EXCEPTION WHEN SQLSTATE 'P0R01' THEN
      GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
      RETURN jsonb_build_object('ok', false, 'reason', 'retrait_impossible', 'decision', 'oui',
                                'plateformes', COALESCE(NULLIF(v_detail, '')::jsonb, '[]'::jsonb));
    END;
  END IF;
  IF p_decision = 'non' THEN
    UPDATE inventaire_doublons SET statut = 'refusee', decide_le = now(), decide_par = 'utilisateur' WHERE id = d.id;
    RETURN jsonb_build_object('ok', true, 'decision', 'non');
  ELSIF p_decision = 'oui' THEN
    IF NOT EXISTS (SELECT 1 FROM inventaire WHERE id = d.garde AND user_id = v_user AND fusionne_dans IS NULL)
       OR NOT EXISTS (SELECT 1 FROM inventaire WHERE id = d.absorbe AND user_id = v_user AND fusionne_dans IS NULL) THEN
      UPDATE inventaire_doublons SET statut = 'caduque', decide_le = now(), decide_par = 'utilisateur' WHERE id = d.id;
      RETURN jsonb_build_object('ok', false, 'reason', 'fiche_introuvable');
    END IF;
    IF EXISTS (SELECT 1 FROM inventaire WHERE id = d.garde AND statut = 'vendu')
       AND (EXISTS (SELECT 1 FROM annonces_plateforme ap
                     WHERE ap.user_id = v_user AND ap.inventaire_id = d.absorbe
                       AND ap.disparu_le IS NULL AND ap.retiree_le IS NULL)
            OR EXISTS (SELECT 1 FROM cross_post_jobs j
                        WHERE j.user_id = v_user AND j.inventaire_id = d.absorbe AND j.status = 'published'
                          AND COALESCE(j.action, 'publish') IN ('publish', 'republish'))) THEN
      UPDATE inventaire_doublons SET statut = 'refusee', decide_le = now(), decide_par = 'utilisateur',
             preuves = COALESCE(preuves, '{}'::jsonb) || jsonb_build_object(
               'reponse', p_decision, 'issue', 'article_a_part_annonce_en_ligne', 'le', now())
       WHERE id = d.id;
      INSERT INTO usage_logs (user_id, feature, metadata)
      VALUES (v_user, 'doublon_vendu_article_a_part', jsonb_build_object(
        'doublon', d.id, 'garde', d.garde::text, 'absorbe', d.absorbe::text, 'motif', d.motif, 'reponse', p_decision));
      RETURN jsonb_build_object('ok', true, 'decision', p_decision, 'retraits', 0, 'article_a_part', true);
    END IF;
    IF EXISTS (SELECT 1 FROM inventaire WHERE id = d.garde AND statut = 'vendu') THEN
      BEGIN
        r := inventaire_fusionner_pour(v_user, d.garde, d.absorbe, 'utilisateur (doublon proposé)');
        IF NOT COALESCE((r ->> 'ok')::boolean, false) THEN
          IF r ->> 'reason' = 'deux_annonces_meme_plateforme' THEN
            UPDATE inventaire_doublons
               SET preuves = COALESCE(preuves, '{}'::jsonb) || jsonb_build_object('fusion_refusee', jsonb_build_object(
                     'motif', 'deux_annonces_meme_plateforme', 'plateformes', r -> 'plateformes', 'message', r ->> 'message', 'le', now()))
             WHERE id = d.id AND statut = 'proposee';
          END IF;
          RETURN r || jsonb_build_object('decision', 'oui');
        END IF;
        FOR v_job IN
          SELECT j.id FROM cross_post_jobs j
           WHERE j.id IN (SELECT (x)::uuid FROM jsonb_array_elements_text(COALESCE(r -> 'deplacements' -> 'cross_post_jobs', '[]'::jsonb)) x)
             AND j.status = 'published' AND COALESCE(j.action, 'publish') IN ('publish', 'republish')
        LOOP
          v_geste := p_annonce_montree IS NOT NULL AND EXISTS (
            SELECT 1 FROM annonces_plateforme ap
             WHERE ap.id = p_annonce_montree AND ap.user_id = v_user AND ap.job_id = v_job AND ap.disparu_le IS NULL
               AND ap.id IN (SELECT (x)::uuid FROM jsonb_array_elements_text(COALESCE(r -> 'deplacements' -> 'annonces_plateforme', '[]'::jsonb)) x));
          v_del := armer_retrait_job_pour(v_job, 'doublon_vendu_confirme', interval '0', v_geste);
        END LOOP;
        SELECT COALESCE(jsonb_agg(DISTINCT dj.id::text), '[]'::jsonb) INTO v_retraits
          FROM cross_post_jobs j JOIN cross_post_jobs dj ON dj.id = NULLIF(j.platform_fields -> 'retrait_arme' ->> 'job', '')::uuid
         WHERE j.id IN (SELECT (x)::uuid FROM jsonb_array_elements_text(COALESCE(r -> 'deplacements' -> 'cross_post_jobs', '[]'::jsonb)) x)
           AND dj.action = 'delete' AND dj.status IN ('pending', 'processing', 'needs_user');
        SELECT count(*) INTO v_sans
          FROM annonces_plateforme ap
         WHERE ap.id IN (SELECT (x)::uuid FROM jsonb_array_elements_text(COALESCE(r -> 'deplacements' -> 'annonces_plateforme', '[]'::jsonb)) x)
           AND ap.disparu_le IS NULL
           AND NOT EXISTS (SELECT 1 FROM cross_post_jobs j JOIN cross_post_jobs dj ON dj.id = NULLIF(j.platform_fields -> 'retrait_arme' ->> 'job', '')::uuid
                            WHERE j.id = ap.job_id AND dj.action = 'delete' AND dj.status IN ('pending', 'processing', 'needs_user'));
        IF v_sans > 0 THEN
          SELECT COALESCE(jsonb_agg(DISTINCT ap.platform), '[]'::jsonb) INTO v_pf_sans
            FROM annonces_plateforme ap
           WHERE ap.id IN (SELECT (x)::uuid FROM jsonb_array_elements_text(COALESCE(r -> 'deplacements' -> 'annonces_plateforme', '[]'::jsonb)) x)
             AND ap.disparu_le IS NULL
             AND NOT EXISTS (SELECT 1 FROM cross_post_jobs j JOIN cross_post_jobs dj ON dj.id = NULLIF(j.platform_fields -> 'retrait_arme' ->> 'job', '')::uuid
                              WHERE j.id = ap.job_id AND dj.action = 'delete' AND dj.status IN ('pending', 'processing', 'needs_user'));
          RAISE EXCEPTION USING ERRCODE = 'P0R01', MESSAGE = 'retrait_impossible', DETAIL = v_pf_sans::text;
        END IF;
        UPDATE inventaire_doublons SET statut = 'fusionnee', decide_le = now(), decide_par = 'utilisateur',
                                       fusion_id = NULLIF(r ->> 'fusion_id', '')::uuid,
                                       preuves = COALESCE(preuves, '{}'::jsonb) || jsonb_build_object('retraits_oui', v_retraits)
         WHERE id = d.id;
        RETURN r || jsonb_build_object('decision', 'oui', 'retraits', jsonb_array_length(v_retraits));
      EXCEPTION WHEN SQLSTATE 'P0R01' THEN
        GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
        RETURN jsonb_build_object('ok', false, 'reason', 'retrait_impossible', 'decision', 'oui',
                                  'plateformes', COALESCE(NULLIF(v_detail, '')::jsonb, '[]'::jsonb));
      END;
    END IF;
    r := inventaire_fusionner_pour(v_user, d.garde, d.absorbe, 'utilisateur (doublon proposé)');
    IF r ->> 'reason' = 'deux_annonces_meme_plateforme' THEN
      UPDATE inventaire_doublons
         SET preuves = COALESCE(preuves, '{}'::jsonb) || jsonb_build_object('fusion_refusee', jsonb_build_object(
               'motif', 'deux_annonces_meme_plateforme', 'plateformes', r -> 'plateformes', 'message', r ->> 'message', 'le', now()))
       WHERE id = d.id AND statut = 'proposee';
    END IF;
    IF COALESCE((r ->> 'ok')::boolean, false) THEN
      UPDATE inventaire_doublons SET statut = 'fusionnee', decide_le = now(), decide_par = 'utilisateur',
                                     fusion_id = NULLIF(r ->> 'fusion_id', '')::uuid
       WHERE id = d.id;
    END IF;
    RETURN r || jsonb_build_object('decision', 'oui');
  END IF;
  RETURN jsonb_build_object('ok', false, 'reason', 'decision_inconnue');
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_doublons_a_verifier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id bigint;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.statut = 'proposee' THEN RETURN NULL; END IF;
  FOREACH v_id IN ARRAY ARRAY[OLD.garde, OLD.absorbe] LOOP
    UPDATE inventaire i SET a_verifier = NULL
     WHERE i.id = v_id AND i.a_verifier IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM inventaire_doublons d
                        WHERE d.user_id = OLD.user_id AND d.statut = 'proposee' AND d.id <> OLD.id
                          AND (d.garde = v_id OR d.absorbe = v_id));
  END LOOP;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_doublons_attribut_distinctif()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_raison text;
BEGIN
  IF NEW.statut IS DISTINCT FROM 'proposee' OR NEW.motif = 'copie_non_prouvee'
     OR NEW.garde IS NULL OR NEW.absorbe IS NULL OR NEW.garde = NEW.absorbe THEN
    RETURN NEW;
  END IF;
  BEGIN
    v_raison := doublon_ecarte_par_regle(NEW.user_id, NEW.garde, NEW.absorbe);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'inventaire_doublons_attribut_distinctif (% / %): %', NEW.garde, NEW.absorbe, SQLERRM;
    RETURN NEW;
  END;
  IF v_raison IS NOT NULL THEN
    INSERT INTO doublons_ecartes_par_regle (user_id, garde, absorbe, motif, source, raison)
    VALUES (NEW.user_id, NEW.garde, NEW.absorbe, NEW.motif, NEW.source, v_raison);
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_doublons_jamais_deux_exemplaires()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_vendue bigint; v_en_ligne bigint; v_pf_vendue text[]; v_pf_question text[];
BEGIN
  IF NEW.motif IS DISTINCT FROM 'homonyme_vendu' OR NEW.statut IS DISTINCT FROM 'proposee' THEN
    RETURN NEW;
  END IF;
  BEGIN
    SELECT CASE WHEN g.statut = 'vendu' THEN g.id WHEN a.statut = 'vendu' THEN a.id END,
           CASE WHEN g.statut = 'vendu' THEN a.id WHEN a.statut = 'vendu' THEN g.id END
      INTO v_vendue, v_en_ligne
      FROM inventaire g, inventaire a WHERE g.id = NEW.garde AND a.id = NEW.absorbe;
    IF v_vendue IS NULL THEN RETURN NEW; END IF;

    SELECT ARRAY(SELECT DISTINCT x FROM (
             SELECT CASE WHEN i.vinted_item_id IS NOT NULL OR i.origine = 'vinted_sync' THEN 'vinted' END x FROM inventaire i WHERE i.id = v_vendue
             UNION ALL SELECT CASE WHEN i.origine LIKE 'releve\_%' THEN substr(i.origine, 8) END FROM inventaire i WHERE i.id = v_vendue
             UNION ALL SELECT ap.platform FROM annonces_plateforme ap WHERE ap.inventaire_id = v_vendue
             UNION ALL SELECT j.platform FROM cross_post_jobs j WHERE j.inventaire_id = v_vendue AND j.status = 'published' AND j.action IN ('publish', 'republish')
           ) z WHERE x IS NOT NULL)
      INTO v_pf_vendue;

    IF NEW.preuves ? 'platform' AND NULLIF(NEW.preuves ->> 'platform', '') IS NOT NULL THEN
      v_pf_question := ARRAY[NEW.preuves ->> 'platform'];
    ELSE
      SELECT ARRAY(SELECT DISTINCT x FROM (
               SELECT CASE WHEN i.vinted_item_id IS NOT NULL AND i.disparu_le IS NULL THEN 'vinted' END x FROM inventaire i WHERE i.id = v_en_ligne
               UNION ALL SELECT ap.platform FROM annonces_plateforme ap WHERE ap.inventaire_id = v_en_ligne AND ap.disparu_le IS NULL
             ) z WHERE x IS NOT NULL)
        INTO v_pf_question;
    END IF;

    IF v_pf_vendue && v_pf_question THEN
      RETURN NULL;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'inventaire_doublons_jamais_deux_exemplaires (% / %): %', NEW.garde, NEW.absorbe, SQLERRM;
  END;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inventaire_ecarte_import_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_motif text;
begin
  if coalesce(new.origine,'') <> 'vinted_sync' then
    return new;
  end if;

  if TG_OP = 'UPDATE' and new.vinted_item_id is null then
    return new;
  end if;

  if public.boutique_vinted_autre_compte(new.user_id, new.vinted_account_id) then
    raise exception '[boutique_a_confirmer][boutique_autre_compte] Cette boutique Vinted est déjà suivie par un autre compte FillSell. Rien n’a été importé et rien n’a changé sur Vinted : une boutique se suit sur un seul compte.';
  end if;
  if not boutique_vinted_confirmee(new.user_id,new.vinted_account_id) then
    raise exception '[boutique_a_confirmer] Cette boutique Vinted n’est pas confirmée sur ton compte FillSell. Confirme-la dans « Actualiser mon dressing » si elle t’appartient. Aucun article n’a été importé.';
  end if;
  if TG_OP='UPDATE' then return new; end if;

  if exists (
    select 1 from inventaire i
    where i.user_id = new.user_id
      and i.vinted_item_id is not distinct from new.vinted_item_id
  ) then
    return new;
  end if;

  if public.annonce_publiee_par_compte_lie(new.user_id, 'vinted', new.vinted_item_id)
     and not public.annonce_publiee_par_compte(new.user_id, 'vinted', new.vinted_item_id) then
    insert into sync_import_ecartes (user_id, vinted_item_id, vinted_status, titre, motif)
    values (new.user_id, new.vinted_item_id, new.vinted_status, left(coalesce(new.titre,''),120), 'compte_relie:vinted');
    return null;
  end if;

  if exists (
    select 1 from vinted_sync_runs r
    where r.user_id = new.user_id and r.kind = 'dressing' and r.status = 'running'
      and not releve_est_geste(r.declencheur)
  ) then
    raise log 'inventaire_ecarte_import_sync : article % non importé (relevé automatique en cours, user %)', new.vinted_item_id, new.user_id;
    return null;
  end if;

  if new.vinted_status = 'draft' then
    v_motif := 'brouillon';
  elsif new.photos is null
     or jsonb_typeof(new.photos) <> 'array'
     or jsonb_array_length(new.photos) = 0 then
    v_motif := 'sans_photo';
  else
    return new;
  end if;

  insert into sync_import_ecartes (user_id, vinted_item_id, vinted_status, titre, motif)
  values (new.user_id, new.vinted_item_id, new.vinted_status, left(coalesce(new.titre,''),120), v_motif);

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_fusionner_pour(p_user uuid, p_garde bigint, p_absorbe bigint, p_par text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := p_user;
  g inventaire%ROWTYPE;
  a inventaire%ROWTYPE;
  v_dep jsonb := '{}'::jsonb;
  v_champs jsonb := '{}'::jsonb;
  v_ids jsonb;
  v_attr jsonb;
  v_cle text;
  v_id uuid;
  v_geste boolean := COALESCE(p_par, '') = 'utilisateur' OR COALESCE(p_par, '') LIKE 'utilisateur (%';
  v_conflits jsonb;
  v_remise_annulee boolean := false;
BEGIN
  IF COALESCE(p_par, '') NOT LIKE 'utilisateur%' AND COALESCE(p_par, '') NOT LIKE 'ia (%'
     AND COALESCE(p_par, '') NOT IN ('auto:photo_rapprochement_v3 (photo_identique)',
                                     'auto:photo_rapprochement_v3_main (photo_identique)',
                                     'auto:photo_rapprochement_v3_remise (photo_identique)') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'confirmation_utilisateur_requise');
  END IF;
  IF v_user IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'unauthorized'); END IF;
  IF p_garde IS NULL OR p_absorbe IS NULL OR p_garde = p_absorbe THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'articles_identiques');
  END IF;
  SELECT * INTO g FROM inventaire WHERE id = p_garde AND user_id = v_user FOR UPDATE;
  SELECT * INTO a FROM inventaire WHERE id = p_absorbe AND user_id = v_user FOR UPDATE;
  IF g.id IS NULL OR a.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'article_introuvable'); END IF;
  IF g.fusionne_dans IS NOT NULL OR a.fusionne_dans IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'deja_fusionne');
  END IF;
  v_remise_annulee := v_geste AND COALESCE(public.vinted_remise_apres_annulation(p_garde, p_absorbe), false);

  IF COALESCE(g.quantite, 1) <= 1 THEN
    WITH l AS (
      SELECT CASE WHEN ap.inventaire_id = p_garde THEN 'g' ELSE 'a' END AS cote, ap.platform, btrim(ap.listing_id) AS lid, ap.id AS annonce
        FROM annonces_plateforme ap
       WHERE ap.inventaire_id IN (p_garde, p_absorbe) AND ap.user_id = v_user
         AND ap.disparu_le IS NULL AND ap.retiree_le IS NULL AND ap.ignoree_le IS NULL
      UNION ALL
      SELECT CASE WHEN j.inventaire_id = p_garde THEN 'g' ELSE 'a' END, j.platform,
             COALESCE(NULLIF(btrim(j.platform_listing_id), ''), 'job:' || j.id::text), NULL::uuid
        FROM cross_post_jobs j
       WHERE j.inventaire_id IN (p_garde, p_absorbe) AND j.user_id = v_user AND j.platform <> 'vinted'
         AND j.status = 'published' AND COALESCE(j.action, 'publish') IN ('publish', 'republish')
         AND NOT EXISTS (SELECT 1 FROM annonces_plateforme x WHERE x.job_id = j.id)
      UNION ALL
      SELECT 'g', 'vinted', btrim(g.vinted_item_id), NULL::uuid
       WHERE NULLIF(btrim(COALESCE(g.vinted_item_id, '')), '') IS NOT NULL AND g.disparu_le IS NULL
      UNION ALL
      SELECT 'a', 'vinted', btrim(a.vinted_item_id), NULL::uuid
       WHERE NULLIF(btrim(COALESCE(a.vinted_item_id, '')), '') IS NOT NULL AND a.disparu_le IS NULL)
    SELECT jsonb_agg(DISTINCT x.platform) INTO v_conflits
      FROM l x JOIN l y ON y.platform = x.platform AND y.cote = 'g'
     WHERE x.cote = 'a' AND x.lid IS DISTINCT FROM y.lid
       AND NOT (x.annonce IS NOT NULL AND y.annonce IS NOT NULL
                AND COALESCE(rapprochement_republication_prouvee(x.annonce, y.annonce), false))
       AND NOT (x.platform = 'vinted' AND (COALESCE(vinted_remise_en_ligne(g.id, a.id), false)
                                           OR v_remise_annulee
                                           OR COALESCE(vinted_retraits_successifs(g.id, a.id), false)));
    IF v_conflits IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'deux_annonces_meme_plateforme', 'plateformes', v_conflits,
        'message', 'Cette fiche a déjà une annonce '
                   || (SELECT string_agg(CASE p WHEN 'leboncoin' THEN 'Leboncoin' WHEN 'ebay' THEN 'eBay' WHEN 'beebs' THEN 'Beebs'
                                                WHEN 'depop' THEN 'Depop' WHEN 'vinted' THEN 'Vinted' WHEN 'opla' THEN 'Opla' ELSE p END, ' et une annonce ')
                         FROM jsonb_array_elements_text(v_conflits) p)
                   || ' en ligne, et l''autre fiche en '
                   || CASE WHEN jsonb_array_length(v_conflits) > 1 THEN 'a d''autres' ELSE 'a une autre' END
                   || ' : deux annonces d''une même plateforme, ce sont deux exemplaires. Rien n''a été regroupé.');
    END IF;
  END IF;

  SELECT jsonb_agg(id) INTO v_ids FROM ventes WHERE inventaire_id = p_absorbe AND user_id = v_user;
  IF v_ids IS NOT NULL THEN
    UPDATE ventes SET inventaire_id = p_garde WHERE inventaire_id = p_absorbe AND user_id = v_user;
    v_dep := v_dep || jsonb_build_object('ventes', v_ids);
  END IF;

  SELECT jsonb_agg(id) INTO v_ids FROM cross_post_jobs WHERE inventaire_id = p_absorbe AND user_id = v_user;
  IF v_ids IS NOT NULL THEN
    UPDATE cross_post_jobs SET inventaire_id = p_garde WHERE inventaire_id = p_absorbe AND user_id = v_user;
    v_dep := v_dep || jsonb_build_object('cross_post_jobs', v_ids);
  END IF;

  SELECT jsonb_agg(id) INTO v_ids FROM annonces_plateforme WHERE inventaire_id = p_absorbe AND user_id = v_user;
  IF v_ids IS NOT NULL THEN
    UPDATE annonces_plateforme SET inventaire_id = p_garde,
           source_rapprochement = CASE WHEN v_geste THEN 'manuel' ELSE source_rapprochement END,
           proposition = NULL, updated_at = now()
     WHERE inventaire_id = p_absorbe AND user_id = v_user;
    v_dep := v_dep || jsonb_build_object('annonces_plateforme', v_ids);
  END IF;

  SELECT jsonb_agg(id) INTO v_ids FROM vinted_listing_snapshots WHERE inventaire_id = p_absorbe;
  IF v_ids IS NOT NULL THEN
    UPDATE vinted_listing_snapshots SET inventaire_id = p_garde WHERE inventaire_id = p_absorbe;
    v_dep := v_dep || jsonb_build_object('vinted_listing_snapshots', v_ids);
  END IF;
  SELECT jsonb_agg(id) INTO v_ids FROM vinted_republish_captures WHERE inventaire_id = p_absorbe;
  IF v_ids IS NOT NULL THEN
    UPDATE vinted_republish_captures SET inventaire_id = p_garde WHERE inventaire_id = p_absorbe;
    v_dep := v_dep || jsonb_build_object('vinted_republish_captures', v_ids);
  END IF;
  IF EXISTS (SELECT 1 FROM fiches_annonce WHERE inventaire_id = p_absorbe AND user_id = v_user)
     AND NOT EXISTS (SELECT 1 FROM fiches_annonce WHERE inventaire_id = p_garde AND user_id = v_user) THEN
    UPDATE fiches_annonce SET inventaire_id = p_garde WHERE inventaire_id = p_absorbe AND user_id = v_user;
    v_dep := v_dep || jsonb_build_object('fiches_annonce', jsonb_build_array(p_absorbe));
  END IF;
  SELECT jsonb_agg(id) INTO v_ids FROM push_ventes WHERE inventaire_id = p_absorbe AND user_id = v_user;
  IF v_ids IS NOT NULL THEN
    UPDATE push_ventes SET inventaire_id = p_garde WHERE inventaire_id = p_absorbe AND user_id = v_user;
    v_dep := v_dep || jsonb_build_object('push_ventes', v_ids);
  END IF;
  SELECT jsonb_agg(id) INTO v_ids FROM remises_en_vente WHERE inventaire_id = p_absorbe AND user_id = v_user;
  IF v_ids IS NOT NULL THEN
    UPDATE remises_en_vente SET inventaire_id = p_garde WHERE inventaire_id = p_absorbe AND user_id = v_user;
    v_dep := v_dep || jsonb_build_object('remises_en_vente', v_ids);
  END IF;
  SELECT jsonb_agg(id) INTO v_ids FROM rapprochements WHERE inventaire_id = p_absorbe AND user_id = v_user;
  IF v_ids IS NOT NULL THEN
    UPDATE rapprochements SET inventaire_id = p_garde WHERE inventaire_id = p_absorbe AND user_id = v_user;
    v_dep := v_dep || jsonb_build_object('rapprochements', v_ids);
  END IF;

  IF g.prix_achat IS NULL AND COALESCE(g.prix_achat_inconnu, false) = false
     AND (a.prix_achat IS NOT NULL OR COALESCE(a.prix_achat_inconnu, false) = true) THEN
    UPDATE inventaire SET prix_achat = a.prix_achat, prix_achat_inconnu = a.prix_achat_inconnu WHERE id = p_garde;
    v_champs := v_champs || jsonb_build_object(
      'prix_achat', jsonb_build_object('avant', NULL, 'apres', a.prix_achat),
      'prix_achat_inconnu', jsonb_build_object('avant', g.prix_achat_inconnu, 'apres', a.prix_achat_inconnu));
  END IF;

  IF NULLIF(trim(COALESCE(g.description, '')), '') IS NULL AND NULLIF(trim(COALESCE(a.description, '')), '') IS NOT NULL THEN
    UPDATE inventaire SET description = a.description WHERE id = p_garde;
    v_champs := v_champs || jsonb_build_object('description', jsonb_build_object('avant', g.description, 'apres', a.description));
  END IF;
  IF NULLIF(trim(COALESCE(g.marque, '')), '') IS NULL AND NULLIF(trim(COALESCE(a.marque, '')), '') IS NOT NULL THEN
    UPDATE inventaire SET marque = a.marque WHERE id = p_garde;
    v_champs := v_champs || jsonb_build_object('marque', jsonb_build_object('avant', g.marque, 'apres', a.marque));
  END IF;
  IF (g.photos IS NULL OR jsonb_typeof(g.photos) <> 'array' OR jsonb_array_length(g.photos) = 0)
     AND jsonb_typeof(a.photos) = 'array' AND jsonb_array_length(a.photos) > 0 THEN
    UPDATE inventaire SET photos = a.photos WHERE id = p_garde;
    v_champs := v_champs || jsonb_build_object('photos', jsonb_build_object('avant', g.photos, 'apres', a.photos));
  END IF;
  IF jsonb_typeof(a.attributs) = 'object' THEN
    v_attr := COALESCE(g.attributs, '{}'::jsonb);
    FOR v_cle IN SELECT k FROM jsonb_object_keys(a.attributs) k LOOP
      IF NOT (v_attr ? v_cle) THEN v_attr := v_attr || jsonb_build_object(v_cle, a.attributs -> v_cle); END IF;
    END LOOP;
    IF v_attr <> COALESCE(g.attributs, '{}'::jsonb) THEN
      UPDATE inventaire SET attributs = v_attr WHERE id = p_garde;
      v_champs := v_champs || jsonb_build_object('attributs', jsonb_build_object('avant', g.attributs, 'apres', v_attr));
    END IF;
  END IF;

  IF g.vinted_item_id IS NULL AND a.vinted_item_id IS NOT NULL AND a.disparu_le IS NULL THEN
    UPDATE inventaire SET vinted_item_id = NULL, vinted_status = NULL, vinted_account_id = NULL WHERE id = p_absorbe;
    UPDATE inventaire
       SET vinted_item_id = a.vinted_item_id, vinted_status = a.vinted_status, vinted_account_id = a.vinted_account_id,
           vinted_catalog_id = COALESCE(g.vinted_catalog_id, a.vinted_catalog_id),
           vinted_view_count = a.vinted_view_count, vinted_favourite_count = a.vinted_favourite_count,
           listed_at_guess = COALESCE(g.listed_at_guess, a.listed_at_guess)
     WHERE id = p_garde;
    v_champs := v_champs || jsonb_build_object('vinted_identite', jsonb_build_object(
      'avant', jsonb_build_object('vinted_item_id', g.vinted_item_id, 'vinted_status', g.vinted_status,
                                  'vinted_account_id', g.vinted_account_id, 'vinted_catalog_id', g.vinted_catalog_id,
                                  'vinted_view_count', g.vinted_view_count, 'vinted_favourite_count', g.vinted_favourite_count,
                                  'listed_at_guess', g.listed_at_guess),
      'apres', jsonb_build_object('vinted_item_id', a.vinted_item_id, 'vinted_status', a.vinted_status,
                                  'vinted_account_id', a.vinted_account_id, 'vinted_catalog_id', a.vinted_catalog_id,
                                  'vinted_view_count', a.vinted_view_count, 'vinted_favourite_count', a.vinted_favourite_count,
                                  'listed_at_guess', a.listed_at_guess)));
  ELSIF g.vinted_item_id IS NOT NULL AND a.vinted_item_id IS NOT NULL
        AND (vinted_remise_en_ligne(g.id, a.id) OR vinted_retraits_successifs(g.id, a.id) OR v_remise_annulee) THEN
    UPDATE inventaire SET vinted_item_id = NULL, vinted_status = NULL, vinted_account_id = NULL WHERE id = p_absorbe;
    UPDATE inventaire
       SET vinted_item_id = a.vinted_item_id, vinted_status = a.vinted_status, vinted_account_id = a.vinted_account_id,
           vinted_catalog_id = COALESCE(a.vinted_catalog_id, g.vinted_catalog_id),
           vinted_view_count = a.vinted_view_count, vinted_favourite_count = a.vinted_favourite_count,
           listed_at_guess = COALESCE(g.listed_at_guess, a.listed_at_guess),
           disparu_le = a.disparu_le, last_synced_at = COALESCE(a.last_synced_at, g.last_synced_at)
     WHERE id = p_garde;
    UPDATE inventaire
       SET vinted_item_id = g.vinted_item_id, vinted_status = g.vinted_status, vinted_account_id = g.vinted_account_id,
           disparu_le = g.disparu_le
     WHERE id = p_absorbe;
    v_champs := v_champs || jsonb_build_object('vinted_identite', jsonb_build_object(
      'echange', true,
      'avant', jsonb_build_object('vinted_item_id', g.vinted_item_id, 'vinted_status', g.vinted_status,
                                  'vinted_account_id', g.vinted_account_id, 'vinted_catalog_id', g.vinted_catalog_id,
                                  'vinted_view_count', g.vinted_view_count, 'vinted_favourite_count', g.vinted_favourite_count,
                                  'listed_at_guess', g.listed_at_guess, 'disparu_le', g.disparu_le, 'last_synced_at', g.last_synced_at),
      'apres', jsonb_build_object('vinted_item_id', a.vinted_item_id, 'vinted_status', a.vinted_status,
                                  'vinted_account_id', a.vinted_account_id, 'vinted_catalog_id', a.vinted_catalog_id,
                                  'vinted_view_count', a.vinted_view_count, 'vinted_favourite_count', a.vinted_favourite_count,
                                  'listed_at_guess', a.listed_at_guess, 'disparu_le', a.disparu_le, 'last_synced_at', a.last_synced_at)));
  END IF;

  UPDATE inventaire SET fusionne_dans = p_garde, fusionne_le = now() WHERE id = p_absorbe;

  INSERT INTO inventaire_fusions (user_id, garde, absorbe, deplacements, champs_repris, par)
  VALUES (v_user, p_garde, p_absorbe, v_dep, v_champs, COALESCE(NULLIF(p_par, ''), 'utilisateur'))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok', true, 'fusion_id', v_id, 'garde', p_garde, 'absorbe', p_absorbe,
                            'deplacements', v_dep, 'champs_repris', v_champs);
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_rattache_recreation_vinted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_titre text;
  v_t timestamptz;
  v_n integer := 0;
  v_job record;
  c record;
  v_pf jsonb;
  v_garde text;
begin
  if coalesce(new.origine, '') <> 'vinted_sync' or nullif(btrim(coalesce(new.vinted_item_id, '')), '') is null
     or new.listed_at_guess is null then
    return new;
  end if;
  begin
    if exists (select 1 from inventaire i where i.user_id = new.user_id and i.vinted_item_id = new.vinted_item_id) then
      return new;
    end if;
    v_titre := recreation_vinted_titre_norm(new.titre);
    if v_titre = '' then return new; end if;
    v_t := new.listed_at_guess;

    for c in
      select j.id, j.status, j.inventaire_id, j.title, j.platform_fields as pf,
             i.vinted_item_id as fiche_numero
        from cross_post_jobs j
        join inventaire i on i.id = j.inventaire_id and i.user_id = j.user_id
       where j.user_id = new.user_id and j.platform = 'vinted' and j.action = 'republish'
         and j.created_at > now() - interval '30 days'
         and (
               (j.status in ('pending', 'needs_user') and j.platform_fields ->> 'republish_step' = 'deleted')
            or (j.status = 'published' and j.platform_fields ->> 'republish_step' = 'recreated'
                and coalesce(j.published_at, j.created_at) > now() - interval '3 days')
         )
         and recreation_vinted_titre_norm(coalesce(nullif(j.platform_fields -> 'republish_snapshot' ->> 'titre', ''), j.title)) = v_titre
         and new.vinted_item_id is distinct from nullif(btrim(coalesce(j.platform_fields ->> 'vinted_item_id', '')), '')
         and new.vinted_item_id is distinct from nullif(btrim(coalesce(j.platform_fields ->> 'old_vinted_item_id', '')), '')
         and (new.vinted_account_id is null
              or coalesce(nullif(j.platform_fields ->> 'vinted_account_id', ''), i.vinted_account_id) is null
              or coalesce(nullif(j.platform_fields ->> 'vinted_account_id', ''), i.vinted_account_id) = new.vinted_account_id)
         and recreation_vinted_retrait_le(j.platform_fields) is not null
         and v_t >= recreation_vinted_retrait_le(j.platform_fields) - interval '2 minutes'
         and exists (select 1 from unnest(recreation_vinted_envois(j.platform_fields)) e
                      where v_t >= e - interval '2 minutes' and v_t <= e + interval '20 minutes')
    loop
      v_n := v_n + 1;
      v_job := c;
    end loop;
    if v_n <> 1 then return new; end if;

    v_pf := coalesce(v_job.pf, '{}'::jsonb);

    if v_job.status in ('pending', 'needs_user') then
      update inventaire
         set vinted_item_id = new.vinted_item_id, disparu_le = null,
             listed_at_guess = new.listed_at_guess, vinted_status = coalesce(new.vinted_status, vinted_status),
             vinted_view_count = new.vinted_view_count, vinted_favourite_count = new.vinted_favourite_count,
             vinted_account_id = coalesce(vinted_account_id, new.vinted_account_id),
             last_synced_at = coalesce(new.last_synced_at, now())
       where id = v_job.inventaire_id and user_id = new.user_id
         and vinted_item_id is not distinct from v_job.fiche_numero;
      if not found then return new; end if;
      update cross_post_jobs
         set status = 'published', error = null,
             listing_url = 'https://www.vinted.fr/items/' || new.vinted_item_id,
             platform_listing_id = new.vinted_item_id,
             published_at = v_t,
             platform_fields = (v_pf - 'next_action_after' - 'needs_user_source' - 'error_technique' - 'recreation_retries'
                                - 'processing_since' - 'depot_incertain' - 'recreation_attente_releve')
               || jsonb_build_object(
                    'republish_step', 'recreated', 'recreated_at', v_t,
                    'old_vinted_item_id', coalesce(nullif(v_pf ->> 'vinted_item_id', ''), v_job.fiche_numero),
                    'new_vinted_item_id', new.vinted_item_id,
                    'reconciliation', 'remise en ligne retrouvée au relevé du dressing (numéro inconnu, heure d''un de nos envois, même titre, même boutique)',
                    'rattachement_releve', jsonb_build_object('le', now(), 'numero', new.vinted_item_id, 'mise_en_ligne', v_t,
                      'statut_avant', v_job.status, 'pose_par', 'inventaire_rattache_recreation_vinted'))
       where id = v_job.id;
      raise log 'inventaire_rattache_recreation_vinted : republication % rattachée à % (fiche %)', v_job.id, new.vinted_item_id, v_job.inventaire_id;
      return null;
    end if;

    v_garde := coalesce(nullif(v_pf ->> 'new_vinted_item_id', ''), v_job.fiche_numero);
    if v_garde is null or v_garde = new.vinted_item_id then return new; end if;
    if not exists (
      select 1 from cross_post_jobs d
       where d.user_id = new.user_id and d.platform = 'vinted' and d.action = 'delete'
         and d.status not in ('cancelled', 'failed')
         and coalesce(case when d.platform_listing_id ~ '^\d+$' then d.platform_listing_id end,
                      substring(d.listing_url from '/items/(\d+)')) = new.vinted_item_id) then
      insert into cross_post_jobs (user_id, inventaire_id, platform, action, status, photo_option, voie, title,
                                   listing_url, platform_listing_id, platform_fields)
      values (new.user_id, v_job.inventaire_id, 'vinted', 'delete', 'pending', 'original', 'extension',
              left(coalesce(new.titre, v_job.title, ''), 200),
              'https://www.vinted.fr/items/' || new.vinted_item_id, new.vinted_item_id,
              jsonb_build_object(
                'arme_par', jsonb_build_object('chemin', 'doublon_de_republication', 'republication', v_job.id::text,
                  'garde', v_garde, 'le', now(), 'mise_en_ligne', v_t,
                  'pose_par', 'inventaire_rattache_recreation_vinted (copie de plus vue au relevé)'))
              || case when new.vinted_account_id is not null
                      then jsonb_build_object('vinted_account_id', new.vinted_account_id) else '{}'::jsonb end);
    end if;
    update cross_post_jobs
       set platform_fields = platform_fields || jsonb_build_object('doublons_retires',
             coalesce(platform_fields -> 'doublons_retires', '[]'::jsonb)
             || jsonb_build_array(jsonb_build_object('numero', new.vinted_item_id, 'mise_en_ligne', v_t, 'le', now())))
     where id = v_job.id;
    raise log 'inventaire_rattache_recreation_vinted : copie % de la republication % (gardée %) → retrait armé', new.vinted_item_id, v_job.id, v_garde;
    return null;
  exception when others then
    raise warning 'inventaire_rattache_recreation_vinted : % — import inchangé', sqlerrm;
    return new;
  end;
end $function$

CREATE OR REPLACE FUNCTION public.inventaire_reconcilie_jumelle_vinted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_titre text;
  v_job   record;
BEGIN
  IF coalesce(NEW.origine, '') <> 'vinted_sync' OR NEW.vinted_item_id IS NULL THEN RETURN NEW; END IF;
  BEGIN
    IF EXISTS (SELECT 1 FROM inventaire i WHERE i.user_id = NEW.user_id AND i.vinted_item_id = NEW.vinted_item_id) THEN RETURN NEW; END IF;
    SELECT j.id, j.inventaire_id, j.status, j.error INTO v_job
    FROM cross_post_jobs j
    JOIN inventaire i ON i.id = j.inventaire_id
    WHERE j.user_id = NEW.user_id
      AND j.platform = 'vinted' AND j.action = 'publish'
      AND j.status IN ('failed', 'needs_user', 'pending')
      AND j.created_at > now() - interval '7 days'
      AND i.user_id = NEW.user_id
      AND i.vinted_item_id IS NULL
      AND coalesce(i.statut, '') NOT IN ('vendu', 'supprime')
      AND listing_designe(NEW.vinted_item_id,j.listing_url,j.platform_listing_id)
      AND (i.vinted_account_id IS NULL OR i.vinted_account_id=NEW.vinted_account_id)
      AND (nullif(j.platform_fields->>'vinted_account_id','') IS NULL
           OR j.platform_fields->>'vinted_account_id'=NEW.vinted_account_id)
    ORDER BY j.created_at DESC
    LIMIT 1;
    IF v_job.id IS NULL THEN RETURN NEW; END IF;

    UPDATE inventaire SET vinted_item_id = NEW.vinted_item_id, disparu_le = NULL
    WHERE id = v_job.inventaire_id AND vinted_item_id IS NULL;
    IF NOT FOUND THEN RETURN NEW; END IF;

    UPDATE cross_post_jobs SET
      status = 'published',
      error = NULL,
      listing_url = 'https://www.vinted.fr/items/' || NEW.vinted_item_id,
      platform_listing_id = NEW.vinted_item_id,
      platform_fields = coalesce(platform_fields, '{}'::jsonb) || jsonb_build_object('reconciliation_synchro', jsonb_build_object(
        'le', now(), 'vinted_item_id', NEW.vinted_item_id, 'statut_avant', v_job.status, 'erreur_avant', left(v_job.error, 300),
        'motif', 'identifiant exact du dépôt retrouvé dans la garde-robe Vinted — titre ignoré'))
    WHERE id = v_job.id;
    RAISE NOTICE 'inventaire_reconcilie_jumelle_vinted : job % rattaché à l''annonce % (article %)', v_job.id, NEW.vinted_item_id, v_job.inventaire_id;
    RETURN NEW;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'inventaire_reconcilie_jumelle_vinted : % — synchro inchangée', SQLERRM;
    RETURN NEW;
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_releve_garde_textes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_h jsonb;
begin
  begin
    if coalesce(current_setting('request.method', true), '') <> 'PATCH' then return new; end if;
    if coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') <> 'authenticated' then return new; end if;
    v_h := nullif(current_setting('request.headers', true), '')::jsonb;
    if coalesce(v_h ->> 'origin', '') not like 'chrome-extension://%' then return new; end if;
    if nullif(btrim(old.titre), '') is not null and new.titre is distinct from old.titre then
      new.titre := old.titre;
    end if;
    if nullif(btrim(old.description), '') is not null and new.description is distinct from old.description then
      new.description := old.description;
    end if;
  exception when others then
    raise warning 'inventaire_releve_garde_textes (article %) : %', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_supprimer_sans_retrait(p_inventaire bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  i inventaire%ROWTYPE;
  j record;
  v_lid text;
  n_annonces integer := 0;
  n_jobs integer := 0;
  v_pf jsonb;
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'unauthorized'); END IF;
  SELECT * INTO i FROM inventaire WHERE id = p_inventaire AND user_id = v_user FOR UPDATE;
  IF i.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'article_introuvable'); END IF;

  FOR j IN
    SELECT platform, listing_url, platform_listing_id, title, price
    FROM cross_post_jobs
    WHERE user_id = v_user AND inventaire_id = p_inventaire
      AND action IN ('publish', 'republish') AND status = 'published'
      AND (NULLIF(trim(COALESCE(platform_listing_id, '')), '') IS NOT NULL
           OR NULLIF(trim(COALESCE(listing_url, '')), '') IS NOT NULL)
    ORDER BY COALESCE(published_at, created_at) DESC
  LOOP
    v_lid := COALESCE(NULLIF(trim(COALESCE(j.platform_listing_id, '')), ''), trim(j.listing_url));
    INSERT INTO annonces_plateforme (user_id, platform, listing_id, url, titre, prix,
                                     photo_url, statut_plateforme, inventaire_id, job_id,
                                     source_rapprochement, vu_le, updated_at, fiche_supprimee_le)
    VALUES (v_user, j.platform, v_lid, NULLIF(trim(COALESCE(j.listing_url, '')), ''),
            COALESCE(NULLIF(trim(COALESCE(j.title, '')), ''), i.titre), COALESCE(j.price, i.prix_vente),
            CASE WHEN jsonb_typeof(i.photos) = 'array' AND jsonb_array_length(i.photos) > 0
                 THEN i.photos ->> 0 ELSE NULL END,
            'en_ligne', NULL, NULL, NULL, now(), now(), now())
    ON CONFLICT (user_id, platform, listing_id) DO UPDATE
      SET inventaire_id = NULL, job_id = NULL, source_rapprochement = NULL,
          proposition = NULL, disparu_le = NULL, ignoree_le = NULL,
          fiche_supprimee_le = now(),
          statut_plateforme = 'en_ligne', updated_at = now();
    n_annonces := n_annonces + 1;
  END LOOP;

  FOR j IN
    SELECT id, platform_fields FROM cross_post_jobs
    WHERE user_id = v_user AND inventaire_id = p_inventaire
      AND status IN ('published', 'pending', 'processing', 'needs_user', 'failed')
  LOOP
    v_pf := COALESCE(j.platform_fields, '{}'::jsonb)
            || jsonb_build_object('fiche_supprimee_le', now(), 'annonces_laissees_en_ligne', true);
    UPDATE cross_post_jobs
       SET status = 'cancelled', platform_fields = v_pf,
           error = 'Fiche supprimée du stock, annonce laissée en ligne — aucun retrait demandé'
     WHERE id = j.id;
    n_jobs := n_jobs + 1;
  END LOOP;

  UPDATE ventes SET inventaire_id = NULL WHERE inventaire_id = p_inventaire AND user_id = v_user;

  DELETE FROM inventaire WHERE id = p_inventaire AND user_id = v_user;
  RETURN jsonb_build_object('ok', true, 'annonces_laissees', n_annonces, 'jobs_clos', n_jobs);
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_trace_changements()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_par text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.prix_vente IS NOT NULL OR NEW.poids_g IS NOT NULL THEN v_par := public.source_changement_courante(); END IF;
    NEW.prix_vente_change_le := CASE WHEN NEW.prix_vente IS NOT NULL THEN now() END;
    NEW.prix_vente_change_par := CASE WHEN NEW.prix_vente IS NOT NULL THEN v_par END;
    NEW.poids_change_le := CASE WHEN NEW.poids_g IS NOT NULL THEN now() END;
    NEW.poids_change_par := CASE WHEN NEW.poids_g IS NOT NULL THEN v_par END;
    RETURN NEW;
  END IF;
  IF NEW.prix_vente IS DISTINCT FROM OLD.prix_vente THEN
    v_par := public.source_changement_courante();
    NEW.prix_vente_change_le := now();
    NEW.prix_vente_change_par := v_par;
  ELSE
    NEW.prix_vente_change_le := OLD.prix_vente_change_le;
    NEW.prix_vente_change_par := OLD.prix_vente_change_par;
  END IF;
  IF NEW.poids_g IS DISTINCT FROM OLD.poids_g THEN
    v_par := COALESCE(v_par, public.source_changement_courante());
    NEW.poids_change_le := now();
    NEW.poids_change_par := v_par;
  ELSE
    NEW.poids_change_le := OLD.poids_change_le;
    NEW.poids_change_par := OLD.poids_change_par;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_vendu_retire_ses_copies()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if coalesce(current_setting('fillsell.sans_retrait', true), '') = '1' then
    return new;
  end if;
  if new.fusionne_dans is not null then
    return new;
  end if;
  if old.statut = 'vendu' or (old.quantite is not null and old.quantite <= 0) then
    return new;
  end if;
  if not (new.statut = 'vendu' or (new.quantite is not null and new.quantite <= 0)) then
    return new;
  end if;
  begin
    perform public.armer_retraits_copies(
      new.id, 'vente_article_serveur', null,
      case when new.vinted_status = 'sold' then 'vinted' end,
      interval '10 minutes');
  exception when others then
    raise warning 'inventaire_vendu_retire_ses_copies (article %) : % — vente poursuivie', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_vendu_vinted_par_la_vente()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id  text := nullif(btrim(coalesce(new.vinted_item_id, '')), '');
  v_job uuid;
  v_pf  jsonb;
begin
  begin
    if v_id is null then return new; end if;
    select c.id, c.platform_fields into v_job, v_pf
      from public.cross_post_jobs c
     where c.user_id = new.user_id and c.platform = 'vinted' and c.status = 'published'
       and coalesce(c.action, 'publish') in ('publish', 'republish')
       and (btrim(coalesce(c.platform_listing_id, '')) = v_id
            or substring(coalesce(c.listing_url, '') from '/items/([0-9]+)') = v_id)
     order by c.created_at desc
     limit 1
     for update;
    if v_job is null
       and exists (select 1 from public.ventes_supprimees s
                    where s.user_id = new.user_id and s.plateforme_code = 'vinted' and s.annonce_id = v_id
                      and s.source = 'releve_vinted' and left(s.motif, 9) = 'commande_'
                      and not exists (select 1 from public.vinted_listing_snapshots x
                                       where x.user_id = new.user_id and x.vinted_item_id = v_id
                                         and x.status in ('active', 'reserved', 'hidden')
                                         and x.captured_at > s.supprimee_le))
       and not exists (select 1 from public.ventes v
                        where v.user_id = new.user_id and (v.inventaire_id = new.id or v.annonce_id = v_id)) then
      new.statut := old.statut;
      new.quantite := old.quantite;
      new.vinted_status := coalesce(old.vinted_status, 'closed');
      raise log 'inventaire_vendu_vinted_par_la_vente : fiche % (annonce %) gardée en stock — commande Vinted annulée, annonce jamais revue en ligne',
        new.id, v_id;
      return new;
    end if;
    if v_job is null then return new; end if;
    if exists (select 1 from public.ventes v
                where v.user_id = new.user_id and (v.inventaire_id = new.id or v.annonce_id = v_id))
       or exists (select 1 from public.ventes_operations o
                   where o.user_id = new.user_id
                     and o.cle in ('annonce:vinted:' || v_id, coalesce(v_pf ->> 'vente_operation_cle', ''))) then
      return new;
    end if;
    if coalesce(v_pf ->> 'sale_signal', '') <> 'sold' then
      update public.cross_post_jobs
         set platform_fields = coalesce(platform_fields, '{}'::jsonb) || jsonb_build_object(
               'sale_signal', 'sold',
               'unavailable_since', coalesce(platform_fields ->> 'unavailable_since',
                                             to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')),
               'sale_signal_pose_par', jsonb_build_object(
                 'par', 'inventaire_vendu_vinted_par_la_vente', 'le', now(),
                 'motif', 'dressing_sold_fiche_vendue_par_le_client'))
       where id = v_job;
    end if;
    new.statut := old.statut;
    new.quantite := old.quantite;
    raise log 'inventaire_vendu_vinted_par_la_vente : fiche % (annonce %) gardée en stock, signal sur le job %',
      new.id, v_id, v_job;
  exception when others then
    raise warning 'inventaire_vendu_vinted_par_la_vente (fiche %) : %', new.id, sqlerrm;
    return new;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.inventaire_vente_fiche_liee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  l record;
  v_autre bigint;
  v_autre_user uuid;
  v_avant boolean;
  v_apres boolean;
  v_le timestamptz;
begin
  if coalesce(current_setting('fillsell.sans_retrait', true), '') = '1' then return new; end if;
  if new.fusionne_dans is not null then return new; end if;
  v_avant := old.statut = 'vendu' or (old.quantite is not null and old.quantite <= 0);
  v_apres := new.statut = 'vendu' or (new.quantite is not null and new.quantite <= 0);
  if v_avant = v_apres then return new; end if;
  begin
    for l in select * from public.fiches_liees_comptes f where f.fiche_a = new.id or f.fiche_b = new.id loop
      v_autre := case when l.fiche_a = new.id then l.fiche_b else l.fiche_a end;
      v_autre_user := case when l.fiche_a = new.id then l.user_b else l.user_a end;
      if not public.comptes_sont_lies(new.user_id, v_autre_user) then continue; end if;
      if v_apres then
        update public.inventaire set statut = 'vendu'
         where id = v_autre and user_id = v_autre_user and fusionne_dans is null and statut is distinct from 'vendu';
        if found then
          update public.fiches_liees_comptes
             set derniere_propagation = jsonb_build_object('type', 'vente', 'le', now(), 'de', new.id, 'vers', v_autre)
           where id = l.id;
          insert into public.usage_logs (user_id, feature, metadata)
          values (v_autre_user, 'vente_fiche_liee', jsonb_build_object('de_fiche', new.id::text, 'de_compte', new.user_id,
                  'vers_fiche', v_autre::text, 'motif', 'vente prouvée sur le compte relié : copies retirées ici aussi'));
        end if;
      elsif l.derniere_propagation ->> 'type' = 'vente' and (l.derniere_propagation ->> 'de')::bigint = new.id then
        v_le := (l.derniere_propagation ->> 'le')::timestamptz;
        update public.inventaire set statut = 'stock'
         where id = v_autre and user_id = v_autre_user and statut = 'vendu';
        update public.cross_post_jobs
           set status = 'cancelled',
               error = 'Retrait annulé : la vente a été annulée sur ton autre compte FillSell, l''article est de nouveau disponible. Ton annonce reste en ligne.',
               platform_fields = coalesce(platform_fields, '{}'::jsonb) || jsonb_build_object('retrait_annule',
                 jsonb_build_object('le', now(), 'motif', 'vente_annulee_compte_lie', 'pose_par', 'inventaire_vente_fiche_liee'))
         where inventaire_id = v_autre and user_id = v_autre_user and action = 'delete'
           and status in ('pending', 'needs_user') and created_at >= v_le - interval '1 minute';
        update public.fiches_liees_comptes
           set derniere_propagation = jsonb_build_object('type', 'annulation', 'le', now(), 'de', new.id, 'vers', v_autre)
         where id = l.id;
      end if;
    end loop;
  exception when others then
    raise warning 'inventaire_vente_fiche_liee (article %) : % — vente poursuivie', new.id, sqlerrm;
  end;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.inventaire_vinted_suit_annonce_en_ligne()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_old text := NULLIF(btrim(COALESCE(OLD.vinted_item_id, '')), '');
  v_new text := NULLIF(btrim(COALESCE(NEW.vinted_item_id, '')), '');
BEGIN
  IF v_old IS NULL OR v_new IS NULL OR v_old = v_new THEN RETURN NEW; END IF;
  IF v_old !~ '^\d+$' OR v_new !~ '^\d+$' OR v_new::numeric > v_old::numeric THEN RETURN NEW; END IF;
  IF COALESCE(NEW.vinted_status, '') = 'active' AND (
       COALESCE(OLD.vinted_status, '') IN ('sold', 'closed') OR OLD.disparu_le IS NOT NULL
       OR EXISTS (SELECT 1 FROM cross_post_jobs j
                   WHERE j.inventaire_id = OLD.id AND j.user_id = OLD.user_id AND j.platform = 'vinted'
                     AND j.action IN ('publish', 'republish') AND btrim(j.platform_listing_id) = v_old
                     AND (j.status IN ('sold', 'cancelled', 'deleted') OR j.platform_fields ? 'unavailable_since'))) THEN
    RETURN NEW;
  END IF;
  NEW.vinted_item_id := OLD.vinted_item_id;
  NEW.vinted_status := OLD.vinted_status;
  NEW.vinted_view_count := OLD.vinted_view_count;
  NEW.vinted_favourite_count := OLD.vinted_favourite_count;
  NEW.listed_at_guess := OLD.listed_at_guess;
  NEW.disparu_le := OLD.disparu_le;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.journal_etapes_republication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_etape text := COALESCE(NEW.platform_fields->>'republish_step', 'a_capturer');
  v_journal jsonb := '[]'::jsonb;
  v_n integer;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF jsonb_typeof(OLD.platform_fields->'journal_etapes') = 'array' THEN
      v_journal := OLD.platform_fields->'journal_etapes';
    END IF;
    IF v_etape IS NOT DISTINCT FROM COALESCE(OLD.platform_fields->>'republish_step', 'a_capturer')
       AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
      IF jsonb_array_length(v_journal) > 0
         AND (NEW.platform_fields->'journal_etapes') IS DISTINCT FROM v_journal THEN
        NEW.platform_fields := COALESCE(NEW.platform_fields, '{}'::jsonb) || jsonb_build_object('journal_etapes', v_journal);
      END IF;
      RETURN NEW;
    END IF;
  END IF;
  v_journal := v_journal || jsonb_build_array(jsonb_build_object(
    'etape', v_etape,
    'statut', NEW.status,
    'le', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  v_n := jsonb_array_length(v_journal);
  IF v_n > 30 THEN
    SELECT jsonb_agg(x.e ORDER BY x.i) INTO v_journal
      FROM jsonb_array_elements(v_journal) WITH ORDINALITY AS x(e, i)
     WHERE x.i > v_n - 30;
  END IF;
  NEW.platform_fields := COALESCE(NEW.platform_fields, '{}'::jsonb) || jsonb_build_object('journal_etapes', v_journal);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.liberer_reservation_job_termine()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  DELETE FROM jobs_reservations_extension WHERE job_id=OLD.id;
  RETURN OLD;
 END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status<>'processing' THEN
  DELETE FROM jobs_reservations_extension WHERE job_id=NEW.id;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.opla_copie_a_retirer_noter(p_job uuid, p_chemin text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c public.cross_post_jobs%ROWTYPE;
BEGIN
  SELECT * INTO c FROM public.cross_post_jobs WHERE id = p_job;
  IF c.id IS NULL OR c.platform IS DISTINCT FROM 'opla' OR c.status IS DISTINCT FROM 'published'
     OR coalesce(c.action, 'publish') NOT IN ('publish', 'republish') THEN
    RETURN false;
  END IF;
  IF coalesce(c.platform_fields, '{}'::jsonb) ? 'opla_a_retirer'
     OR coalesce(c.platform_fields, '{}'::jsonb) ? 'opla_retire_par_la_personne' THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM public.cross_post_jobs d
              WHERE d.user_id = c.user_id AND d.platform = 'opla' AND d.action = 'delete'
                AND coalesce(d.platform_fields, '{}'::jsonb) ? 'opla_retire_par_la_personne'
                AND ((c.inventaire_id IS NOT NULL AND d.inventaire_id = c.inventaire_id)
                     OR public.listing_designe(coalesce(nullif(btrim(c.platform_listing_id), ''), c.listing_url), d.listing_url, d.platform_listing_id))) THEN
    RETURN false;
  END IF;
  UPDATE public.cross_post_jobs
     SET platform_fields = coalesce(platform_fields, '{}'::jsonb)
           || jsonb_build_object('opla_a_retirer', jsonb_build_object('le', now(), 'chemin', left(coalesce(p_chemin, ''), 60)))
   WHERE id = c.id AND status = 'published';
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.photos_ordre_article(p_job jsonb, p_article jsonb, p_pf jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job_cles text[];
  v_art_cles text[] := '{}';
  v_art_ent  jsonb[] := '{}';
  v_e        jsonb;
  v_c        text;
  v_i        integer;
  v_n        integer;
  v_plaf     boolean;
  v_sortie   jsonb := '[]'::jsonb;
BEGIN
  IF p_job IS NULL OR jsonb_typeof(p_job) <> 'array' OR jsonb_array_length(p_job) = 0 THEN RETURN p_job; END IF;
  IF COALESCE(p_pf ->> 'photos_choisies', '') = 'true' THEN RETURN p_job; END IF;
  IF p_article IS NULL OR jsonb_typeof(p_article) <> 'array' OR jsonb_array_length(p_article) = 0 THEN RETURN p_job; END IF;
  SELECT array_agg(NULLIF(split_part(btrim(CASE jsonb_typeof(e) WHEN 'string' THEN e #>> '{}'
                                                                 WHEN 'object' THEN e ->> 'url' END, E' \t\r\n'), '?', 1), '')
                   ORDER BY o)
    INTO v_job_cles
    FROM jsonb_array_elements(p_job) WITH ORDINALITY AS t(e, o);
  IF array_position(v_job_cles, NULL) IS NOT NULL
     OR (SELECT count(DISTINCT c) FROM unnest(v_job_cles) AS c) <> cardinality(v_job_cles) THEN
    RETURN p_job;
  END IF;
  FOR v_e IN SELECT e FROM jsonb_array_elements(p_article) WITH ORDINALITY AS t(e, o) ORDER BY o LOOP
    v_c := NULLIF(split_part(btrim(CASE jsonb_typeof(v_e) WHEN 'string' THEN v_e #>> '{}'
                                                          WHEN 'object' THEN v_e ->> 'url' END, E' \t\r\n'), '?', 1), '');
    IF v_c IS NOT NULL AND NOT (v_c = ANY (v_art_cles)) THEN
      v_art_cles := array_append(v_art_cles, v_c);
      v_art_ent := array_append(v_art_ent, v_e);
    END IF;
  END LOOP;
  IF NOT (v_job_cles <@ v_art_cles) THEN RETURN p_job; END IF;
  v_plaf := COALESCE(p_pf ->> 'lbcPhotosCapped', '') = 'true';
  v_n := cardinality(v_job_cles);
  FOR v_i IN 1 .. cardinality(v_art_cles) LOOP
    v_c := v_art_cles[v_i];
    IF v_plaf THEN
      EXIT WHEN jsonb_array_length(v_sortie) >= v_n;
      IF v_c = ANY (v_job_cles) THEN
        v_sortie := v_sortie || jsonb_build_array(p_job -> (array_position(v_job_cles, v_c) - 1));
      ELSIF jsonb_typeof(v_art_ent[v_i]) = 'string' THEN
        v_sortie := v_sortie || jsonb_build_array(jsonb_build_object('url', v_art_ent[v_i] #>> '{}',
          'type', CASE WHEN jsonb_array_length(v_sortie) = 0 THEN 'original' ELSE 'photo_' || jsonb_array_length(v_sortie) END));
      ELSE
        v_sortie := v_sortie || jsonb_build_array(v_art_ent[v_i]);
      END IF;
    ELSIF v_c = ANY (v_job_cles) THEN
      v_sortie := v_sortie || jsonb_build_array(p_job -> (array_position(v_job_cles, v_c) - 1));
    END IF;
  END LOOP;
  IF v_sortie = p_job THEN RETURN p_job; END IF;
  RETURN v_sortie;
EXCEPTION WHEN OTHERS THEN
  RETURN p_job;
END
$function$

CREATE OR REPLACE FUNCTION public.prix_vente_du_job(p_user uuid, p_platform text, p_listing text, p_price numeric, p_pf jsonb, p_inv bigint)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT coalesce(
    public.prix_vente_enregistree(p_user, p_platform, p_listing, p_pf),
    public._prix_ou_null(p_pf ->> 'detected_price'),
    CASE WHEN p_price > 0 THEN p_price END,
    public._prix_ou_null(p_pf ->> 'prix_recreation'),
    public._prix_ou_null(p_pf #>> '{republish_snapshot,prix}'),
    (SELECT i.prix_vente FROM public.inventaire i
      WHERE i.id = p_inv AND i.user_id = p_user AND i.prix_vente > 0));
$function$

CREATE OR REPLACE FUNCTION public.push_noter(p_user uuid, p_origine text, p_pf text, p_vente bigint DEFAULT NULL::bigint, p_inv bigint DEFAULT NULL::bigint, p_job uuid DEFAULT NULL::uuid, p_commande text DEFAULT NULL::text, p_annonce text DEFAULT NULL::text, p_titre text DEFAULT NULL::text, p_prix numeric DEFAULT NULL::numeric, p_devise text DEFAULT NULL::text, p_vendu_le timestamp with time zone DEFAULT NULL::timestamp with time zone, p_declaree boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cles text[] := '{}';
  v_q    integer;
  v_pf   text := nullif(btrim(coalesce(p_pf, '')), '');
  v_preuve text := nullif(btrim(coalesce(current_setting('fillsell.push_preuve', true), '')), '');
  v_motif  text;
begin
  if v_preuve is not null then perform set_config('fillsell.push_preuve', '', true); end if;
  if coalesce(current_setting('fillsell.push_essai_panne', true), '') = '1' then
    raise exception 'panne simulée (essai)';
  end if;
  if p_user is null then return; end if;

  if p_commande is not null and v_pf is not null then
    v_cles := v_cles || ('commande:' || v_pf || ':' || p_commande);
  end if;
  if p_annonce is not null and v_pf is not null then
    v_cles := v_cles || ('annonce:' || v_pf || ':' || p_annonce);
  end if;
  if p_job is not null then
    v_cles := v_cles || ('job:' || p_job::text);
  end if;
  if p_inv is not null then
    select coalesce(i.quantite, 1) into v_q from public.inventaire i where i.id = p_inv;
    if coalesce(v_q, 1) <= 1 or p_declaree then
      v_cles := v_cles || ('fiche:' || p_inv::text);
    end if;
  end if;

  if not p_declaree then
    v_motif := public.push_vente_deja_signalee(p_user, v_pf, v_cles, now(), null, false);
  end if;

  insert into public.push_ventes (
    user_id, origine, plateforme, vente_id, inventaire_id, job_id, commande_ref, annonce_id,
    titre, prix, devise, vendu_le, cles, statut, motif, traite_le, lot, preuve_recente
  ) values (
    p_user, case when p_declaree then 'declaree' else p_origine end, v_pf, p_vente, p_inv, p_job,
    p_commande, p_annonce, left(p_titre, 200), p_prix, p_devise, p_vendu_le, v_cles,
    case when p_declaree then 'declaree' when v_motif is not null then 'doublon' else 'a_envoyer' end,
    v_motif, case when v_motif is not null then now() end,
    pg_current_xact_id()::text::bigint,
    case when p_declaree then null else left(v_preuve, 120) end
  );

  if not p_declaree and v_motif is null and coalesce(current_setting('fillsell.push_relance', true), '') <> '1' then
    perform set_config('fillsell.push_relance', '1', true);
    perform net.http_post(
      url     := 'https://tojihnuawsoohlolangc.supabase.co/functions/v1/push-ventes',
      headers := ('{"Content-Type":"application/json"}'::jsonb || jsonb_build_object('x-cron-secret', public.cron_secret())),
      body    := '{"trigger":"push_noter"}'::jsonb,
      timeout_milliseconds := 60000
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.push_preuve_en_ligne(p_user uuid, p_pf text, p_annonce text, p_inv bigint DEFAULT NULL::bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_aujourdhui date := (now() at time zone 'Europe/Paris')::date;
  v_debut_hier timestamptz := ((now() at time zone 'Europe/Paris')::date - 1)::timestamp at time zone 'Europe/Paris';
  v_annonce text := nullif(btrim(coalesce(p_annonce, '')), '');
  v_d date;
  v_t timestamptz;
begin
  if p_user is null or v_annonce is null or p_pf is null then return null; end if;
  if p_pf = 'vinted' then
    select max(s.captured_on) into v_d from public.vinted_listing_snapshots s
     where s.user_id = p_user and s.vinted_item_id = v_annonce
       and s.captured_on >= v_aujourdhui - 1
       and s.status in ('active', 'reserved', 'hidden');
    if v_d is not null then return 'releve:' || v_d::text; end if;
  else
    select a.vu_le into v_t from public.annonces_plateforme a
     where a.user_id = p_user and a.platform = p_pf and a.listing_id = v_annonce
       and a.vu_le >= v_debut_hier and a.disparu_le is null
       and a.statut_plateforme in ('en_ligne', 'en_verification');
    if v_t is not null then return 'releve:' || to_char(v_t at time zone 'Europe/Paris', 'YYYY-MM-DD"T"HH24:MI'); end if;
  end if;
  if p_inv is not null then
    select max(greatest(j.vu_en_ligne_le,
                        case when j.status = 'published'
                              and (j.platform_fields ->> 'sale_signal') is null
                              and (j.platform_fields ->> 'unavailable_since') is null
                              and (j.platform_fields ->> 'unavailable_pending_since') is null
                              and coalesce(j.platform_fields ->> 'check_unknown_count', '0') = '0'
                              and coalesce(j.platform_fields ->> 'check_unresolved', 'false') <> 'true'
                             then j.last_checked_at end))
      into v_t
      from public.cross_post_jobs j
     where j.inventaire_id = p_inv and j.user_id = p_user and j.platform = p_pf
       and j.action in ('publish', 'republish')
       and public.listing_designe(v_annonce, j.listing_url, j.platform_listing_id);
    if v_t >= v_debut_hier and v_t <= now() + interval '5 minutes' then
      return 'veille:' || to_char(v_t at time zone 'Europe/Paris', 'YYYY-MM-DD"T"HH24:MI');
    end if;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.push_trg_inventaire_vinted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item text;
  v_preuve text;
begin
  begin
    if new.fusionne_dans is not null then return new; end if;
    if coalesce(current_setting('fillsell.sans_retrait', true), '') = '1' then return new; end if;
    v_item := nullif(btrim(coalesce(new.vinted_item_id, '')), '');
    if v_item is null then return new; end if;
    if public.push_vinted_vendue_avant(new.user_id, v_item) then return new; end if;
    if old.vinted_item_id is not distinct from new.vinted_item_id
       and old.vinted_status in ('active', 'reserved', 'hidden')
       and old.last_synced_at >= ((now() at time zone 'Europe/Paris')::date - 1)::timestamp at time zone 'Europe/Paris'
       and old.last_synced_at <= now() + interval '5 minutes' then
      v_preuve := 'releve:' || to_char(old.last_synced_at at time zone 'Europe/Paris', 'YYYY-MM-DD"T"HH24:MI');
    else
      v_preuve := public.push_preuve_en_ligne(new.user_id, 'vinted', v_item, new.id);
    end if;
    if v_preuve is null then return new; end if;
    perform set_config('fillsell.push_preuve', v_preuve, true);
    perform public.push_noter(new.user_id, 'vinted', 'vinted', null, new.id, null,
      null, v_item, new.titre, new.prix_vente, null, null, false);
  exception when others then
    perform set_config('fillsell.push_preuve', '', true);
    raise warning 'push_trg_inventaire_vinted (article %) : % — relevé poursuivi', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.push_trg_job()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pf text;
  v_declaree boolean;
  v_dispa timestamptz;
  v_annonce text;
  v_debut_hier timestamptz;
  v_vu timestamptz;
  v_preuve text;
  v_prix numeric;
  v_lu timestamptz;
  v_fin timestamptz;
begin
  begin
    v_pf := public.plateforme_normalisee(new.platform);
    v_annonce := nullif(btrim(coalesce(new.platform_listing_id, '')), '');
    v_declaree := public.push_declaration_en_cours(new.user_id, new.inventaire_id);
    if not v_declaree then
      if new.platform_fields #>> '{sale_evidence,source}' = 'transaction_leboncoin'
         and new.platform_fields #>> '{sale_evidence,statut}' = 'sold' then
        return new;
      end if;
      if new.platform_fields #>> '{sale_evidence,source}' = 'transaction_leboncoin'
         and new.platform_fields #> '{sale_evidence,rattrapage}' is not null
         and coalesce(public._ts_ou_null(new.platform_fields #>> '{sale_evidence,rattrapage,premiere_lecture}'), '-infinity'::timestamptz)
             < now() - interval '24 hours' then
        return new;
      end if;
      v_dispa := least(public._ts_ou_null(new.platform_fields ->> 'unavailable_since'),
                       public._ts_ou_null(new.platform_fields ->> 'unavailable_pending_since'));
      if v_pf is distinct from 'vinted' then
        if v_pf = 'ebay' and exists (
             select 1 from public.push_ventes o
              where o.user_id = new.user_id and o.job_id is null
                and (o.part_le is not null or o.statut in ('a_envoyer', 'en_envoi', 'envoyee', 'declaree'))
                and (o.cles && array['commande:ebay:' || nullif(btrim(coalesce(new.platform_fields #>> '{vente_commande_ebay,commande}', '')), '')]
                     or (v_annonce is not null and o.cles && array['annonce:ebay:' || v_annonce]
                         and (split_part(coalesce(o.commande_ref, ''), ':', 1)
                                = nullif(btrim(coalesce(new.platform_fields #>> '{sale_evidence,order_id}', '')), '')
                              or (nullif(btrim(coalesce(new.platform_fields #>> '{sale_evidence,order_id}', '')), '') is null
                                  and nullif(btrim(coalesce(new.platform_fields #>> '{vente_commande_ebay,commande}', '')), '') is null
                                  and o.cree_le > now() - interval '3 days' and o.vendu_le is not null
                                  and (case when public._ts_ou_null(new.platform_fields #>> '{sale_evidence,fin}') is not null
                                            then abs(extract(epoch from (o.vendu_le - public._ts_ou_null(new.platform_fields #>> '{sale_evidence,fin}')))) <= 600
                                            else o.vendu_le <= now() + interval '5 minutes' end)))))) then
          insert into public.usage_logs (user_id, feature, metadata)
          values (new.user_id, 'vente_notification_ecartee', jsonb_build_object(
            'raison', 'parade_ebay_job', 'plateforme', v_pf, 'job_id', new.id, 'statut', new.status,
            'annonce_id', v_annonce, 'commande', new.platform_fields #>> '{vente_commande_ebay,commande}',
            'order_id', new.platform_fields #>> '{sale_evidence,order_id}', 'inventaire_id', new.inventaire_id));
          return new;
        end if;
        if v_dispa is not null then
          if v_dispa < now() - interval '24 hours' then return new; end if;
        elsif not (coalesce(new.voie, '') = 'api' and new.status = 'sold') then
          if old.last_checked_at is null or old.last_checked_at < now() - interval '24 hours' then
            v_lu := coalesce(public._ts_ou_null(new.platform_fields #>> '{sale_evidence,observed_at}'),
                             public._ts_ou_null(new.platform_fields #>> '{sale_evidence,lu_le}'));
            v_fin := public._ts_ou_null(new.platform_fields #>> '{sale_evidence,fin}');
            if new.platform_fields #>> '{sale_evidence,exact}' = 'true'
               and new.platform_fields #>> '{sale_evidence,state}' = 'sold'
               and new.platform_fields #>> '{sale_evidence,platform}' = new.platform
               and btrim(coalesce(new.platform_fields #>> '{sale_evidence,listing_id}', '')) = v_annonce
               and v_lu >= now() - interval '24 hours' and v_lu <= now() + interval '5 minutes'
               and (v_fin is null or v_fin >= now() - interval '24 hours') then
              v_preuve := 'exacte:' || coalesce(new.platform_fields #>> '{sale_evidence,source}', 'page_annonce')
                          || ':' || to_char(v_lu at time zone 'Europe/Paris', 'YYYY-MM-DD"T"HH24:MI');
            elsif new.published_at > now() - interval '48 hours' then
              v_preuve := 'publiee:' || to_char(new.published_at at time zone 'Europe/Paris', 'YYYY-MM-DD"T"HH24:MI');
            else
              v_preuve := public.push_preuve_en_ligne(new.user_id, v_pf, v_annonce, null);
            end if;
            if v_preuve is null then
              return new;
            end if;
            perform set_config('fillsell.push_preuve', v_preuve, true);
          end if;
        end if;
      else
        if v_dispa is not null and v_dispa < now() - interval '24 hours' then return new; end if;
        if public.push_vinted_vendue_avant(new.user_id, v_annonce) then return new; end if;
        v_debut_hier := ((now() at time zone 'Europe/Paris')::date - 1)::timestamp at time zone 'Europe/Paris';
        v_vu := greatest(old.vu_en_ligne_le,
                         case when old.status = 'published'
                               and (old.platform_fields ->> 'sale_signal') is null
                               and (old.platform_fields ->> 'unavailable_since') is null
                               and (old.platform_fields ->> 'unavailable_pending_since') is null
                               and coalesce(old.platform_fields ->> 'check_unknown_count', '0') = '0'
                               and coalesce(old.platform_fields ->> 'check_unresolved', 'false') <> 'true'
                              then old.last_checked_at end);
        if v_vu >= v_debut_hier and v_vu <= now() + interval '5 minutes' then
          v_preuve := 'veille:' || to_char(v_vu at time zone 'Europe/Paris', 'YYYY-MM-DD"T"HH24:MI');
        elsif new.published_at > now() - interval '48 hours' then
          v_preuve := 'publiee:' || to_char(new.published_at at time zone 'Europe/Paris', 'YYYY-MM-DD"T"HH24:MI');
        else
          v_preuve := public.push_preuve_en_ligne(new.user_id, v_pf, v_annonce, null);
        end if;
        if v_preuve is null then return new; end if;
        perform set_config('fillsell.push_preuve', v_preuve, true);
      end if;
    end if;
    begin
      v_prix := coalesce(public.prix_vente_du_job(new.user_id, new.platform, new.platform_listing_id,
                                                  new.price, new.platform_fields, new.inventaire_id),
                         new.price);
    exception when others then
      v_prix := new.price;
    end;
    perform public.push_noter(new.user_id, 'job', v_pf, null, new.inventaire_id, new.id,
      null, v_annonce, new.title, v_prix, null, null,
      v_declaree);
  exception when others then
    perform set_config('fillsell.push_preuve', '', true);
    raise warning 'push_trg_job (job %) : % — vente poursuivie', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.push_vente_deja_signalee(p_user uuid, p_pf text, p_cles text[], p_avant timestamp with time zone DEFAULT now(), p_note bigint DEFAULT NULL::bigint, p_anterieures boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pf    text := nullif(btrim(coalesce(p_pf, '')), '');
  v_ann   text[];
  v_cmd   text[];
  v_unite boolean;
begin
  if p_user is null or p_cles is null then return null; end if;
  v_cmd := array(select k from unnest(p_cles) k where k like 'commande:%');
  v_ann := array(select k from unnest(p_cles) k
                  where k like 'annonce:%' and k not like 'annonce:ebay:%' and k not like 'annonce:ailleurs:%');
  v_unite := coalesce(v_pf in ('vinted', 'beebs', 'opla', 'depop'), false);

  if cardinality(v_ann) > 0 and (v_unite or cardinality(v_cmd) = 0)
     and exists (select 1 from public.ventes_operations o
                  where o.user_id = p_user and o.cle = any (v_ann) and o.cree_le < p_avant) then
    return 'vente_deja_enregistree';
  end if;
  if cardinality(v_cmd) > 0 and exists (
       select 1 from public.push_ventes o
        where o.user_id = p_user and o.id is distinct from p_note
          and (not p_anterieures or o.id < p_note)
          and (o.part_le is not null or o.statut in ('envoyee', 'en_envoi', 'declaree'))
          and o.cles && v_cmd) then
    return 'vente_deja_annoncee';
  end if;
  if cardinality(v_ann) > 0 and exists (
       select 1 from public.push_ventes o
        where o.user_id = p_user and o.id is distinct from p_note
          and (not p_anterieures or o.id < p_note)
          and (o.part_le is not null or o.statut in ('envoyee', 'en_envoi', 'declaree'))
          and o.cles && v_ann
          and (v_unite or cardinality(v_cmd) = 0
               or not exists (select 1 from unnest(o.cles) ok where ok like 'commande:%')
               or o.cles && v_cmd)) then
    return 'vente_deja_annoncee';
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.quota_republication_free_etat(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plafond integer;
  v_borne   timestamptz;
  v_exec    integer;
  v_vol     integer;
  v_remise  timestamptz;
BEGIN
  v_plafond := quota_remontees_plafond('free');
  IF v_plafond IS NULL OR v_plafond <= 0 THEN
    RETURN jsonb_build_object('mode', 'mensuel', 'plafond', NULL);
  END IF;
  v_borne := GREATEST(
    debut_cycle_quotas(p_user),
    to_timestamp(COALESCE((SELECT value FROM coin_config WHERE key = 'quotas_republication_free_depuis'), 0)));
  SELECT count(*) FILTER (WHERE j.published_at >= v_borne),
         count(*) FILTER (WHERE j.published_at IS NULL AND j.created_at >= v_borne
                            AND j.status IN ('pending', 'processing', 'needs_user'))
    INTO v_exec, v_vol
    FROM cross_post_jobs j
   WHERE j.user_id = p_user
     AND j.action = 'republish'
     AND (j.published_at >= v_borne OR j.created_at >= v_borne)
     AND NOT (COALESCE(j.platform_fields, '{}'::jsonb) ?| ARRAY['opla_sortie', 'hors_quota'])
     AND COALESCE(j.handler_build, '') !~ '(sync-dressing|releve-annonces)';
  SELECT w.next_grant_at INTO v_remise FROM coin_wallets w WHERE w.user_id = p_user;
  RETURN jsonb_build_object(
    'mode', 'mensuel',
    'plafond', v_plafond,
    'faites', v_exec + v_vol,
    'executees', v_exec,
    'en_cours', v_vol,
    'restantes', GREATEST(0, v_plafond - v_exec - v_vol),
    'depuis', v_borne,
    'remise_le', v_remise);
END;
$function$

CREATE OR REPLACE FUNCTION public.rapprochement_v3_remise_possible(p_user uuid, p_ancienne bigint, p_nouvelle bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE m inventaire%ROWTYPE; n inventaire%ROWTYPE;
BEGIN
  SELECT * INTO m FROM inventaire WHERE id = p_ancienne AND user_id = p_user;
  SELECT * INTO n FROM inventaire WHERE id = p_nouvelle AND user_id = p_user;
  IF m.id IS NULL OR n.id IS NULL OR m.id = n.id OR m.fusionne_dans IS NOT NULL OR n.fusionne_dans IS NOT NULL THEN
    RETURN 'introuvable';
  END IF;
  IF EXISTS (SELECT 1 FROM inventaire_doublons q WHERE q.user_id = p_user AND q.decide_par = 'utilisateur'
               AND least(q.garde, q.absorbe) = least(m.id, n.id) AND greatest(q.garde, q.absorbe) = greatest(m.id, n.id))
     OR EXISTS (SELECT 1 FROM inventaire_fusions f WHERE f.user_id = p_user AND f.defait_le IS NOT NULL
                  AND least(f.garde, f.absorbe) = least(m.id, n.id) AND greatest(f.garde, f.absorbe) = greatest(m.id, n.id)) THEN
    RETURN 'paire_tranchee';
  END IF;
  IF NULLIF(btrim(COALESCE(m.vinted_item_id, '')), '') IS NULL OR NULLIF(btrim(COALESCE(n.vinted_item_id, '')), '') IS NULL
     OR btrim(m.vinted_item_id) = btrim(n.vinted_item_id) THEN
    RETURN 'pas_vinted';
  END IF;
  IF COALESCE(m.vinted_account_id, '') <> COALESCE(n.vinted_account_id, '') THEN RETURN 'boutiques_differentes'; END IF;
  IF public.boutique_vinted_autre_compte(p_user, m.vinted_account_id) THEN RETURN 'boutiques_differentes'; END IF;
  IF m.statut = 'stock' AND COALESCE(m.vinted_status, '') IN ('sold', 'closed') AND COALESCE(m.quantite, 1) <= 1
     AND n.statut = 'stock' AND COALESCE(n.vinted_status, '') = 'active' AND n.disparu_le IS NULL AND COALESCE(n.quantite, 1) <= 1
     AND NOT COALESCE(public.vinted_remise_en_ligne(m.id, n.id), false)
     AND COALESCE(public.vinted_remise_apres_annulation(m.id, n.id), false)
     AND NOT EXISTS (SELECT 1 FROM plateforme_commandes pc WHERE pc.inventaire_id IN (m.id, n.id) AND pc.etat IS DISTINCT FROM 'annulee')
     AND NOT EXISTS (SELECT 1 FROM cross_post_jobs j WHERE j.user_id = p_user AND j.inventaire_id IN (m.id, n.id)
                       AND j.status = 'published' AND j.platform_fields ->> 'sale_signal' = 'sold')
     AND NOT EXISTS (SELECT 1 FROM annonces_plateforme a WHERE a.inventaire_id IN (m.id, n.id) AND a.platform = 'leboncoin'
                       AND public.leboncoin_transaction_lue(a.transaction_plateforme, a.capture) IN ('pending', 'sold')) THEN
    RETURN 'vente_annulee_question';
  END IF;
  IF m.statut IS DISTINCT FROM 'stock' OR COALESCE(m.vinted_status, '') = 'sold'
     OR n.statut IS DISTINCT FROM 'stock' AND (n.statut = 'vendu' OR COALESCE(n.vinted_status, '') = 'sold') THEN
    RETURN 'ancienne_vendue';
  END IF;
  IF EXISTS (SELECT 1 FROM plateforme_commandes pc WHERE pc.inventaire_id IN (m.id, n.id))
     OR EXISTS (SELECT 1 FROM cross_post_jobs j WHERE j.user_id = p_user AND j.inventaire_id IN (m.id, n.id)
                  AND j.status = 'published' AND j.platform_fields ->> 'sale_signal' = 'sold')
     OR EXISTS (SELECT 1 FROM annonces_plateforme a WHERE a.inventaire_id IN (m.id, n.id) AND a.platform = 'leboncoin'
                  AND public.leboncoin_transaction_lue(a.transaction_plateforme, a.capture) IN ('pending', 'sold')) THEN
    RETURN 'vente_en_cours';
  END IF;
  IF n.statut IS DISTINCT FROM 'stock' OR COALESCE(n.vinted_status, '') <> 'active' OR n.disparu_le IS NOT NULL THEN
    RETURN 'nouvelle_pas_en_ligne';
  END IF;
  IF NOT vinted_remise_en_ligne(m.id, n.id) THEN RETURN 'pas_une_remise_en_ligne'; END IF;
  IF COALESCE(m.quantite, 1) > 1 OR COALESCE(n.quantite, 1) > 1 THEN RETURN 'quantite'; END IF;
  IF EXISTS (SELECT 1 FROM cross_post_jobs j WHERE j.user_id = p_user AND j.inventaire_id IN (m.id, n.id)
               AND j.status IN ('pending', 'processing', 'needs_user')) THEN
    RETURN 'job_en_vol';
  END IF;
  IF n.prix_achat IS NOT NULL OR COALESCE(n.prix_achat_inconnu, false)
     OR n.prix_vente_change_par = 'app' OR n.poids_change_par = 'app'
     OR EXISTS (SELECT 1 FROM ventes x WHERE x.inventaire_id = n.id)
     OR EXISTS (SELECT 1 FROM fiches_annonce fa WHERE fa.inventaire_id = n.id)
     OR EXISTS (SELECT 1 FROM push_ventes pv WHERE pv.inventaire_id = n.id)
     OR EXISTS (SELECT 1 FROM remises_en_vente rv WHERE rv.inventaire_id = n.id)
     OR EXISTS (SELECT 1 FROM jsonb_each(CASE WHEN jsonb_typeof(n.attributs) = 'object' THEN n.attributs ELSE '{}'::jsonb END) e
                 WHERE jsonb_typeof(e.value) = 'object' AND e.value ->> 'source' = 'manuel') THEN
    RETURN 'nouvelle_touchee';
  END IF;
  IF EXISTS (SELECT 1 FROM annonces_plateforme x JOIN annonces_plateforme y ON y.platform = x.platform
              WHERE x.inventaire_id = m.id AND y.inventaire_id = n.id AND x.disparu_le IS NULL AND y.disparu_le IS NULL)
     OR EXISTS (SELECT 1 FROM cross_post_jobs x JOIN cross_post_jobs y ON y.platform = x.platform
                 WHERE x.inventaire_id = m.id AND y.inventaire_id = n.id AND x.platform <> 'vinted'
                   AND x.status = 'published' AND y.status = 'published'
                   AND x.action IN ('publish', 'republish') AND y.action IN ('publish', 'republish')) THEN
    RETURN 'deux_exemplaires';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.recreation_vinted_envois(pf jsonb)
 RETURNS timestamp with time zone[]
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  r timestamptz[] := '{}';
  v text;
  e jsonb;
begin
  if pf is null then return r; end if;
  foreach v in array array[pf -> 'suppression_verdict' ->> 'date_serveur', pf ->> 'deleted_at_client', pf ->> 'deleted_at',
                           pf ->> 'deleted_at_serveur', pf -> 'recreation_tentee' ->> 'at'] loop
    begin
      if nullif(btrim(coalesce(v, '')), '') is not null then r := r || v::timestamptz; end if;
    exception when others then null;
    end;
  end loop;
  if jsonb_typeof(pf -> 'recreation_envois') = 'array' then
    for e in select x from jsonb_array_elements(pf -> 'recreation_envois') x loop
      begin
        r := r || (case when jsonb_typeof(e) = 'string' then e #>> '{}' else e ->> 'at' end)::timestamptz;
      exception when others then null;
      end;
    end loop;
  end if;
  return r;
end $function$

CREATE OR REPLACE FUNCTION public.recreation_vinted_retrait_le(pf jsonb)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  r timestamptz;
  v text;
  t timestamptz;
begin
  if pf is null then return null; end if;
  foreach v in array array[pf -> 'suppression_verdict' ->> 'date_serveur', pf ->> 'deleted_at_client', pf ->> 'deleted_at',
                           pf ->> 'deleted_at_serveur'] loop
    begin
      if nullif(btrim(coalesce(v, '')), '') is not null then
        t := v::timestamptz;
        if r is null or t < r then r := t; end if;
      end if;
    exception when others then null;
    end;
  end loop;
  return r;
end $function$

CREATE OR REPLACE FUNCTION public.refund_coins(p_user_id uuid, p_amount integer, p_metadata jsonb DEFAULT NULL::jsonb, p_kind text DEFAULT 'refund'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wallet coin_wallets%ROWTYPE;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('refunded', false, 'reason', 'invalid_amount');
  END IF;
  IF p_kind NOT IN ('refund', 'refund_generate', 'refund_republish') THEN
    RETURN jsonb_build_object('refunded', false, 'reason', 'invalid_kind');
  END IF;
  INSERT INTO coin_wallets (user_id) VALUES (p_user_id) ON CONFLICT (user_id) DO NOTHING;
  SELECT * INTO v_wallet FROM coin_wallets WHERE user_id = p_user_id FOR UPDATE;
  UPDATE coin_wallets SET
    purchased_balance = purchased_balance + p_amount,
    updated_at        = now()
  WHERE user_id = p_user_id;
  INSERT INTO coin_ledger (user_id, delta, included_after, purchased_after, kind, metadata)
  VALUES (
    p_user_id, p_amount,
    v_wallet.included_balance, v_wallet.purchased_balance + p_amount,
    p_kind, p_metadata
  );
  RETURN jsonb_build_object('refunded', true, 'amount', p_amount);
END;
$function$

CREATE OR REPLACE FUNCTION public.relancer_jobs_connexion(p_user uuid, p_platform text, p_preuve text, p_preuve_le timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r        record;
  v_pf     jsonb;
  v_parque timestamptz;
  v_rc     jsonb;
  v_n      integer;
  v_i      integer := 0;
  v_pas    interval;
  v_fait   integer := 0;
BEGIN
  IF p_user IS NULL OR p_platform IS NULL OR p_platform NOT IN ('vinted', 'leboncoin', 'beebs', 'opla', 'depop') THEN
    RETURN 0;
  END IF;
  v_pas := CASE WHEN p_platform = 'vinted' THEN interval '90 seconds' ELSE interval '45 seconds' END;
  FOR r IN
    SELECT c.id, c.status, c.action, c.inventaire_id, COALESCE(c.platform_fields, '{}'::jsonb) AS pf
      FROM cross_post_jobs c
     WHERE c.user_id = p_user AND c.platform = p_platform
       AND c.created_at > now() - interval '30 days'
       AND (
         (c.status = 'pending' AND c.platform_fields ? 'attente_session'
            AND c.error ~* '^En attente de ta connexion à ')
         OR (c.status = 'needs_user'
            AND c.error !~* '(anti-?robot|datadome)'
            AND NOT (c.platform_fields ? 'blocage_antirobot')
            AND NOT (c.platform_fields ? 'attente_antirobot_compte')
            AND (c.platform_fields->>'needs_user_source' = 'session_vinted'
                 OR c.platform_fields->'pas_de_rouge'->>'motif' = 'connexion'
                 OR c.error ~* '^(Connexion|Reconnexion) \S+ requise'))
       )
     ORDER BY c.created_at
     FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      v_pf := r.pf;
      IF v_pf ? 'needsUserField' THEN CONTINUE; END IF;
      v_parque := GREATEST(
        _ts_ou_null(v_pf->'attente_session'->>'derniere'),
        _ts_ou_null(v_pf->'attente_session'->>'depuis'),
        _ts_ou_null(v_pf->'pas_de_rouge'->>'at'),
        _ts_ou_null(v_pf->>'needs_user_vu_le'),
        _ts_ou_null(v_pf->'reprise_connexion'->>'le'));
      IF p_preuve_le IS NOT NULL AND v_parque IS NOT NULL AND p_preuve_le <= v_parque THEN CONTINUE; END IF;
      v_rc := CASE WHEN jsonb_typeof(v_pf->'reprise_connexion') = 'object' THEN v_pf->'reprise_connexion' ELSE '{}'::jsonb END;
      v_n := CASE WHEN _ts_ou_null(v_rc->>'depuis') > now() - interval '24 hours'
                  THEN COALESCE(NULLIF(v_rc->>'n', '')::integer, 0) ELSE 0 END;
      IF v_n >= 6 THEN CONTINUE; END IF;
      IF r.inventaire_id IS NOT NULL AND COALESCE(r.action, 'publish') IN ('publish', 'republish')
         AND article_vendu(r.inventaire_id) THEN
        CONTINUE;
      END IF;

      v_pf := v_pf - 'needs_user_source' - 'next_action_after' - 'attente_session'
                   - 'needs_user_actif_ms' - 'needs_user_tick_le' - 'needs_user_vu_le' - 'needs_user_vu_erreur'
                   - 'needsUserAttempts' - 'needsUserBoucle' - 'needsUserResolved' - 'error_technique'
                   - 'processing_since';
      v_pf := v_pf || jsonb_build_object('reprise_connexion', jsonb_build_object(
        'le', now(), 'preuve', p_preuve, 'preuve_le', p_preuve_le,
        'depuis', CASE WHEN v_n = 0 THEN now()::text ELSE v_rc->>'depuis' END,
        'n', v_n + 1, 'etait', r.status));
      IF COALESCE(r.action, 'publish') = 'publish' THEN
        v_pf := v_pf || jsonb_build_object('verifier_doublon_avant_publication', true);
      END IF;
      IF v_i > 0 THEN
        v_pf := v_pf || jsonb_build_object('next_action_after', (now() + v_pas * v_i)::text);
      END IF;

      UPDATE cross_post_jobs SET status = 'pending', error = NULL, platform_fields = v_pf
       WHERE id = r.id AND status = r.status;
      IF FOUND THEN v_fait := v_fait + 1; v_i := v_i + 1; END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'relancer_jobs_connexion (job %) : %', r.id, SQLERRM;
    END;
  END LOOP;
  RETURN v_fait;
END
$function$

CREATE OR REPLACE FUNCTION public.relancer_jobs_connexion_echus()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r       record;
  v_pf    jsonb;
  v_rc    jsonb;
  v_k     integer;
  v_at    timestamptz;
  v_label text;
  v_quoi  text;
  v_fait  integer := 0;
BEGIN
  FOR r IN
    SELECT c.id, c.platform, c.action, c.error, c.inventaire_id, COALESCE(c.platform_fields, '{}'::jsonb) AS pf
      FROM cross_post_jobs c
     WHERE c.status = 'needs_user'
       AND c.platform IN ('vinted', 'leboncoin', 'beebs', 'opla', 'depop')
       AND c.created_at > now() - interval '30 days'
       AND c.platform_fields->>'needs_user_source' = 'connexion'
       AND c.platform_fields->'pas_de_rouge'->>'motif' = 'connexion'
       AND c.error !~* '(anti-?robot|datadome)'
       AND NOT (c.platform_fields ? 'blocage_antirobot')
       AND NOT (c.platform_fields ? 'attente_antirobot_compte')
     FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      v_pf := r.pf;
      IF v_pf ? 'needsUserField' THEN CONTINUE; END IF;
      v_rc := CASE WHEN jsonb_typeof(v_pf->'reprise_differee') = 'object' THEN v_pf->'reprise_differee' ELSE '{}'::jsonb END;
      v_k := COALESCE(NULLIF(v_rc->>'n', '')::integer, 0);
      IF v_k >= 3 THEN CONTINUE; END IF;
      v_at := _ts_ou_null(v_pf->'pas_de_rouge'->>'at');
      IF v_at IS NULL OR v_at < now() - interval '2 days' THEN CONTINUE; END IF;
      IF _ts_ou_null(v_rc->>'parcage') IS NOT DISTINCT FROM v_at THEN CONTINUE; END IF;
      IF r.inventaire_id IS NOT NULL AND COALESCE(r.action, 'publish') IN ('publish', 'republish')
         AND article_vendu(r.inventaire_id) THEN
        CONTINUE;
      END IF;
      v_label := CASE r.platform WHEN 'vinted' THEN 'Vinted' WHEN 'leboncoin' THEN 'Leboncoin'
                                 WHEN 'beebs' THEN 'Beebs' ELSE 'Opla' END;
      v_quoi := CASE COALESCE(r.action, 'publish') WHEN 'delete' THEN 'le retrait de l''annonce'
                                                    WHEN 'republish' THEN 'la republication' ELSE 'la publication' END;
      v_pf := v_pf - 'needs_user_source' - 'next_action_after'
                   - 'needs_user_actif_ms' - 'needs_user_tick_le' - 'needs_user_vu_le' - 'needs_user_vu_erreur'
                   - 'needsUserBoucle' - 'needsUserResolved' - 'error_technique' - 'processing_since';
      v_pf := v_pf || jsonb_build_object(
        'attente_session', jsonb_build_object(
          'platform', r.platform, 'depuis', v_at, 'derniere', v_at, 'observations', 1,
          'motif', left(COALESCE(r.error, ''), 300),
          'reconnu_par', 'classification « connexion » (pas-de-rouge)',
          'pose_par', 'relancer_jobs_connexion_echus'),
        'next_action_after', (v_at + (CASE v_k WHEN 0 THEN interval '3 minutes' WHEN 1 THEN interval '6 minutes' ELSE interval '10 minutes' END))::text,
        'reprise_differee', jsonb_build_object('le', now(), 'n', v_k + 1, 'parcage', v_at));
      IF COALESCE(r.action, 'publish') = 'publish' THEN
        v_pf := v_pf || jsonb_build_object('verifier_doublon_avant_publication', true);
      END IF;
      UPDATE cross_post_jobs SET
        status = 'pending',
        error = 'En attente de ta connexion à ' || v_label || ' dans Chrome : ' || v_quoi
                || ' repartira toute seule dès que tu seras reconnecté(e).',
        platform_fields = v_pf
       WHERE id = r.id AND status = 'needs_user';
      IF FOUND THEN v_fait := v_fait + 1; END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'relancer_jobs_connexion_echus (job %) : %', r.id, SQLERRM;
    END;
  END LOOP;
  RETURN v_fait;
END
$function$

CREATE OR REPLACE FUNCTION public.releve_apres_annulation(p_user uuid, p_platform text, p_depuis timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_kind text := CASE WHEN p_platform = 'vinted' THEN 'dressing' ELSE 'annonces' END;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM vinted_sync_runs s WHERE s.user_id = p_user AND s.platform = p_platform AND s.kind = v_kind
                    AND s.status = 'done' AND s.finished_at > now() - interval '30 days') THEN
    RETURN 'sans_releve';
  END IF;
  IF EXISTS (SELECT 1 FROM vinted_sync_runs s WHERE s.user_id = p_user AND s.platform = p_platform AND s.kind = v_kind
                AND s.status = 'done' AND s.finished_at > p_depuis
                AND (CASE WHEN v_kind = 'annonces' THEN public.releve_preuve_absence(s.id)
                          ELSE COALESCE(s.items_vus, 0) > 0 AND COALESCE(s.erreur, '') NOT LIKE '[incomplet]%'
                               AND (s.total_entries IS NULL OR s.items_vus >= s.total_entries) END)) THEN
    RETURN 'vu';
  END IF;
  RETURN 'attendu';
END;
$function$

CREATE OR REPLACE FUNCTION public.releve_poser_question(p_user uuid, p_existante bigint, p_nouvelle bigint, p_motif text, p_preuves jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t1 text; v_t2 text;
BEGIN
  IF p_user IS NULL OR p_existante IS NULL OR p_nouvelle IS NULL OR p_existante = p_nouvelle THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM inventaire WHERE id = p_existante AND user_id = p_user AND fusionne_dans IS NULL) THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM inventaire WHERE id = p_nouvelle AND user_id = p_user AND fusionne_dans IS NULL) THEN RETURN false; END IF;
  IF p_motif = 'photo_proche' THEN
    SELECT titre INTO v_t1 FROM inventaire WHERE id = p_existante;
    SELECT titre INTO v_t2 FROM inventaire WHERE id = p_nouvelle;
    IF titre_en_serie(p_user, v_t1) OR titre_en_serie(p_user, v_t2) THEN
      IF NOT EXISTS (SELECT 1 FROM usage_logs l WHERE l.user_id = p_user AND l.feature = 'question_photo_proche_ecartee'
                        AND l.created_at > now() - interval '1 day'
                        AND l.metadata ->> 'paire' = least(p_existante, p_nouvelle)::text || '-' || greatest(p_existante, p_nouvelle)::text) THEN
        INSERT INTO usage_logs (user_id, feature, metadata)
        VALUES (p_user, 'question_photo_proche_ecartee', jsonb_build_object(
          'paire', least(p_existante, p_nouvelle)::text || '-' || greatest(p_existante, p_nouvelle)::text,
          'existante', p_existante::text, 'nouvelle', p_nouvelle::text, 'motif', p_motif, 'raison', 'titre_en_serie',
          'photo', p_preuves -> 'photo', 'titres', jsonb_build_array(v_t1, v_t2)));
      END IF;
      RETURN false;
    END IF;
  END IF;
  INSERT INTO inventaire_doublons (user_id, garde, absorbe, niveau, statut, motif, preuves, source)
  VALUES (p_user, p_existante, p_nouvelle, 'probable', 'proposee', COALESCE(p_motif, 'releve'), COALESCE(p_preuves, '{}'::jsonb), 'releve')
  ON CONFLICT DO NOTHING;
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.releve_preuve_absence(p_run uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r vinted_sync_runs%ROWTYPE;
BEGIN
  SELECT * INTO r FROM vinted_sync_runs WHERE id=p_run;
  IF r.id IS NULL OR (auth.uid() IS NOT NULL AND auth.uid()<>r.user_id)
     OR r.status<>'done' OR r.kind<>'annonces'
     OR COALESCE(r.items_vus,0)<=0 OR r.finished_at IS NULL
     OR COALESCE(r.erreur,'') LIKE '[incomplet]%'
     OR releve_hors_liste(r.erreur)
     OR (r.total_entries IS NOT NULL AND r.items_vus<r.total_entries)
     THEN RETURN false; END IF;
  IF r.platform='ebay' AND (releve_ebay_run_bloque(r.id) OR releve_ebay_run_incomplet(r.id)) THEN RETURN false; END IF;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.remise_annulee_jumelle_fermer(p_user uuid, p_fiche bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_apres timestamptz; v_jumelle bigint; v_motif text; v_photos integer; v_n integer;
BEGIN
  IF p_user IS NULL OR p_fiche IS NULL THEN RETURN NULL; END IF;
  v_apres := public.remise_annulee_vente_le(p_user, p_fiche);
  IF v_apres IS NULL THEN RETURN NULL; END IF;
  SELECT x.jumelle, x.motif, x.photos_communes INTO v_jumelle, v_motif, v_photos
    FROM public.fiche_jumelle_prouvee(p_user, p_fiche, v_apres) x LIMIT 1;
  IF v_jumelle IS NULL THEN RETURN NULL; END IF;
  UPDATE remises_en_vente rv SET statut = 'abandonnee', motif = v_motif, traite_le = now()
   WHERE rv.user_id = p_user AND rv.inventaire_id = p_fiche AND rv.statut IN ('proposee', 'a_faire')
     AND EXISTS (SELECT 1 FROM cross_post_jobs jv
                  WHERE jv.id = rv.job_vendu AND COALESCE(jv.platform_fields, '{}'::jsonb) ? 'vente_annulee_remise');
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RETURN NULL; END IF;
  INSERT INTO usage_logs (user_id, feature, metadata)
  VALUES (p_user, 'remise_annulee_fermee_jumelle', jsonb_build_object(
    'inventaire_id', p_fiche::text, 'jumelle', v_jumelle::text, 'motif', v_motif, 'photos_communes', v_photos,
    'vente_le', v_apres, 'lignes', v_n, 'regle', 'ventes_annulees_fermeture_0711'));
  RETURN jsonb_build_object('jumelle', v_jumelle, 'motif', v_motif, 'photos_communes', v_photos, 'lignes', v_n);
END;
$function$

CREATE OR REPLACE FUNCTION public.remise_annulee_question_poser(p_user uuid, p_fiche bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_le timestamptz; v_jumelle bigint; v_motif text; v_photos integer; v_rp text; v_posee boolean;
  v_ancienne text; v_vivante text;
BEGIN
  IF p_user IS NULL OR p_fiche IS NULL THEN RETURN NULL; END IF;
  v_le := public.vente_annulee_prouvee(p_user, p_fiche);
  IF v_le IS NULL THEN RETURN NULL; END IF;
  SELECT x.jumelle, x.motif, x.photos_communes INTO v_jumelle, v_motif, v_photos
    FROM public.fiche_jumelle_prouvee(p_user, p_fiche, v_le) x LIMIT 1;
  IF v_jumelle IS NULL OR v_motif IS DISTINCT FROM 'deja_en_vente_autre_fiche' THEN RETURN NULL; END IF;
  v_rp := public.rapprochement_v3_remise_possible(p_user, p_fiche, v_jumelle);
  IF v_rp IS DISTINCT FROM 'vente_annulee_question' THEN RETURN NULL; END IF;
  SELECT btrim(vinted_item_id) INTO v_ancienne FROM inventaire WHERE id = p_fiche;
  SELECT btrim(vinted_item_id) INTO v_vivante FROM inventaire WHERE id = v_jumelle;
  v_posee := public.releve_poser_question(p_user, p_fiche, v_jumelle, 'remise_en_ligne_vente_annulee',
    jsonb_build_object('regle', 'rapprochement_v3', 'portee', 'remise_en_ligne', 'refus_fusion', v_rp,
                       'motif', 'photo_identique', 'photos_communes', v_photos, 'vente_le', v_le,
                       'vinted_ancienne', v_ancienne, 'vinted_vivante', v_vivante,
                       'signaux', jsonb_build_object('photo', jsonb_build_object('verdict', 'identique', 'communes', v_photos)),
                       'regle_0711', 'remise_apres_annulation_question'));
  IF NOT COALESCE(v_posee, false) THEN RETURN NULL; END IF;
  INSERT INTO usage_logs (user_id, feature, metadata)
  VALUES (p_user, 'remise_annulee_question_posee', jsonb_build_object(
    'ancienne', p_fiche::text, 'nouvelle', v_jumelle::text, 'photos_communes', v_photos, 'vente_le', v_le,
    'vinted_ancienne', v_ancienne, 'vinted_vivante', v_vivante, 'regle', 'remise_apres_annulation_question_0711'));
  RETURN jsonb_build_object('ancienne', p_fiche, 'nouvelle', v_jumelle, 'photos_communes', v_photos);
END;
$function$

CREATE OR REPLACE FUNCTION public.remise_en_vente_place(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_palier text := COALESCE(republish_palier(p_user), 'free');
  v_quota integer; v_depuis timestamptz; v_faits integer;
  v_qfree jsonb;
BEGIN
  IF v_palier = 'free' THEN
    v_qfree := quota_republication_free_etat(p_user);
    IF (v_qfree ->> 'plafond') IS NOT NULL AND (v_qfree ->> 'restantes')::integer <= 0 THEN
      RETURN jsonb_build_object('place', false, 'motif', 'quota_du_mois',
        'palier', v_palier, 'plafond', (v_qfree ->> 'plafond')::integer,
        'faits', (v_qfree ->> 'faites')::integer,
        'reprise', GREATEST(COALESCE((v_qfree ->> 'remise_le')::timestamptz, now() + interval '1 day'),
                            now() + interval '1 hour'));
    END IF;
  ELSIF v_palier IN ('premium', 'pro') THEN
    v_quota := quota_remontees_plafond(v_palier);
    v_depuis := debut_cycle_quotas(p_user);
  END IF;
  IF v_quota IS NOT NULL AND v_depuis IS NOT NULL THEN
    SELECT remontees_du_cycle(p_user, v_depuis)
         + (SELECT count(*) FROM remises_en_vente r
             WHERE r.user_id = p_user AND r.statut = 'faite' AND r.traite_le >= v_depuis
               AND NOT EXISTS (SELECT 1 FROM cross_post_jobs jv WHERE jv.id = r.job_vendu
                                AND COALESCE(jv.platform_fields, '{}'::jsonb) ? 'vente_annulee_remise'))
      INTO v_faits;
    IF v_faits >= v_quota THEN
      RETURN jsonb_build_object('place', false,
        'motif', 'quota_du_mois',
        'palier', v_palier, 'plafond', v_quota, 'faits', v_faits,
        'reprise', now() + interval '1 day');
    END IF;
  END IF;
  RETURN jsonb_build_object('place', true, 'palier', v_palier);
END;
$function$

CREATE OR REPLACE FUNCTION public.remises_en_vente_tick(p_limite integer DEFAULT 20, p_user uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '20s'
AS $function$
DECLARE
  v_cpu numeric;
  r record; j cross_post_jobs%ROWTYPE; i inventaire%ROWTYPE;
  v_op jsonb; v_place jsonb; v_motif text; v_report timestamptz; v_nouveau uuid;
  v_vu timestamptz; v_api boolean; v_sortie bigint; v_prix integer;
  v_faites integer := 0; v_abandons integer := 0; v_reports integer := 0;
  v_annul boolean; v_restant integer;
  v_trans text; v_conv text; v_rep jsonb;
  v_f record; v_jum jsonb; v_hors_stock integer := 0; v_jumelles integer := 0;
  v_questions integer := 0;
BEGIN
  SELECT pct INTO v_cpu FROM veille_cpu WHERE pct IS NOT NULL ORDER BY le DESC LIMIT 1;
  IF v_cpu IS NOT NULL AND v_cpu > 50 THEN
    RETURN jsonb_build_object('issue', 'saute_cpu', 'cpu', v_cpu);
  END IF;
  SELECT value INTO v_sortie FROM coin_config WHERE key = 'opla_sortie_le';
  SELECT value INTO v_prix FROM coin_config WHERE key = 'price_per_platform';

  UPDATE remises_en_vente rv SET statut = 'abandonnee', motif = 'plus_en_stock', traite_le = now()
    FROM cross_post_jobs jv
   WHERE rv.statut = 'proposee' AND (p_user IS NULL OR rv.user_id = p_user)
     AND jv.id = rv.job_vendu AND COALESCE(jv.platform_fields, '{}'::jsonb) ? 'vente_annulee_remise'
     AND NOT EXISTS (SELECT 1 FROM inventaire ix
                      WHERE ix.id = rv.inventaire_id AND ix.user_id = rv.user_id AND ix.fusionne_dans IS NULL
                        AND ix.statut = 'stock' AND COALESCE(ix.quantite, 1) > 0);
  GET DIAGNOSTICS v_hors_stock = ROW_COUNT;

  UPDATE remises_en_vente rv SET statut = 'abandonnee', motif = 'deja_en_vente', traite_le = now()
    FROM cross_post_jobs jv, inventaire iv
   WHERE rv.statut = 'proposee' AND (p_user IS NULL OR rv.user_id = p_user)
     AND jv.id = rv.job_vendu AND COALESCE(jv.platform_fields, '{}'::jsonb) ? 'vente_annulee_remise'
     AND iv.id = rv.inventaire_id AND iv.user_id = rv.user_id
     AND (
       (rv.platform = 'vinted' AND NULLIF(btrim(jv.platform_listing_id), '') IS NOT NULL AND coalesce((
          SELECT sv.status = 'active' FROM vinted_listing_snapshots sv
           WHERE sv.user_id = rv.user_id AND sv.vinted_item_id = btrim(jv.platform_listing_id)
             AND sv.captured_at > COALESCE(NULLIF(jv.platform_fields #>> '{vente_annulee_remise,le}', '')::timestamptz, rv.cree_le)
           ORDER BY sv.captured_at DESC LIMIT 1), false))
       OR EXISTS (
          SELECT 1 FROM annonces_plateforme av
           WHERE av.user_id = rv.user_id AND av.inventaire_id = rv.inventaire_id AND av.platform = rv.platform
             AND av.statut_plateforme IN ('en_ligne', 'en_verification')
             AND av.disparu_le IS NULL AND av.retiree_le IS NULL AND av.ignoree_le IS NULL
             AND COALESCE(av.vu_le, av.created_at) > COALESCE(NULLIF(jv.platform_fields #>> '{vente_annulee_remise,le}', '')::timestamptz, rv.cree_le))
       OR (rv.platform = 'vinted' AND iv.vinted_item_id IS NOT NULL
           AND iv.vinted_item_id IS DISTINCT FROM NULLIF(btrim(jv.platform_listing_id), '')
           AND iv.disparu_le IS NULL AND COALESCE(iv.vinted_status, 'active') NOT IN ('sold', 'closed')));

  FOR v_f IN
    SELECT rv.user_id, rv.inventaire_id
      FROM remises_en_vente rv JOIN cross_post_jobs jv ON jv.id = rv.job_vendu
     WHERE rv.statut = 'proposee' AND (p_user IS NULL OR rv.user_id = p_user)
       AND COALESCE(jv.platform_fields, '{}'::jsonb) ? 'vente_annulee_remise'
     GROUP BY rv.user_id, rv.inventaire_id
     ORDER BY random()
     LIMIT 50
  LOOP
    BEGIN
      IF public.remise_annulee_jumelle_fermer(v_f.user_id, v_f.inventaire_id) IS NOT NULL THEN
        v_jumelles := v_jumelles + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'remises_en_vente_tick : jumelle (%, %) : %', v_f.user_id, v_f.inventaire_id, SQLERRM;
    END;
  END LOOP;

  FOR r IN
    SELECT * FROM remises_en_vente
     WHERE statut = 'a_faire' AND prochain_essai <= now()
       AND (p_user IS NULL OR user_id = p_user)
     ORDER BY prochain_essai
     LIMIT GREATEST(1, LEAST(p_limite, 50))
     FOR UPDATE SKIP LOCKED
  LOOP
    IF NOT EXISTS (SELECT 1 FROM remises_en_vente x WHERE x.id = r.id AND x.statut = 'a_faire') THEN CONTINUE; END IF;
    v_motif := NULL; v_report := NULL; v_nouveau := NULL;
    SELECT * INTO j FROM cross_post_jobs WHERE id = r.job_vendu;
    SELECT * INTO i FROM inventaire WHERE id = r.inventaire_id AND user_id = r.user_id;
    v_op := NULL;
    IF j.id IS NOT NULL AND NULLIF(j.platform_fields->>'vente_operation_cle', '') IS NOT NULL THEN
      SELECT o.resultat INTO v_op FROM ventes_operations o
       WHERE o.user_id = r.user_id AND o.cle = j.platform_fields->>'vente_operation_cle';
    END IF;
    v_annul := (j.id IS NOT NULL AND j.status = 'cancelled' AND (COALESCE(j.platform_fields, '{}'::jsonb) ? 'vente_annulee_remise'));
    v_restant := CASE WHEN v_annul THEN COALESCE(i.quantite, 1) ELSE NULLIF(v_op->>'restant', '')::integer END;

    IF j.id IS NULL OR (j.status <> 'sold' AND NOT v_annul) THEN
      v_motif := 'annonce_plus_vendue';
    ELSIF NOT v_annul AND (v_op IS NULL OR (v_op->>'ok') IS DISTINCT FROM 'true') THEN
      v_motif := 'vente_non_enregistree';
    ELSIF NOT v_annul AND COALESCE(NULLIF(v_op->>'restant', '')::integer, 0) <= 0 THEN
      v_motif := 'plus_de_stock';
    ELSIF i.id IS NULL OR i.fusionne_dans IS NOT NULL THEN
      v_motif := 'fiche_absente';
    ELSIF i.statut = 'vendu' OR COALESCE(i.quantite, 1) <= 0 THEN
      v_motif := 'plus_de_stock';
    ELSIF v_annul AND public.releve_apres_annulation(r.user_id, r.platform,
            GREATEST(COALESCE(NULLIF(j.platform_fields #>> '{vente_annulee_remise,le}', '')::timestamptz, r.cree_le),
                     COALESCE(r.accepte_le, r.cree_le) - interval '15 minutes')) = 'attendu' THEN
      v_motif := 'releve_attendu';
      v_report := CASE WHEN COALESCE(r.accepte_le, r.cree_le) < now() - interval '3 days' THEN NULL
                       ELSE now() + interval '20 minutes' END;
    ELSIF r.platform NOT IN ('vinted', 'beebs', 'opla', 'leboncoin', 'ebay', 'depop') THEN
      v_motif := 'plateforme_non_geree';
    ELSIF r.platform IN ('leboncoin', 'ebay')
      AND (COALESCE(j.platform_fields->>'source', '') = 'releve'
           OR COALESCE(j.platform_fields #>> '{rattachement,import}', '') = 'true')
      AND NOT (r.platform = 'leboncoin' AND COALESCE(j.action, 'publish') = 'republish')
      AND NOT (r.platform = 'ebay' AND (
            COALESCE(j.platform_fields #>> '{sale_evidence,exact}', '') = 'true'
         OR (COALESCE(j.platform_fields #>> '{quantite_ebay,exacte}', '') = 'true'
             AND COALESCE(NULLIF(j.platform_fields #>> '{quantite_ebay,disponible}', '')::numeric, 1) <= 0))) THEN
      v_motif := 'annonce_importee_a_quantite';
    ELSIF r.platform = 'opla' AND COALESCE(v_sortie, 0) > 0 AND now() >= to_timestamp(v_sortie) THEN
      v_motif := 'opla_sortie';
    ELSIF COALESCE(v_prix, 0) > 0 THEN
      v_motif := 'publication_payante';
    ELSIF (r.platform = 'vinted' AND NULLIF(btrim(j.platform_listing_id), '') IS NOT NULL AND (
             SELECT s.status = 'active' AND s.captured_at > COALESCE(j.sold_at, now())
               FROM vinted_listing_snapshots s
              WHERE s.user_id = r.user_id AND s.vinted_item_id = btrim(j.platform_listing_id)
              ORDER BY s.captured_at DESC LIMIT 1))
       OR (r.platform <> 'vinted' AND NULLIF(btrim(j.platform_listing_id), '') IS NOT NULL AND EXISTS (
             SELECT 1 FROM annonces_plateforme a
              WHERE a.user_id = r.user_id AND a.platform = r.platform AND a.listing_id = btrim(j.platform_listing_id)
                AND a.statut_plateforme = 'en_ligne' AND a.disparu_le IS NULL AND a.vu_le > COALESCE(j.sold_at, now())
                AND NOT (a.platform = 'leboncoin'
                         AND COALESCE(public.leboncoin_transaction_lue(a.transaction_plateforme, a.capture), '') IN ('pending', 'sold')))) THEN
      v_motif := 'annonce_vendue_encore_en_ligne'; v_report := now() + interval '6 hours';
    ELSIF EXISTS (
        SELECT 1 FROM cross_post_jobs c
         WHERE c.user_id = r.user_id AND c.inventaire_id = r.inventaire_id AND c.platform = r.platform
           AND c.id <> j.id AND COALESCE(c.action, 'publish') IN ('publish', 'republish')
           AND (c.status IN ('pending', 'processing', 'needs_user')
                OR (c.status = 'published' AND NOT EXISTS (
                      SELECT 1 FROM cross_post_jobs d
                       WHERE d.user_id = c.user_id AND d.inventaire_id = c.inventaire_id
                         AND d.platform = c.platform AND d.action = 'delete' AND d.status = 'deleted'
                         AND CASE WHEN annonce_id_de_job(d.platform_listing_id, d.listing_url) IS NOT NULL
                                   AND annonce_id_de_job(c.platform_listing_id, c.listing_url) IS NOT NULL
                                  THEN annonce_id_de_job(d.platform_listing_id, d.listing_url)
                                     = annonce_id_de_job(c.platform_listing_id, c.listing_url)
                                  ELSE d.created_at > COALESCE(c.published_at, c.created_at) END))))
      OR EXISTS (
        SELECT 1 FROM annonces_plateforme a
         WHERE a.user_id = r.user_id AND a.inventaire_id = r.inventaire_id AND a.platform = r.platform
           AND a.statut_plateforme IN ('en_ligne', 'en_verification')
           AND a.disparu_le IS NULL AND a.retiree_le IS NULL AND a.ignoree_le IS NULL
           AND a.listing_id IS DISTINCT FROM NULLIF(btrim(j.platform_listing_id), '')
           AND NOT (a.platform = 'leboncoin'
                    AND COALESCE(public.leboncoin_transaction_lue(a.transaction_plateforme, a.capture), '') IN ('pending', 'sold'))
           AND COALESCE(a.vu_le, a.created_at) > COALESCE(j.sold_at, now()))
      OR (r.platform = 'vinted' AND i.vinted_item_id IS NOT NULL
          AND i.vinted_item_id IS DISTINCT FROM NULLIF(btrim(j.platform_listing_id), '')
          AND i.disparu_le IS NULL AND COALESCE(i.vinted_status, 'active') NOT IN ('sold', 'closed')) THEN
      v_motif := 'deja_en_vente';
    END IF;

    IF v_motif IS NULL AND EXISTS (SELECT 1 FROM platform_health h WHERE h.platform = r.platform AND h.paused) THEN
      v_motif := 'plateforme_en_pause'; v_report := now() + interval '1 hour';
    END IF;
    IF v_motif IS NULL THEN
      SELECT p.extension_last_seen_at, COALESCE(p.ebay_voie_api, false) INTO v_vu, v_api
        FROM profiles p WHERE p.id = r.user_id;
      IF NOT (v_vu > now() - interval '7 days' OR (r.platform = 'ebay' AND v_api)) THEN
        v_motif := 'poste_absent'; v_report := now() + interval '6 hours';
      END IF;
    END IF;
    IF v_motif IS NULL AND NOT v_annul THEN
      v_place := remise_en_vente_place(r.user_id);
      IF (v_place->>'place') IS DISTINCT FROM 'true' THEN
        v_motif := v_place->>'motif';
        v_report := NULLIF(v_place->>'reprise', '')::timestamptz;
        IF v_report IS NULL THEN v_report := 'infinity'; END IF;
      END IF;
    END IF;

    v_rep := '{}'::jsonb;
    IF v_motif IS NULL AND r.platform = 'vinted' AND v_annul THEN
      v_trans := NULLIF(btrim(COALESCE(j.platform_fields #>> '{vente_annulee_remise,commande}', '')), '');
      IF v_trans IS NULL OR v_trans !~ '^[0-9]+$' OR NULLIF(btrim(j.platform_listing_id), '') IS NULL THEN
        v_motif := 'republier_commande_inconnue';
      ELSE
        SELECT NULLIF(btrim(pc.conversation_ref), '') INTO v_conv FROM plateforme_commandes pc
         WHERE pc.user_id = r.user_id AND pc.platform = 'vinted' AND pc.commande_ref = v_trans
         ORDER BY pc.maj_le DESC NULLS LAST LIMIT 1;
        v_rep := jsonb_build_object('remise_par_republier', jsonb_build_object(
          'transaction_id', v_trans, 'conversation_id', v_conv, 'item_id', btrim(j.platform_listing_id),
          'vente', j.platform_fields #>> '{vente_annulee_remise,vente}', 'annulee_le', j.platform_fields #>> '{vente_annulee_remise,le}',
          'job_vendu', j.id, 'cree_le', now()));
      END IF;
    END IF;

    IF v_motif IS NULL AND v_annul THEN
      BEGIN
        v_jum := public.remise_annulee_jumelle_fermer(r.user_id, r.inventaire_id);
      EXCEPTION WHEN OTHERS THEN
        v_jum := NULL; v_motif := 'jumelle_non_verifiee'; v_report := now() + interval '1 hour';
      END;
      IF v_jum IS NOT NULL THEN
        v_abandons := v_abandons + 1; v_jumelles := v_jumelles + 1;
        CONTINUE;
      END IF;
    END IF;

    IF v_motif IS NULL THEN
      BEGIN
        INSERT INTO cross_post_jobs (user_id, inventaire_id, platform, status, action, photo_option,
                                     title, description, price, photos, platform_fields)
        VALUES (r.user_id, r.inventaire_id, r.platform, 'pending', 'publish', COALESCE(j.photo_option, 'original'),
                coalesce(nullif(btrim(j.title), ''), i.titre), coalesce(nullif(btrim(j.description), ''), i.description),
                coalesce(j.price, i.prix_vente),
                CASE WHEN jsonb_typeof(j.photos) = 'array' AND jsonb_array_length(j.photos) > 0
                          THEN public.photos_ordre_article(j.photos, i.photos, j.platform_fields)
                     WHEN jsonb_typeof(i.photos) = 'array' THEN i.photos ELSE j.photos END,
                remise_en_vente_champs(j.platform_fields) || jsonb_build_object('remise_en_vente',
                  jsonb_build_object('apres_vente_job', j.id, 'annonce_vendue', NULLIF(btrim(j.platform_listing_id), ''),
                                     'vente', j.platform_fields->>'vente_operation_cle',
                                     'restant', v_restant, 'apres_annulation', v_annul, 'le', now()))
                || CASE WHEN v_annul THEN jsonb_build_object('hors_quota', true) ELSE '{}'::jsonb END
                || v_rep)
        RETURNING id INTO v_nouveau;
      EXCEPTION
        WHEN unique_violation THEN v_motif := 'deja_en_vente';
        WHEN OTHERS THEN v_motif := 'refus_creation: ' || left(SQLERRM, 160);
      END;
    END IF;

    IF v_nouveau IS NOT NULL THEN
      UPDATE remises_en_vente SET statut = 'faite', motif = NULL, job_cree = v_nouveau,
             essais = essais + 1, traite_le = now() WHERE id = r.id;
      INSERT INTO usage_logs (user_id, feature, metadata)
      VALUES (r.user_id, 'remise_en_vente', jsonb_build_object('plateforme', r.platform,
        'inventaire_id', r.inventaire_id::text, 'job_vendu', j.id, 'job_cree', v_nouveau,
        'restant', v_restant, 'apres_annulation', v_annul, 'par_republier', v_rep ? 'remise_par_republier'));
      v_faites := v_faites + 1;
    ELSIF v_report IS NOT NULL AND v_report <> 'infinity' THEN
      UPDATE remises_en_vente SET motif = v_motif, essais = essais + 1, prochain_essai = v_report,
             traite_le = now() WHERE id = r.id;
      v_reports := v_reports + 1;
    ELSE
      UPDATE remises_en_vente SET statut = 'abandonnee', motif = v_motif, essais = essais + 1,
             traite_le = now() WHERE id = r.id;
      v_abandons := v_abandons + 1;
    END IF;
  END LOOP;
  BEGIN
    v_questions := public.remise_annulee_questions(p_user, 20);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'remises_en_vente_tick : questions après annulation : %', SQLERRM;
  END;
  RETURN jsonb_build_object('issue', 'tour', 'faites', v_faites, 'reportees', v_reports,
                            'abandonnees', v_abandons, 'cpu', v_cpu,
                            'hors_stock', v_hors_stock, 'jumelles', v_jumelles, 'questions', v_questions);
END;
$function$

CREATE OR REPLACE FUNCTION public.republish_maintenance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v text; cle int;
begin
  if coalesce(new.action,'') <> 'republish' then return new; end if;

  begin
    if exists (select 1 from public.platform_health h where h.platform = coalesce(new.platform, 'vinted') and h.paused = true) then
      raise exception 'REPUBLISH_MAINTENANCE: La republication sur cette plateforme est momentanement en pause, nous travaillons dessus. Tes annonces sont protegees et aucune Pepite n''est debitee.';
    end if;
  exception when others then
    if sqlerrm like 'REPUBLISH_MAINTENANCE:%' then raise; end if;
  end;

  select coalesce(value,0) into cle from coin_config where key = 'republish_maintenance';
  cle := coalesce(cle, 0);

  if cle = 1 then
    raise exception 'REPUBLISH_MAINTENANCE: La republication est temporairement en maintenance. Tes annonces sont protegees et aucune Pepite n''est debitee. On te previent des que c''est retabli.';
  end if;

  select extension_version into v from profiles where id = new.user_id;
  if public.version_cle(v) is null or public.version_cle(v) < public.version_cle('0.6.2') then
    raise exception 'REPUBLISH_MAINTENANCE: Ta version de l''extension doit etre mise a jour avant de republier. Chrome installe la nouvelle version automatiquement, elle arrivera d''ici quelques heures. Tes annonces sont protegees et aucune Pepite n''est debitee.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.republish_planifiee_reglage(p_user uuid, p_platform text DEFAULT 'vinted'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pf text := lower(COALESCE(NULLIF(trim(p_platform), ''), 'vinted'));
  v_brut jsonb; v_palier text;
  v_type text; v_de time; v_a time; v_fuseau text; v_jours integer[];
  v_plafond integer; v_age integer; v_ordre text; v_pb jsonb := '{}'::jsonb;
  v_k text; v_n integer; v_invalide text := NULL; v_actif boolean;
BEGIN
  IF NOT (v_pf = ANY (republish_planifiee_plateformes())) THEN RETURN NULL; END IF;
  IF v_pf = 'depop' AND NOT public.depop_autorise(p_user) THEN RETURN NULL; END IF;

  SELECT p.platform_settings #> ARRAY[v_pf, 'republish_planifiee'] INTO v_brut
  FROM profiles p WHERE p.id = p_user;
  IF v_brut IS NULL OR jsonb_typeof(v_brut) <> 'object' THEN RETURN NULL; END IF;

  v_palier := republish_palier(p_user);
  IF v_palier NOT IN ('pro', 'business') THEN v_invalide := 'palier'; END IF;
  IF public.republish_planifiee_pf_sortie(v_pf) THEN v_invalide := 'plateforme_sortie'; END IF;

  v_fuseau := COALESCE(NULLIF(v_brut ->> 'fuseau', ''), 'Europe/Paris');
  BEGIN
    PERFORM now() AT TIME ZONE v_fuseau;
  EXCEPTION WHEN OTHERS THEN v_fuseau := 'Europe/Paris';
  END;

  v_type := COALESCE(v_brut ->> 'creneau', 'matin');
  CASE v_type
    WHEN 'matin' THEN v_de := '08:00'; v_a := '10:00';
    WHEN 'midi'  THEN v_de := '12:00'; v_a := '14:00';
    WHEN 'soir'  THEN v_de := '19:00'; v_a := '22:00';
    WHEN 'perso' THEN
      BEGIN
        v_de := (v_brut ->> 'de')::time; v_a := (v_brut ->> 'a')::time;
      EXCEPTION WHEN OTHERS THEN v_de := NULL; v_a := NULL;
      END;
      IF v_de IS NULL OR v_a IS NULL OR v_a <= v_de THEN v_invalide := COALESCE(v_invalide, 'creneau'); END IF;
    ELSE v_invalide := COALESCE(v_invalide, 'creneau');
  END CASE;

  IF v_brut ? 'jours' THEN
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), '{}'::integer[]) INTO v_jours
    FROM (
      SELECT (e)::integer AS x
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_brut -> 'jours') = 'array' THEN v_brut -> 'jours' ELSE '[]'::jsonb END) e
      WHERE e ~ '^[1-7]$'
    ) s;
    IF cardinality(v_jours) = 0 THEN v_invalide := COALESCE(v_invalide, 'jours'); END IF;
  ELSE
    v_jours := ARRAY[1,2,3,4,5,6,7];
  END IF;

  BEGIN v_plafond := NULLIF(v_brut ->> 'plafond_jour', '')::integer; EXCEPTION WHEN OTHERS THEN v_plafond := NULL; END;
  v_plafond := CASE WHEN v_plafond IS NULL THEN NULL ELSE GREATEST(1, v_plafond) END;

  BEGIN v_age := NULLIF(v_brut ->> 'age_jours', '')::integer; EXCEPTION WHEN OTHERS THEN v_age := NULL; END;
  v_age := LEAST(365, GREATEST(7, COALESCE(v_age, 30)));

  v_ordre := COALESCE(v_brut ->> 'ordre', 'anciennes');
  IF v_ordre NOT IN ('anciennes', 'prix', 'vues') THEN v_ordre := 'anciennes'; END IF;
  IF v_ordre = 'vues' AND v_pf <> 'vinted' THEN v_ordre := 'anciennes'; END IF;

  IF v_pf = 'vinted' AND jsonb_typeof(v_brut -> 'plafond_boutique') = 'object' THEN
    FOR v_k IN SELECT jsonb_object_keys(v_brut -> 'plafond_boutique') LOOP
      BEGIN v_n := (v_brut -> 'plafond_boutique' ->> v_k)::integer; EXCEPTION WHEN OTHERS THEN v_n := NULL; END;
      IF v_n IS NOT NULL THEN
        v_pb := v_pb || jsonb_build_object(v_k, LEAST(v_plafond, GREATEST(1, v_n)));
      END IF;
    END LOOP;
  END IF;

  v_actif := COALESCE((v_brut ->> 'actif')::boolean, false) AND v_invalide IS NULL;

  RETURN jsonb_build_object(
    'platform', v_pf,
    'actif', v_actif,
    'invalide', v_invalide,
    'palier', v_palier,
    'creneau', v_type,
    'de', to_char(v_de, 'HH24:MI'),
    'a', to_char(v_a, 'HH24:MI'),
    'fuseau', v_fuseau,
    'jours', to_jsonb(v_jours),
    'plafond_jour', v_plafond,
    'plafond_boutique', v_pb,
    'age_jours', v_age,
    'ordre', v_ordre,
    'active_le', v_brut ->> 'active_le',
    'arrete_le', v_brut ->> 'arrete_le',
    'arret_motif', v_brut ->> 'arret_motif',
    'palier_perdu_le', v_brut ->> 'palier_perdu_le',
    'pause_generale', COALESCE((v_brut ->> 'pause_generale')::boolean, false)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.republish_refund_on_terminal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_montant integer;
BEGIN
  IF NEW.action IS DISTINCT FROM 'republish' THEN RETURN NEW; END IF;
  IF NEW.status NOT IN ('failed', 'cancelled', 'dry_run_completed') THEN RETURN NEW; END IF;
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
  IF (NEW.platform_fields->>'pepite_remboursee') = 'true' THEN RETURN NEW; END IF;

  IF NEW.published_at IS NOT NULL
     OR (NEW.platform_fields->>'new_vinted_item_id') IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_montant := COALESCE(NULLIF(NEW.platform_fields->>'pepites_debitees', '')::integer, 0);
  IF v_montant > 0 THEN
    PERFORM refund_coins(NEW.user_id, v_montant,
      jsonb_build_object('source', 'republish_' || NEW.status, 'job_id', NEW.id),
      'refund_republish');
    NEW.platform_fields := jsonb_set(COALESCE(NEW.platform_fields, '{}'::jsonb),
      '{pepite_remboursee}', 'true'::jsonb);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.retrait_cible_vivante(p_user uuid, p_inv bigint, p_platform text, p_url text, p_pid text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pf       text := lower(coalesce(p_platform, ''));
  v_nom      text;
  v_cible    text;
  v_rempl    record;
  v_encours  record;
  v_ids      text[];
  v_vers     text;
  v_sans_lien integer;
  intacte    constant jsonb := jsonb_build_object('verdict', 'intacte');
begin
  if v_pf not in ('vinted', 'leboncoin', 'beebs', 'opla', 'depop') or p_inv is null or p_user is null then
    return intacte;
  end if;
  v_nom := case v_pf when 'vinted' then 'Vinted' when 'leboncoin' then 'Leboncoin' when 'beebs' then 'Beebs' when 'depop' then 'Depop' else 'Opla' end;
  v_cible := coalesce(public.annonce_id_job(v_pf, p_url), nullif(btrim(p_pid), ''));
  if v_cible is null or length(v_cible) < 4 then return intacte; end if;

  if exists (
    select 1 from public.cross_post_jobs j
     where j.user_id = p_user and j.platform = v_pf and j.status = 'published'
       and coalesce(j.action, 'publish') in ('publish', 'republish')
       and (public.annonce_id_job(v_pf, j.listing_url) = v_cible
            or nullif(btrim(j.platform_listing_id), '') = v_cible)) then
    return intacte;
  end if;

  select r.id, r.status, r.platform_fields ->> 'republish_step' as etape,
    coalesce(nullif(btrim(r.platform_fields->>'new_vinted_item_id'),''),
      nullif(btrim(r.platform_listing_id),''),public.annonce_id_job(v_pf,r.listing_url)) as nouvel_identifiant
    into v_rempl
    from public.cross_post_jobs r
   where r.user_id = p_user and r.inventaire_id = p_inv and r.platform = v_pf and r.action = 'republish'
     and v_cible in (
           nullif(btrim(r.platform_fields ->> 'old_platform_listing_id'), ''),
           public.annonce_id_job(v_pf, r.platform_fields ->> 'old_listing_url'),
           public.annonce_id_job(v_pf, r.platform_fields -> 'republish_snapshot' ->> 'listing_url'),
           case when v_pf = 'vinted' then nullif(btrim(r.platform_fields ->> 'vinted_item_id_avant'), '') end,
           case when v_pf = 'vinted' then nullif(btrim(r.platform_fields ->> 'vinted_item_id'), '') end)
     and (r.platform_fields ->> 'republish_step' = 'recreated'
          or coalesce(case when v_pf = 'vinted' then nullif(btrim(r.platform_fields ->> 'new_vinted_item_id'), '') end,
                      nullif(btrim(r.platform_listing_id), ''),
                      public.annonce_id_job(v_pf, r.listing_url)) is distinct from v_cible)
   order by r.created_at desc
   limit 1;

  if v_rempl.id is null then
    select r.id into v_encours
      from public.cross_post_jobs r
     where r.user_id = p_user and r.inventaire_id = p_inv and r.platform = v_pf and r.action = 'republish'
       and r.status in ('pending', 'processing', 'needs_user')
       and r.platform_fields ->> 'republish_step' = 'deleted'
       and v_cible in (
             nullif(btrim(r.platform_fields ->> 'old_platform_listing_id'), ''),
             public.annonce_id_job(v_pf, r.platform_fields ->> 'old_listing_url'),
             public.annonce_id_job(v_pf, r.platform_fields -> 'republish_snapshot' ->> 'listing_url'),
             public.annonce_id_job(v_pf, r.listing_url),
             case when v_pf = 'vinted' then nullif(btrim(r.platform_fields ->> 'vinted_item_id_avant'), '') end,
             case when v_pf = 'vinted' then nullif(btrim(r.platform_fields ->> 'vinted_item_id'), '') end)
     order by r.created_at desc
     limit 1;
    if v_encours.id is null then
      return intacte;
    end if;
    return jsonb_build_object('verdict', 'attente', 'raison', 'republication_en_cours', 'cible', v_cible,
      'republication', v_encours.id,
      'motif', format('Retrait en attente : cette annonce %s est en cours de republication (l''ancienne est déjà retirée, la nouvelle pas encore en ligne). Le retrait visera la nouvelle annonce dès qu''elle existera — rien n''est retiré à l''aveugle.', v_nom));
  end if;

  select coalesce(array_agg(distinct x.id_annonce) filter (where x.id_annonce is not null), '{}'),
         count(*) filter (where x.id_annonce is null)
    into v_ids, v_sans_lien
    from (select coalesce(public.annonce_id_job(v_pf, j.listing_url), nullif(btrim(j.platform_listing_id), '')) as id_annonce
            from public.cross_post_jobs j
           where j.user_id = p_user and j.inventaire_id = p_inv and j.platform = v_pf and j.status = 'published'
             and coalesce(j.action, 'publish') in ('publish', 'republish')
             and public.retrait_job_prouve(j.id)
             and public.listing_designe(v_rempl.nouvel_identifiant,j.listing_url,j.platform_listing_id)) x
   where x.id_annonce is distinct from v_cible;

  if coalesce(array_length(v_ids, 1), 0) = 0 and v_sans_lien = 0 then
    return intacte;
  end if;
  if coalesce(array_length(v_ids, 1), 0) = 1 and v_sans_lien = 0 then
    select j.listing_url into v_vers
      from public.cross_post_jobs j
     where j.user_id = p_user and j.inventaire_id = p_inv and j.platform = v_pf and j.status = 'published'
       and coalesce(j.action, 'publish') in ('publish', 'republish')
             and public.retrait_job_prouve(j.id)
             and public.listing_designe(v_rempl.nouvel_identifiant,j.listing_url,j.platform_listing_id)
       and coalesce(public.annonce_id_job(v_pf, j.listing_url), nullif(btrim(j.platform_listing_id), '')) = v_ids[1]
       and nullif(btrim(j.listing_url), '') is not null
     order by coalesce(j.published_at, j.created_at) desc
     limit 1;
    if v_vers is not null then
      return jsonb_build_object('verdict', 'redirigee', 'cible', v_cible, 'vers', v_vers,
                                'vers_id', v_ids[1], 'republication', v_rempl.id);
    end if;
  end if;
  return jsonb_build_object('verdict', 'attente', 'cible', v_cible, 'republication', v_rempl.id,
    'raison', case when coalesce(array_length(v_ids, 1), 0) = 0 then 'lien_inconnu' else 'plusieurs_vivantes' end,
    'motif', case when coalesce(array_length(v_ids, 1), 0) = 0
      then format('Retrait en attente : cette annonce %s a été remplacée par une republication dont le lien n''est pas encore connu. Le retrait visera la nouvelle annonce dès que son lien sera repéré — rien n''est retiré à l''aveugle.', v_nom)
      else format('Retrait en attente : cette annonce %s a été remplacée par une republication, et plusieurs annonces de cet article sont en ligne sur %s. Rien n''est retiré à l''aveugle : retire la bonne depuis la fiche de l''article.', v_nom, v_nom) end);
end;
$function$

CREATE OR REPLACE FUNCTION public.retrait_garde_vendue_et_doublon()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item   text;
  v_url    text;
  v_ident  text;
  v_autre  uuid;
begin
  if new.action is distinct from 'delete' or new.status is distinct from 'pending' then
    return new;
  end if;

  begin

  if new.platform = 'vinted' then
    v_item := coalesce(
      case when new.platform_listing_id ~ '^\d+$' then new.platform_listing_id end,
      substring(new.listing_url from '/items/(\d+)'));
    v_ident := case when v_item is not null then 'vinted:' || v_item end;
  elsif nullif(btrim(new.platform_listing_id), '') is not null then
    v_ident := new.platform || ':' || btrim(new.platform_listing_id);
  elsif nullif(btrim(new.listing_url), '') is not null then
    v_url := regexp_replace(split_part(split_part(btrim(new.listing_url), '?', 1), '#', 1), '/$', '');
    v_ident := new.platform || ':' || v_url;
  end if;

  if exists (
    select 1 from public.cross_post_jobs p
     where p.user_id = new.user_id and p.platform = new.platform
       and coalesce(p.action, 'publish') in ('publish', 'republish') and p.status = 'cancelled'
       and p.error in ('Réponse dans l''app : « je l''ai retirée moi-même » — pas une vente',
                       'Annonce retirée par le vendeur (confirmé dans l''app)')
       and public.retrait_meme_annonce(new.platform, new.platform_listing_id, new.listing_url, p.platform_listing_id, p.listing_url)
  ) then
    insert into public.usage_logs (user_id, feature, metadata)
    values (new.user_id, 'retrait_evite', jsonb_build_object(
      'motif', 'annonce_declaree_retiree_par_la_personne', 'platform', new.platform,
      'listing_id', new.platform_listing_id, 'listing_url', new.listing_url, 'inventaire_id', new.inventaire_id::text));
    return null;
  end if;

  if v_item is not null and public.vinted_annonce_vendue(new.user_id, v_item) then
    new.status := 'cancelled';
    new.error := 'Retrait inutile : cette annonce est vendue sur Vinted, elle n''est plus en vente. Aucune requête envoyée.';
    new.platform_fields := coalesce(new.platform_fields, '{}'::jsonb) || jsonb_build_object(
      'retrait_par', 'vendue_sur_la_plateforme',
      'retrait_non_envoye', jsonb_build_object('le', now(), 'motif', 'annonce_vendue', 'item', v_item,
        'pose_par', 'retrait_garde_vendue_et_doublon (création)'));
    return new;
  end if;

  if v_ident is not null then
    perform pg_advisory_xact_lock(hashtextextended(new.user_id::text || '|' || v_ident, 0));
    select j.id into v_autre
    from public.cross_post_jobs j
    where j.user_id = new.user_id and j.platform = new.platform and j.action = 'delete'
      and j.status in ('pending', 'processing', 'needs_user')
      and j.id <> new.id
      and case
            when new.platform = 'vinted' then
              coalesce(case when j.platform_listing_id ~ '^\d+$' then j.platform_listing_id end,
                       substring(j.listing_url from '/items/(\d+)')) = v_item
            when nullif(btrim(new.platform_listing_id), '') is not null then
              btrim(j.platform_listing_id) = btrim(new.platform_listing_id)
            else
              regexp_replace(split_part(split_part(btrim(j.listing_url), '?', 1), '#', 1), '/$', '') = v_url
          end
    order by j.created_at
    limit 1;
    if v_autre is not null then
      new.status := 'cancelled';
      new.error := 'Doublon : un retrait est déjà en cours pour cette annonce.';
      new.platform_fields := coalesce(new.platform_fields, '{}'::jsonb) || jsonb_build_object(
        'retrait_doublon_de', jsonb_build_object('job', v_autre, 'le', now(), 'annonce', v_ident,
          'pose_par', 'retrait_garde_vendue_et_doublon (création)'));
    end if;
  end if;

  exception when others then
    raise warning 'retrait_garde_vendue_et_doublon (job %) : % — retrait créé comme avant', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.retrait_identifiant_depuis_lien()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.action = 'delete' AND NULLIF(btrim(NEW.platform_listing_id), '') IS NULL AND NULLIF(btrim(NEW.listing_url), '') IS NOT NULL THEN
    NEW.platform_listing_id := public.identifiant_annonce_depuis_lien(NEW.platform, NEW.listing_url);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.retrait_redirige_annonce_remplacee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v jsonb;
  v_pf jsonb;
  v_cible_url text;
begin
  if new.action is distinct from 'delete' or new.status is distinct from 'pending' then return new; end if;
  if tg_op = 'UPDATE' and old.status = 'pending' then return new; end if;
  begin
    v_pf := coalesce(new.platform_fields, '{}'::jsonb);
    v_cible_url := coalesce(v_pf -> 'retrait_en_attente' ->> 'lien', new.listing_url);
    v := public.retrait_cible_vivante(new.user_id, new.inventaire_id, new.platform, v_cible_url, new.platform_listing_id);
    if v ->> 'verdict' = 'redirigee' then
      new.platform_fields := (v_pf - 'retrait_en_attente') || jsonb_build_object('retrait_redirige', jsonb_build_object(
        'le', now(), 'de', v_cible_url, 'vers', v ->> 'vers', 'republication', v ->> 'republication',
        'pose_par', 'retrait_redirige_annonce_remplacee (annonce visée déjà remplacée par une republication)'));
      new.listing_url := v ->> 'vers';
      if nullif(btrim(new.platform_listing_id), '') is not null then
        new.platform_listing_id := v ->> 'vers_id';
      end if;
      if new.error is not null and v_pf ? 'retrait_en_attente' then new.error := null; end if;
    elsif v ->> 'verdict' = 'attente' then
      new.status := 'needs_user';
      new.error := v ->> 'motif';
      new.platform_fields := v_pf || jsonb_build_object('retrait_en_attente', jsonb_build_object(
        'le', coalesce(v_pf -> 'retrait_en_attente' ->> 'le', now()::text), 'lien', v_cible_url,
        'raison', v ->> 'raison', 'republication', v ->> 'republication',
        'pose_par', 'retrait_redirige_annonce_remplacee (jamais de retrait à l''aveugle)'));
    end if;
  exception when others then
    raise warning 'retrait_redirige_annonce_remplacee (job %) : % — retrait inchangé', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.retrait_rejuge_apres_republication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  d record;
  v jsonb;
  v_url text;
begin
  begin
    for d in
      select j.id, j.status, j.listing_url, j.platform_listing_id, j.platform_fields
        from public.cross_post_jobs j
       where j.user_id = new.user_id and j.inventaire_id = new.inventaire_id and j.platform = new.platform
         and j.action = 'delete'
         and ((j.status = 'needs_user' and j.platform_fields ? 'retrait_en_attente')
              or j.status = 'pending')
    loop
      v_url := coalesce(d.platform_fields -> 'retrait_en_attente' ->> 'lien', d.listing_url);
      v := public.retrait_cible_vivante(new.user_id, new.inventaire_id, new.platform, v_url, d.platform_listing_id);
      if d.status = 'needs_user' then
        if v ->> 'verdict' in ('redirigee', 'intacte') then
          update public.cross_post_jobs set status = 'pending', error = null
           where id = d.id and status = 'needs_user';
        end if;
      elsif v ->> 'verdict' in ('redirigee', 'attente') then
        update public.cross_post_jobs
           set status = 'needs_user',
               platform_fields = coalesce(platform_fields, '{}'::jsonb) || jsonb_build_object('retrait_en_attente',
                 jsonb_build_object('le', now()::text, 'lien', v_url, 'raison', 'rejuge_apres_republication',
                                    'republication', new.id, 'pose_par', 'retrait_rejuge_apres_republication'))
         where id = d.id and status = 'pending';
        update public.cross_post_jobs set status = 'pending'
         where id = d.id and status = 'needs_user';
      end if;
    end loop;
  exception when others then
    raise warning 'retrait_rejuge_apres_republication (job %) : %', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.settle_publish_reservation(p_reservation uuid, p_mode text, p_amount integer DEFAULT NULL::integer, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r         coin_reservations%ROWTYPE;
  v_remain  integer;
  v_amt     integer;
  v_rel_pur integer;
  v_rel_inc integer;
  v_wallet  coin_wallets%ROWTYPE;
BEGIN
  IF p_mode NOT IN ('capture','release') THEN
    RAISE EXCEPTION 'settle_publish_reservation: mode invalide %', p_mode;
  END IF;
  SELECT * INTO r FROM coin_reservations WHERE id = p_reservation FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  v_remain := r.amount - r.captured - r.released_included - r.released_purchased;
  v_amt := LEAST(COALESCE(p_amount, r.unit_price), v_remain);
  IF v_amt > 0 THEN
    IF p_mode = 'capture' THEN
      UPDATE coin_reservations SET captured = captured + v_amt WHERE id = r.id;
      UPDATE coin_wallets SET
        reserved_balance = GREATEST(0, reserved_balance - v_amt),
        updated_at = now()
      WHERE user_id = r.user_id;
    ELSE
      v_rel_pur := LEAST(v_amt, r.from_purchased - r.released_purchased);
      v_rel_inc := v_amt - v_rel_pur;
      UPDATE coin_reservations SET
        released_purchased = released_purchased + v_rel_pur,
        released_included  = released_included  + v_rel_inc
      WHERE id = r.id;
      UPDATE coin_wallets SET
        reserved_balance  = GREATEST(0, reserved_balance - v_amt),
        purchased_balance = purchased_balance + v_rel_pur,
        included_balance  = included_balance  + v_rel_inc,
        updated_at = now()
      WHERE user_id = r.user_id
      RETURNING * INTO v_wallet;
      INSERT INTO coin_ledger (user_id, delta, included_after, purchased_after, kind, metadata)
      VALUES (
        r.user_id, v_amt,
        COALESCE(v_wallet.included_balance, 0), COALESCE(v_wallet.purchased_balance, 0),
        'release_publish',
        jsonb_build_object('reservation_id', r.id, 'reason', COALESCE(p_reason, 'job_terminal'))
      );
    END IF;
  END IF;
  SELECT * INTO r FROM coin_reservations WHERE id = p_reservation;
  IF r.captured + r.released_included + r.released_purchased >= r.amount AND r.status = 'held' THEN
    UPDATE coin_reservations SET
      status = CASE
        WHEN r.captured = r.amount THEN 'captured'
        WHEN r.captured = 0        THEN 'released'
        ELSE 'partial'
      END,
      resolved_at = now()
    WHERE id = r.id;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.signal_vente_clore_meme_cession(p_job uuid, p_vente bigint, p_par text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j public.cross_post_jobs%ROWTYPE; v_cle text; v_res jsonb;
BEGIN
  SELECT * INTO j FROM public.cross_post_jobs WHERE id = p_job FOR UPDATE;
  IF j.id IS NULL OR j.status IS DISTINCT FROM 'published' OR p_vente IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'venteCreated', false, 'inventaireUpdated', false,
      'reason', 'Cette annonce n’est plus à confirmer comme vendue.');
  END IF;
  v_cle := CASE WHEN nullif(btrim(j.platform_listing_id), '') IS NOT NULL
    THEN 'annonce:' || j.platform || ':' || btrim(j.platform_listing_id) ELSE 'job:' || j.id::text END;
  v_res := jsonb_build_object('ok', true, 'venteCreated', false, 'inventaireUpdated', false,
    'siblingsCancelled', 0, 'pendingRemoval', 0, 'retraitsArmes', 0, 'emailSent', false, 'venteNotee', false,
    'meme_cession', true, 'vente_saisie', p_vente, 'ventes_ids', to_jsonb(ARRAY[p_vente]), 'rejouee', false,
    'reason', 'Cette vente était déjà enregistrée : l’annonce est classée vendue, rien n’est compté deux fois.');
  INSERT INTO public.ventes_operations (user_id, cle, inventaire_id, job_id, resultat)
  VALUES (j.user_id, v_cle, j.inventaire_id, j.id, v_res)
  ON CONFLICT (user_id, cle) DO NOTHING;
  PERFORM set_config('fillsell.vente_declaree', '1', true);
  UPDATE public.cross_post_jobs SET status = 'sold', sold_at = now(), last_checked_at = now(),
         platform_fields = coalesce(platform_fields, '{}'::jsonb) || jsonb_build_object(
           'vente_operation_cle', v_cle,
           'vente_meme_cession', jsonb_build_object('vente', p_vente, 'le', now(), 'par', p_par))
   WHERE id = j.id;
  PERFORM set_config('fillsell.vente_declaree', '', true);
  RETURN v_res;
END;
$function$

CREATE OR REPLACE FUNCTION public.signal_vente_clore_vente_relevee(p_job uuid, p_vente bigint, p_par text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j public.cross_post_jobs%ROWTYPE; v_res jsonb; v_fiche boolean := false;
BEGIN
  SELECT * INTO j FROM public.cross_post_jobs WHERE id = p_job;
  IF j.id IS NULL OR p_vente IS NULL OR public.vente_relevee_meme_cession(p_job) IS DISTINCT FROM p_vente THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'Cette vente ne correspond plus à cette annonce.');
  END IF;
  v_res := public.signal_vente_clore_meme_cession(p_job, p_vente, p_par);
  IF v_res ->> 'ok' IS DISTINCT FROM 'true' THEN RETURN v_res; END IF;
  PERFORM set_config('fillsell.vente_declaree', '1', true);
  UPDATE public.inventaire SET quantite = 0, statut = 'vendu'
   WHERE id = j.inventaire_id AND user_id = j.user_id AND statut = 'stock' AND coalesce(quantite, 1) <= 1;
  v_fiche := FOUND;
  PERFORM set_config('fillsell.vente_declaree', '', true);
  RETURN v_res || jsonb_build_object('inventaireUpdated', v_fiche, 'vente_relevee', p_vente,
    'reason', 'Cette vente était déjà enregistrée par ta commande Vinted : l’article passe vendu, rien n’est compté deux fois.');
END;
$function$

CREATE OR REPLACE FUNCTION public.signal_vente_vu_en_ligne(p_user uuid, p_listing text, p_signal timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_snap record;
BEGIN
  IF p_user IS NULL OR nullif(btrim(coalesce(p_listing, '')), '') IS NULL THEN RETURN NULL; END IF;
  SELECT s.status, s.captured_at INTO v_snap FROM public.vinted_listing_snapshots s
   WHERE s.user_id = p_user AND s.vinted_item_id = btrim(p_listing)
   ORDER BY s.captured_at DESC LIMIT 1;
  IF v_snap.status IS DISTINCT FROM 'active' THEN RETURN NULL; END IF;
  IF p_signal IS NULL OR v_snap.captured_at >= p_signal THEN RETURN v_snap.captured_at; END IF;
  IF EXISTS (SELECT 1 FROM public.vinted_sync_runs r
              WHERE r.user_id = p_user AND r.kind = 'dressing'
                AND r.started_at <= LEAST(v_snap.captured_at, p_signal)
                AND coalesce(r.finished_at, now()) >= GREATEST(v_snap.captured_at, p_signal)) THEN
    RETURN v_snap.captured_at;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.signaux_vente_reconcilier(p_max integer DEFAULT 40)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '8s'
AS $function$
DECLARE c record; v_vu timestamptz; v_vente bigint; v_res jsonb; n_dem integer := 0; n_fus integer := 0; n_vus integer := 0;
        n_rel integer := 0; v_ids_rel text[] := ARRAY[]::text[];
        v_ids_dem text[] := ARRAY[]::text[]; v_ids_fus text[] := ARRAY[]::text[];
        v_debut timestamptz := clock_timestamp(); v_budget boolean := false;
BEGIN
  FOR c IN
    SELECT j.id, j.user_id, j.platform, j.platform_listing_id, j.platform_fields
      FROM public.cross_post_jobs j
     WHERE j.status = 'published' AND (j.platform_fields ->> 'sale_signal') = 'sold'
       AND coalesce(j.action, 'publish') IN ('publish', 'republish')
     ORDER BY hashtextextended(j.id::text, floor(extract(epoch FROM now()) / 120)::bigint)
     LIMIT greatest(1, least(coalesce(p_max, 40), 200))
  LOOP
    IF clock_timestamp() - v_debut > interval '1500 milliseconds' THEN v_budget := true; EXIT; END IF;
    n_vus := n_vus + 1;
    IF c.platform = 'vinted' THEN
      v_vu := public.signal_vente_vu_en_ligne(c.user_id, c.platform_listing_id,
                public._ts_ou_null(c.platform_fields ->> 'unavailable_since'));
      IF v_vu IS NOT NULL THEN
        IF public.signal_vente_lever(c.id, 'signal_dementi_par_releve',
             jsonb_build_object('releve_le', v_vu, 'par', 'signaux_vente_reconcilier')) THEN
          n_dem := n_dem + 1; v_ids_dem := v_ids_dem || left(c.id::text, 8);
        END IF;
        CONTINUE;
      END IF;
    END IF;
    v_vente := public.vente_saisie_meme_cession(c.id);
    IF v_vente IS NOT NULL THEN
      v_res := public.signal_vente_clore_meme_cession(c.id, v_vente, 'signaux_vente_reconcilier');
      IF v_res ->> 'ok' = 'true' THEN n_fus := n_fus + 1; v_ids_fus := v_ids_fus || left(c.id::text, 8); END IF;
    ELSE
      v_vente := public.vente_relevee_meme_cession(c.id);
      IF v_vente IS NOT NULL THEN
        v_res := public.signal_vente_clore_vente_relevee(c.id, v_vente, 'signaux_vente_reconcilier');
        IF v_res ->> 'ok' = 'true' THEN n_rel := n_rel + 1; v_ids_rel := v_ids_rel || left(c.id::text, 8); END IF;
      END IF;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('vus', n_vus, 'dementis', n_dem, 'fusionnes', n_fus, 'releves', n_rel, 'budget_atteint', v_budget)
      || CASE WHEN n_rel > 0 THEN jsonb_build_object('releves_jobs', to_jsonb(v_ids_rel)) ELSE '{}'::jsonb END
      || CASE WHEN n_dem > 0 THEN jsonb_build_object('dementis_jobs', to_jsonb(v_ids_dem)) ELSE '{}'::jsonb END
      || CASE WHEN n_fus > 0 THEN jsonb_build_object('fusionnes_jobs', to_jsonb(v_ids_fus)) ELSE '{}'::jsonb END;
END;
$function$

CREATE OR REPLACE FUNCTION public.source_changement_courante()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v text := NULLIF(current_setting('fillsell.source_changement', true), '');
  v_h jsonb;
  v_role text;
BEGIN
  IF v IS NOT NULL THEN RETURN v; END IF;
  BEGIN
    v_h := NULLIF(current_setting('request.headers', true), '')::jsonb;
    IF COALESCE(v_h ->> 'origin', '') LIKE 'chrome-extension://%' THEN RETURN 'extension'; END IF;
    v_role := NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role';
    IF v_role = 'authenticated' THEN RETURN 'app'; END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN 'inconnu';
  END;
  RETURN 'serveur';
END;
$function$

CREATE OR REPLACE FUNCTION public.spend_coins_and_republish(p_inventaire_id bigint, p_vinted_item_id text, p_source text DEFAULT 'manuel'::text, p_prix_republication numeric DEFAULT NULL::numeric, p_platform text DEFAULT 'vinted'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user     uuid := auth.uid();
  v_partie   text;
  v_item     text := NULLIF(trim(p_vinted_item_id), '');
  v_platform text := lower(COALESCE(NULLIF(trim(p_platform), ''), 'vinted'));
  v_price    integer;
  v_wallet   coin_wallets%ROWTYPE;
  v_from_inc integer := 0;
  v_from_pur integer := 0;
  v_tier     text;
  v_prof     record;
  v_plafond  integer;
  v_faits    integer;
  v_qfree    jsonb;
  v_cycle    timestamptz;
  v_garde    jsonb;
  v_titre    text;
  v_prix     numeric;
  v_job_id   uuid;
  v_regl       jsonb;
  v_minuit     timestamptz;
  v_boutique   text;
  v_plafond_b  integer;
  v_faits_b    integer;
  v_multi      integer;
  v_min        integer;
  v_code       integer;
  v_statut     text;
  v_src        cross_post_jobs%ROWTYPE;
  v_pf_src     jsonb;
  v_photos_n   integer;
  v_photos     jsonb;
  v_lid      text;
  v_url      text;
  v_url_ins  text;
  v_fiches_n integer;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'unauthorized');
  END IF;
  IF v_platform = 'opla' AND COALESCE((SELECT value FROM coin_config WHERE key = 'opla_sortie_le'), 1791583200) > 0
     AND now() >= to_timestamp(COALESCE((SELECT value FROM coin_config WHERE key = 'opla_sortie_le'), 1791583200)) THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'opla_arrete', 'platform', v_platform,
      'message', 'Opla n''est plus disponible dans FillSell.');
  END IF;
  IF v_platform NOT IN ('vinted', 'leboncoin', 'beebs', 'opla', 'depop') THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_platform', 'platform', v_platform);
  END IF;
  IF v_platform = 'vinted' AND (v_item IS NULL OR v_item !~ '^\d+$') THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_item');
  END IF;
  IF p_source NOT IN ('manuel', 'auto') THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_source');
  END IF;
  IF p_source = 'auto' AND NOT republish_planifiee_pf_ouverte(v_platform) THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'plateforme_fermee', 'platform', v_platform);
  END IF;
  IF p_source = 'auto' AND v_platform = 'vinted' AND compte_en_pause_antirobot(v_user) THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'pause_antirobot', 'platform', v_platform);
  END IF;
  IF p_prix_republication IS NOT NULL AND p_prix_republication < 1 THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_price');
  END IF;

  SELECT is_premium, is_pro, is_business, is_comped, extension_last_seen_at, extension_version,
         lang, platform_settings
  INTO v_prof FROM profiles WHERE id = v_user;

  IF v_prof.extension_last_seen_at IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'extension_required',
      'message', CASE WHEN COALESCE(v_prof.lang, 'fr') = 'en'
        THEN 'Republishing requires the free FillSell Chrome extension on a computer. Nothing was used from your plan.'
        ELSE 'Pour republier, il faut l''extension Chrome gratuite FillSell sur un ordinateur. Rien n''a été décompté.'
      END);
  END IF;
  IF v_prof.extension_last_seen_at < now() - interval '7 days' THEN
    RETURN jsonb_build_object(
      'allowed', false, 'reason', 'extension_stale',
      'derniere_activite', v_prof.extension_last_seen_at,
      'message', CASE WHEN COALESCE(v_prof.lang, 'fr') = 'en'
        THEN 'Your FillSell extension hasn''t been seen for over a week. Open Chrome on your computer to wake it up, then try again. Nothing was used from your plan.'
        ELSE 'Ton extension FillSell ne s''est pas manifestée depuis plus d''une semaine. Ouvre Chrome sur ton ordinateur pour la réveiller, puis relance. Rien n''a été décompté.'
      END
    );
  END IF;

  IF version_cle(v_prof.extension_version) IS NULL
     OR version_cle(v_prof.extension_version) < version_cle('0.5.0') THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'extension_trop_ancienne',
                              'version', v_prof.extension_version);
  END IF;

  IF v_platform <> 'vinted' THEN
    SELECT value INTO v_multi FROM coin_config WHERE key = 'republication_multi_ouverte';
    IF COALESCE(v_multi, 0) <> 1 THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'republication_multi_fermee', 'platform', v_platform);
    END IF;
    SELECT value INTO v_min FROM coin_config WHERE key = 'republication_multi_extension_min';
    v_min := COALESCE(v_min, 642);
    v_code := CASE
      WHEN v_prof.extension_version ~ '^\d+\.\d+\.\d+' THEN
        (split_part(v_prof.extension_version, '.', 1))::integer * 10000
        + (split_part(v_prof.extension_version, '.', 2))::integer * 100
        + (regexp_replace(split_part(v_prof.extension_version, '.', 3), '\D.*$', ''))::integer
      ELSE 0 END;
    IF v_min > 0 AND v_code < v_min THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'extension_trop_ancienne',
                                'version', v_prof.extension_version, 'minimum', v_min, 'platform', v_platform);
    END IF;

    SELECT i.statut INTO v_statut FROM inventaire i WHERE i.id = p_inventaire_id AND i.user_id = v_user;
    IF v_statut IS NULL THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_item', 'platform', v_platform);
    END IF;
    IF v_statut = 'vendu' THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'article_vendu', 'platform', v_platform);
    END IF;

    SELECT j.* INTO v_src FROM cross_post_jobs j
    WHERE j.user_id = v_user AND j.inventaire_id = p_inventaire_id
      AND j.platform = v_platform AND j.action IN ('publish', 'republish')
      AND j.status = 'published' AND NULLIF(trim(j.listing_url), '') IS NOT NULL
    ORDER BY COALESCE(j.published_at, j.created_at) DESC
    LIMIT 1;
    IF v_src.id IS NULL THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'annonce_introuvable', 'platform', v_platform);
    END IF;

    v_lid := COALESCE(NULLIF(btrim(v_src.platform_listing_id), ''), annonce_id_job(v_platform, v_src.listing_url));
    v_url := NULLIF(btrim(v_src.listing_url), '');
    IF NULLIF(btrim(v_src.platform_listing_id), '') IS NOT NULL AND annonce_id_job(v_platform, v_url) IS NOT NULL
       AND annonce_id_job(v_platform, v_url) <> v_lid THEN
      v_url := NULL;
      SELECT a.url INTO v_url
        FROM annonces_plateforme a
       WHERE a.user_id = v_user AND a.platform = v_platform AND a.listing_id = v_lid
         AND NULLIF(btrim(a.url), '') IS NOT NULL
       ORDER BY a.vu_le DESC NULLS LAST
       LIMIT 1;
    END IF;
    IF v_url IS NULL THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'lien_annonce_incertain', 'cause', 'lien_inconnu',
        'platform', v_platform, 'annonce', v_lid,
        'message', 'Republication pas lancée : FillSell ne connaît pas le lien exact de ton annonce ' || initcap(v_platform)
          || '. Rien n''a été décompté, ton annonce est intacte. « Synchroniser » relit tes annonces.');
    END IF;
    IF v_lid IS NOT NULL THEN
      SELECT count(DISTINCT COALESCE(i.fusionne_dans, i.id)) INTO v_fiches_n
        FROM cross_post_jobs o
        JOIN inventaire i ON i.id = o.inventaire_id
       WHERE o.user_id = v_user AND o.platform = v_platform AND o.inventaire_id IS NOT NULL
         AND o.status IN ('pending', 'processing', 'published', 'needs_user')
         AND (listing_designe(v_lid, o.listing_url, o.platform_listing_id)
              OR annonce_id_job(o.platform, o.listing_url) = v_lid);
      IF COALESCE(v_fiches_n, 0) > 1 THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'lien_annonce_incertain', 'cause', 'annonce_partagee',
          'platform', v_platform, 'annonce', v_lid,
          'message', 'Republication pas lancée : cette annonce ' || initcap(v_platform) || ' est rattachée à deux articles. '
            || 'FillSell vérifie lequel la porte, puis la republication pourra partir. Rien n''a été décompté, ton annonce est intacte.');
      END IF;
    END IF;

    v_partie := public.republication_annonce_partie(v_user, p_inventaire_id, v_platform, v_lid);
    IF v_partie IS NOT NULL THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'annonce_introuvable', 'motif', v_partie,
        'platform', v_platform, 'annonce', v_lid,
        'message', CASE
          WHEN COALESCE(v_prof.lang, 'fr') = 'en' AND v_partie = 'annonce_vendue'
            THEN 'Repost not started: this ' || initcap(v_platform) || ' listing is sold. Nothing was used from your plan.'
          WHEN COALESCE(v_prof.lang, 'fr') = 'en'
            THEN 'Repost not started: this ' || initcap(v_platform) || ' listing is no longer online (confirmed by your syncs, '
              || 'not seen since). Nothing was used from your plan. « Sync » reads it again.'
          WHEN v_partie = 'annonce_vendue'
            THEN 'Republication pas lancée : cette annonce ' || initcap(v_platform) || ' est vendue. Rien n''a été décompté.'
          ELSE 'Republication pas lancée : cette annonce ' || initcap(v_platform) || ' n''est plus en ligne (confirmé par les relevés, '
            || 'pas revue depuis). Rien n''a été décompté. « Synchroniser » la relit.' END);
    END IF;

    IF EXISTS (
      SELECT 1 FROM cross_post_jobs j
      WHERE j.user_id = v_user AND j.action = 'republish'
        AND j.platform = v_platform AND j.inventaire_id = p_inventaire_id
        AND j.status IN ('pending', 'processing', 'needs_user')
    ) THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'republish_en_cours', 'platform', v_platform);
    END IF;
    IF EXISTS (
      SELECT 1 FROM cross_post_jobs j
      WHERE j.user_id = v_user AND j.action = 'republish'
        AND j.platform = v_platform AND j.inventaire_id = p_inventaire_id
        AND j.status = 'published'
        AND j.published_at > now() - interval '24 hours'
    ) THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'cadence_24h', 'platform', v_platform);
    END IF;

    v_photos := CASE WHEN jsonb_typeof(v_src.photos) = 'array' AND jsonb_array_length(v_src.photos) > 0
                     THEN v_src.photos ELSE NULL END;
    IF v_photos IS NULL THEN
      SELECT COALESCE(jsonb_agg(
               CASE WHEN jsonb_typeof(a.val) = 'string'
                    THEN jsonb_build_object('url', a.val #>> '{}',
                           'type', CASE WHEN a.ord = 1 THEN 'original' ELSE 'photo_' || (a.ord - 1) END)
                    ELSE a.val END
               ORDER BY a.ord), '[]'::jsonb) INTO v_photos
      FROM inventaire i,
      LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(i.photos) = 'array' THEN i.photos ELSE '[]'::jsonb END)
              WITH ORDINALITY AS a(val, ord)
      WHERE i.id = p_inventaire_id AND i.user_id = v_user
        AND COALESCE(NULLIF(trim(CASE WHEN jsonb_typeof(a.val) = 'string'
                                      THEN a.val #>> '{}' ELSE a.val->>'url' END), ''), '') <> '';
    END IF;
    v_photos := public.photos_ordre_article(v_photos,
      (SELECT i.photos FROM inventaire i WHERE i.id = p_inventaire_id AND i.user_id = v_user),
      v_src.platform_fields);
    v_photos_n := CASE WHEN jsonb_typeof(v_photos) = 'array' THEN jsonb_array_length(v_photos) ELSE 0 END;
    IF v_photos_n = 0 THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'article_sans_photo', 'platform', v_platform);
    END IF;
  END IF;

  v_tier := palier_de(v_user);

  IF p_source = 'auto' THEN
    IF NOT palier_au_moins(v_user, 'pro') THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'auto_reserve_pro');
    END IF;

    v_regl := republish_planifiee_reglage(v_user, v_platform);
    IF v_regl IS NOT NULL AND COALESCE((v_regl ->> 'actif')::boolean, false) THEN
      v_plafond := (v_regl ->> 'plafond_jour')::integer;
      v_minuit  := republish_minuit_local(COALESCE(v_regl ->> 'fuseau', 'Europe/Paris'));
      SELECT count(*) INTO v_faits
      FROM cross_post_jobs
      WHERE user_id = v_user AND action = 'republish' AND platform = v_platform
        AND platform_fields->>'republish_source' = 'auto'
        AND created_at >= v_minuit;
      IF v_plafond IS NOT NULL AND v_faits >= v_plafond THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'plafond_auto_atteint',
                                  'plafond', v_plafond, 'platform', v_platform);
      END IF;

      IF v_platform = 'vinted' THEN
        SELECT NULLIF(trim(i.vinted_account_id), '') INTO v_boutique
        FROM inventaire i WHERE i.id = p_inventaire_id AND i.user_id = v_user;
        IF v_boutique IS NOT NULL THEN
          v_plafond_b := NULLIF(v_regl -> 'plafond_boutique' ->> v_boutique, '')::integer;
          v_plafond_b := CASE WHEN v_plafond_b IS NULL THEN v_plafond ELSE LEAST(GREATEST(1, v_plafond_b), v_plafond) END;
          SELECT count(*) INTO v_faits_b
          FROM cross_post_jobs j JOIN inventaire i ON i.id = j.inventaire_id
          WHERE j.user_id = v_user AND j.action = 'republish' AND j.platform = 'vinted'
            AND j.platform_fields->>'republish_source' = 'auto'
            AND j.created_at >= v_minuit
            AND i.vinted_account_id = v_boutique;
          IF v_plafond_b IS NOT NULL AND v_faits_b >= v_plafond_b THEN
            RETURN jsonb_build_object('allowed', false, 'reason', 'plafond_boutique_atteint',
                                      'plafond', v_plafond_b, 'boutique', v_boutique);
          END IF;
        END IF;
      END IF;
    ELSIF v_platform = 'vinted' THEN
      v_plafond := GREATEST(1, COALESCE(
        NULLIF(v_prof.platform_settings->'vinted'->'republish_auto'->>'plafond_jour', '')::integer, 10));
      SELECT count(*) INTO v_faits FROM cross_post_jobs
      WHERE user_id = v_user AND action = 'republish'
        AND platform_fields->>'republish_source' = 'auto'
        AND created_at >= date_trunc('day', now());
      IF v_faits >= v_plafond THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'plafond_auto_atteint', 'plafond', v_plafond);
      END IF;
    ELSE
      RETURN jsonb_build_object('allowed', false, 'reason', 'module_inactif', 'platform', v_platform);
    END IF;
  END IF;

  IF v_tier = 'free' THEN
    v_qfree := quota_republication_free_etat(v_user);
    IF (v_qfree ->> 'plafond') IS NOT NULL AND (v_qfree ->> 'restantes')::integer <= 0 THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'plafond_republication_free',
                                'mode', 'mensuel',
                                'plafond', (v_qfree ->> 'plafond')::integer,
                                'faites', (v_qfree ->> 'faites')::integer, 'restantes', 0,
                                'remise_le', v_qfree -> 'remise_le');
    END IF;
  ELSIF v_tier IN ('premium', 'pro') THEN
    v_plafond := quota_remontees_plafond(v_tier);
    IF v_plafond IS NOT NULL AND v_plafond > 0 THEN
      SELECT COALESCE(max(created_at), date_trunc('month', now())) INTO v_cycle
      FROM coin_ledger WHERE user_id = v_user AND kind IN ('grant_monthly','grant_upgrade');
      v_faits := remontees_du_cycle(v_user, v_cycle);
      IF v_faits >= v_plafond THEN
        IF p_source = 'auto' THEN
          RETURN jsonb_build_object('allowed', false, 'reason', 'plafond_auto_atteint', 'plafond', v_plafond);
        END IF;
        RETURN jsonb_build_object('allowed', false, 'reason', 'plafond_republication_mensuel',
                                  'plafond', v_plafond, 'faites', v_faits)
          || CASE WHEN jauges_actives() THEN jsonb_build_object('remise_le', (SELECT w.next_grant_at FROM coin_wallets w WHERE w.user_id = v_user)) ELSE '{}'::jsonb END;
      END IF;
    END IF;
  END IF;

  v_garde := garde_fou_jour(v_user, 'remontees', 1);
  IF v_garde IS NOT NULL THEN
    IF p_source = 'auto' THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'plafond_auto_atteint', 'garde_fou', true,
                                'plafond', (v_garde ->> 'garde')::integer);
    END IF;
    RETURN v_garde || jsonb_build_object('platform', v_platform);
  END IF;

  IF v_platform = 'vinted' THEN
    IF EXISTS (
      SELECT 1 FROM cross_post_jobs j
      WHERE j.user_id = v_user AND j.action = 'republish'
        AND j.platform_fields->>'vinted_item_id' = v_item
        AND j.status IN ('pending', 'processing', 'needs_user')
    ) THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'republish_en_cours');
    END IF;

    IF EXISTS (
      SELECT 1 FROM cross_post_jobs j
      WHERE j.user_id = v_user AND j.action = 'republish'
        AND j.platform_fields->>'vinted_item_id' = v_item
        AND j.status = 'published'
        AND j.published_at > now() - interval '24 hours'
    ) THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'cadence_24h');
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM inventaire i
      WHERE i.id = p_inventaire_id AND i.user_id = v_user
        AND i.photos IS NOT NULL AND jsonb_array_length(i.photos) > 0
    ) THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'article_sans_photo');
    END IF;
  END IF;

  SELECT titre INTO v_titre FROM inventaire
  WHERE id = p_inventaire_id AND user_id = v_user;

  SELECT value INTO v_price FROM coin_config WHERE key = 'price_republish';
  IF v_price IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'price_not_configured');
  END IF;

  IF v_price > 0 THEN
    INSERT INTO coin_wallets (user_id) VALUES (v_user) ON CONFLICT (user_id) DO NOTHING;
    SELECT * INTO v_wallet FROM coin_wallets WHERE user_id = v_user FOR UPDATE;
    IF v_wallet.next_grant_at IS NULL OR v_wallet.next_grant_at <= now() THEN
      PERFORM upgrade_monthly_grant(v_user, v_tier, null, 'lazy');
      SELECT * INTO v_wallet FROM coin_wallets WHERE user_id = v_user FOR UPDATE;
    END IF;
    IF v_wallet.included_balance + v_wallet.purchased_balance < v_price THEN
      IF p_source = 'auto' AND v_platform = 'vinted' THEN
        UPDATE profiles SET platform_settings = jsonb_set(
          COALESCE(platform_settings, '{}'::jsonb),
          '{vinted,republish_auto}',
          COALESCE(platform_settings #> '{vinted,republish_auto}', '{}'::jsonb)
            || jsonb_build_object(
                 'derniere_erreur', 'pepites_insuffisantes',
                 'derniere_erreur_le', now()::text),
          true)
        WHERE id = v_user;
      END IF;
      RETURN jsonb_build_object('allowed', false, 'reason', 'insufficient_coins',
        'price', v_price, 'balance', v_wallet.included_balance + v_wallet.purchased_balance);
    END IF;
    v_from_inc := LEAST(v_wallet.included_balance, v_price);
    v_from_pur := v_price - v_from_inc;
    UPDATE coin_wallets SET
      included_balance  = included_balance  - v_from_inc,
      purchased_balance = purchased_balance - v_from_pur,
      updated_at        = now()
    WHERE user_id = v_user;
  END IF;

  IF p_source = 'auto' AND v_platform = 'vinted'
     AND v_prof.platform_settings #> '{vinted,republish_auto}' ? 'derniere_erreur' THEN
    UPDATE profiles SET platform_settings = jsonb_set(
      platform_settings,
      '{vinted,republish_auto}',
      (platform_settings #> '{vinted,republish_auto}') - 'derniere_erreur' - 'derniere_erreur_le')
    WHERE id = v_user;
  END IF;

  v_prix := p_prix_republication;

  IF v_platform = 'vinted' THEN
    INSERT INTO cross_post_jobs (user_id, inventaire_id, platform, action, status, photo_option,
                                 title, price, listing_url, platform_fields)
    VALUES (
      v_user, p_inventaire_id, 'vinted', 'republish', 'pending', 'original',
      v_titre, v_prix,
      'https://www.vinted.fr/items/' || v_item,
      jsonb_build_object(
        'republish_step', 'a_capturer',
        'vinted_item_id', v_item,
        'pepites_debitees', v_price,
        'republish_source', p_source
      )
      || CASE WHEN v_prix IS NOT NULL
              THEN jsonb_build_object('prix_republication', v_prix)
              ELSE '{}'::jsonb END
    ) RETURNING id INTO v_job_id;
  ELSE
    v_pf_src := public.republication_sans_traces(COALESCE(v_src.platform_fields, '{}'::jsonb))
      - ARRAY['needsUserField', 'needsUserFields', 'needsUserResolved', 'needsUserAttempts', 'needsUserBoucle',
              'boucle_needs_user', 'needs_user_tick_le', 'needs_user_source', 'processing_since', 'next_action_after',
              'stale_recoveries', 'attente_session', 'blocage_antirobot', 'porte_pro_lbc', 'erreurs_archivees',
              'work_window_state', 'last_diagnostic', 'lbc_depot', 'lbc_depot_non_finalise', 'depot_non_confirme_requalifie',
              'verifier_doublon_avant_publication', 'unavailable_since', 'unavailable_pending_since', 'sale_signal',
              'detected_price', 'removed_by_user', 'republished_pending', 'delete_trace', 'delete_confirmed_by',
              'delete_dry_run_trace', 'listing_url_abandon', 'retrait_attend_lien', 'removal_url_missing',
              'republish_step', 'republish_source', 'republish_snapshot', 'republish_platform', 'republish_source_job_id',
              'republish_recreation', 'recreated_at', 'deleted_at', 'deleted_at_client', 'deleted_at_serveur',
              'horloge_client_ecart_s', 'suppression_verdict', 'old_listing_url', 'old_platform_listing_id',
              'recreation_retries', 'pepites_debitees', 'pepite_remboursee', 'prix_republication', 'orphan_alerted_at',
              'deleted_hang_count', 'introuvable_indetermine', 'attente_boutique', 'republish_creneau_id',
              'republish_sweep_at', 'republish_moteur', 'republish_planifie', 'republish_prevol', 'republish_etat_reel'];
    INSERT INTO cross_post_jobs (user_id, inventaire_id, platform, action, status, photo_option,
                                 title, description, price, photos, listing_url, platform_listing_id, platform_fields)
    VALUES (
      v_user, p_inventaire_id, v_platform, 'republish', 'pending', COALESCE(v_src.photo_option, 'original'),
      COALESCE(v_src.title, v_titre), v_src.description, COALESCE(v_prix, v_src.price), v_photos,
      v_url, v_src.platform_listing_id,
      v_pf_src || jsonb_build_object(
        'republish_step', 'a_capturer',
        'republish_source', p_source,
        'republish_platform', v_platform,
        'republish_source_job_id', v_src.id,
        'pepites_debitees', v_price,
        'republish_snapshot', jsonb_build_object(
          'version', 2,
          'plateforme', v_platform,
          'source_job_id', v_src.id,
          'titre', COALESCE(v_src.title, v_titre),
          'prix', COALESCE(v_prix, v_src.price),
          'listing_url', v_url,
          'platform_listing_id', v_src.platform_listing_id,
          'photos', v_photos_n,
          'captured_at', now())
      )
      || CASE WHEN v_prix IS NOT NULL
              THEN jsonb_build_object('prix_republication', v_prix)
              ELSE '{}'::jsonb END
    ) RETURNING id, listing_url INTO v_job_id, v_url_ins;
    IF v_url_ins IS DISTINCT FROM v_url THEN
      RAISE EXCEPTION 'lien_annonce_incertain : republication % née avec le lien % au lieu de %', v_job_id, v_url_ins, v_url;
    END IF;
  END IF;

  IF v_price > 0 THEN
    INSERT INTO coin_ledger (user_id, delta, included_after, purchased_after, kind, metadata)
    VALUES (v_user, -v_price,
            v_wallet.included_balance - v_from_inc,
            v_wallet.purchased_balance - v_from_pur,
            'spend_republish',
            jsonb_build_object('vinted_item_id', v_item, 'job_id', v_job_id, 'platform', v_platform));
  END IF;

  INSERT INTO usage_logs (user_id, feature, metadata)
  VALUES (v_user, 'republish', jsonb_build_object(
    'coins', v_price, 'vinted_item_id', v_item, 'source', p_source,
    'plan', v_tier, 'platform', v_platform
  ));

  RETURN jsonb_build_object(
    'allowed', true, 'price', v_price, 'job_id', v_job_id, 'platform', v_platform,
    'included_after',  CASE WHEN v_price > 0 THEN v_wallet.included_balance - v_from_inc ELSE NULL END,
    'purchased_after', CASE WHEN v_price > 0 THEN v_wallet.purchased_balance - v_from_pur ELSE NULL END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.upgrade_monthly_grant(p_user_id uuid, p_tier text, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source text DEFAULT 'auto'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wallet     coin_wallets%ROWTYPE;
  v_old_tier   text;
  v_new_amount integer;
  v_override   integer;
  v_delta      integer;
  v_cap        integer;
  v_new_inc    integer;
  v_ref        text;
  v_res        jsonb;
begin
  if p_tier not in ('free','premium','pro','business') then
    return jsonb_build_object('granted', false, 'reason', 'invalid_tier');
  end if;

  insert into coin_wallets (user_id) values (p_user_id) on conflict (user_id) do nothing;
  select * into v_wallet from coin_wallets where user_id = p_user_id for update;

  if v_wallet.next_grant_at is null or v_wallet.next_grant_at <= now()
     or (p_source = 'payment' and v_wallet.next_grant_at <= now() + interval '2 days') then
    return grant_monthly_coins(p_user_id, p_tier, p_period_end, p_source);
  end if;

  select l.metadata->>'tier' into v_old_tier
  from coin_ledger l
  where l.user_id = p_user_id
    and l.kind in ('grant_monthly','grant_upgrade')
  order by l.created_at desc, l.id desc
  limit 1;
  v_old_tier := coalesce(v_old_tier, 'free');

  if v_old_tier is not distinct from p_tier and p_source = 'payment'
     and p_period_end is not null and p_period_end > now()
     and p_period_end > v_wallet.next_grant_at + interval '2 days' then
    update coin_wallets set next_grant_at = now() where user_id = p_user_id;
    v_res := grant_monthly_coins(p_user_id, p_tier, p_period_end, p_source);
    if coalesce((v_res ->> 'granted')::boolean, false) then
      return v_res || jsonb_build_object('cycle_neuf', true, 'echeance_avant', v_wallet.next_grant_at);
    end if;
    update coin_wallets set next_grant_at = p_period_end, updated_at = now() where user_id = p_user_id;
    return v_res || jsonb_build_object('cycle_neuf', false);
  end if;

  select monthly_grant_override into v_override from profiles where id = p_user_id;
  if v_override is not null and v_override > 0 then
    return jsonb_build_object('granted', false, 'reason', 'override_fixed_amount',
                              'amount', v_override, 'tier', p_tier);
  end if;


  select value into v_new_amount from coin_config where key = 'monthly_grant_' || p_tier;
  if v_new_amount is null then
    return jsonb_build_object('granted', false, 'reason', 'grant_not_configured');
  end if;

  if v_old_tier is not distinct from p_tier then
    if p_period_end is not null and p_period_end > now() then
      update coin_wallets set next_grant_at = p_period_end, updated_at = now()
      where user_id = p_user_id;
    end if;
    return jsonb_build_object('granted', false, 'reason', 'no_upgrade_needed',
                              'from_tier', v_old_tier, 'tier', p_tier);
  end if;

  v_delta := v_new_amount;

  v_cap     := v_new_amount * 2;
  v_new_inc := greatest(v_wallet.included_balance,
                        least(v_wallet.included_balance + v_delta, v_cap));
  v_delta   := v_new_inc - v_wallet.included_balance;

  if v_delta <= 0 then
    return jsonb_build_object('granted', false, 'reason', 'cap_reached',
                              'from_tier', v_old_tier, 'tier', p_tier);
  end if;

  v_ref := 'grant_upgrade:' || p_user_id || ':'
           || to_char(coalesce(v_wallet.next_grant_at, now()), 'YYYY-MM-DD') || ':' || p_tier;
  begin
    insert into coin_ledger (user_id, delta, included_after, purchased_after, kind, ref, metadata)
    values (
      p_user_id, v_delta, v_new_inc, v_wallet.purchased_balance,
      'grant_upgrade', v_ref,
      jsonb_build_object('tier', p_tier, 'from_tier', v_old_tier, 'source', p_source)
    );
  exception when unique_violation then
    return jsonb_build_object('granted', false, 'reason', 'already_granted', 'ref', v_ref);
  end;

  update coin_wallets set
    included_balance = v_new_inc,
    next_grant_at    = case when p_period_end is not null and p_period_end > now()
                            then p_period_end else next_grant_at end,
    updated_at       = now()
  where user_id = p_user_id;

  return jsonb_build_object('granted', true, 'topup', true, 'amount', v_delta,
                            'from_tier', v_old_tier, 'tier', p_tier,
                            'included_after', v_new_inc);
end;
$function$

CREATE OR REPLACE FUNCTION public.vente_relevee_meme_cession(p_job uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j public.cross_post_jobs%ROWTYPE; i public.inventaire%ROWTYPE; v_n integer; v_id bigint; v_annonce text;
BEGIN
  SELECT * INTO j FROM public.cross_post_jobs WHERE id = p_job;
  IF j.id IS NULL OR j.platform IS DISTINCT FROM 'vinted' OR j.inventaire_id IS NULL
     OR coalesce(j.action, 'publish') NOT IN ('publish', 'republish') THEN RETURN NULL; END IF;
  v_annonce := nullif(btrim(j.platform_listing_id), '');
  IF v_annonce IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO i FROM public.inventaire WHERE id = j.inventaire_id AND user_id = j.user_id;
  IF i.id IS NULL OR i.fusionne_dans IS NOT NULL OR i.statut IS DISTINCT FROM 'stock'
     OR coalesce(i.quantite, 1) > 1 THEN RETURN NULL; END IF;
  SELECT count(*) INTO v_n FROM public.ventes v WHERE v.user_id = j.user_id AND v.inventaire_id = i.id;
  IF v_n <> 1 THEN RETURN NULL; END IF;
  IF EXISTS (SELECT 1 FROM public.ventes_operations o WHERE o.user_id = j.user_id AND o.cle = 'annonce:vinted:' || v_annonce) THEN RETURN NULL; END IF;
  SELECT v.id INTO v_id FROM public.ventes v
   WHERE v.user_id = j.user_id AND v.inventaire_id = i.id
     AND v.commande_ref IS NOT NULL AND btrim(coalesce(v.annonce_id, '')) = v_annonce
     AND (v.plateforme_code IS NULL OR v.plateforme_code = 'vinted')
   LIMIT 1;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.vente_saisie_meme_cession(p_job uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j public.cross_post_jobs%ROWTYPE; i public.inventaire%ROWTYPE; v_n integer; v_id bigint; v_cle text;
BEGIN
  SELECT * INTO j FROM public.cross_post_jobs WHERE id = p_job;
  IF j.id IS NULL OR j.inventaire_id IS NULL OR coalesce(j.action, 'publish') NOT IN ('publish', 'republish') THEN RETURN NULL; END IF;
  SELECT * INTO i FROM public.inventaire WHERE id = j.inventaire_id AND user_id = j.user_id;
  IF i.id IS NULL OR i.fusionne_dans IS NOT NULL OR i.statut IS DISTINCT FROM 'vendu' THEN RETURN NULL; END IF;
  SELECT count(*) INTO v_n FROM public.ventes v WHERE v.user_id = j.user_id AND v.inventaire_id = i.id;
  IF v_n <> 1 THEN RETURN NULL; END IF;
  v_cle := CASE WHEN nullif(btrim(j.platform_listing_id), '') IS NOT NULL
    THEN 'annonce:' || j.platform || ':' || btrim(j.platform_listing_id) ELSE 'job:' || j.id::text END;
  IF EXISTS (SELECT 1 FROM public.ventes_operations o WHERE o.user_id = j.user_id AND o.cle = v_cle) THEN RETURN NULL; END IF;
  SELECT v.id INTO v_id FROM public.ventes v
   WHERE v.user_id = j.user_id AND v.inventaire_id = i.id AND v.commande_ref IS NULL
     AND (v.plateforme_code IS NULL OR v.plateforme_code IN ('ailleurs', j.platform))
   LIMIT 1;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.vente_transaction_annulee_leboncoin(p_vente bigint, p_motif text DEFAULT 'transaction_annulee'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v ventes%ROWTYPE; i inventaire%ROWTYPE; j cross_post_jobs%ROWTYPE;
  v_rendue text := NULL; v_recus jsonb := NULL; v_q integer;
  v_copie record; v_copies integer := 0; v_arretes integer := 0; v_en_cours integer := 0;
  v_ms bigint; v_hist bigint; v_hist_ligne jsonb; v_rv remises_en_vente%ROWTYPE; v_remise_avant jsonb;
  v_depot_avant jsonb; v_remise_arretee text := NULL;
BEGIN
  SELECT * INTO v FROM ventes WHERE id = p_vente;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'introuvable'); END IF;
  IF v.plateforme_code IS DISTINCT FROM 'leboncoin' OR v.annonce_id IS NULL THEN RETURN jsonb_build_object('action', 'hors_sujet'); END IF;
  IF coalesce((SELECT value FROM coin_config WHERE key = 'ventes_annulees_retrait_pause'), 0) = 1 THEN
    RETURN jsonb_build_object('action', 'en_pause');
  END IF;
  IF EXISTS (SELECT 1 FROM ventes_annulees_attente_go g WHERE g.vente_id = v.id AND g.decision IS NULL) THEN
    RETURN jsonb_build_object('action', 'en_attente_go');
  END IF;
  SELECT * INTO j FROM cross_post_jobs c
   WHERE c.user_id = v.user_id AND c.platform = 'leboncoin' AND c.status = 'sold'
     AND c.action IN ('publish', 'republish') AND btrim(coalesce(c.platform_listing_id, '')) = v.annonce_id
     AND c.platform_fields #>> '{sale_evidence,source}' = 'transaction_leboncoin'
   ORDER BY c.sold_at DESC NULLS LAST LIMIT 1;
  IF j.id IS NULL OR NOT EXISTS (SELECT 1 FROM ventes_operations o WHERE o.user_id = v.user_id
                                   AND o.cle = 'annonce:leboncoin:' || v.annonce_id AND o.resultat -> 'ventes_ids' @> to_jsonb(ARRAY[v.id])) THEN
    IF NOT EXISTS (SELECT 1 FROM usage_logs u WHERE u.user_id = v.user_id AND u.feature = 'vente_leboncoin_transaction'
                    AND u.metadata ->> 'vente' = v.id::text AND u.metadata ->> 'issue' = 'annulation_vente_saisie_signalee') THEN
      INSERT INTO usage_logs (user_id, feature, metadata) VALUES (v.user_id, 'vente_leboncoin_transaction',
        jsonb_build_object('vente', v.id::text, 'annonce', v.annonce_id, 'titre', v.titre, 'prix_vente', v.prix_vente,
          'issue', 'annulation_vente_saisie_signalee'));
    END IF;
    RETURN jsonb_build_object('action', 'signalee');
  END IF;
  IF v.inventaire_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(v.user_id::text || ':' || v.inventaire_id::text, 0));
  END IF;
  INSERT INTO ventes_supprimees (user_id, plateforme_code, commande_ref, annonce_id, titre, prix_vente, vendu_le, vente_id, supprimee_le, source, motif)
  VALUES (v.user_id, 'leboncoin', v.commande_ref, v.annonce_id, v.titre, v.prix_vente, v.vendu_le, v.id, now(),
          'releve_leboncoin', left(coalesce(p_motif, 'transaction_annulee'), 60));
  SELECT jsonb_agg(to_jsonb(o)) INTO v_recus FROM ventes_operations o
   WHERE o.user_id = v.user_id AND o.cle = 'annonce:leboncoin:' || v.annonce_id;
  INSERT INTO usage_logs (user_id, feature, metadata) VALUES (v.user_id, 'vente_retiree',
    jsonb_build_object('vente', to_jsonb(v), 'source', 'releve_leboncoin', 'motif', coalesce(p_motif, 'transaction_annulee'), 'recus', v_recus));
  DELETE FROM ventes WHERE id = v.id;
  DELETE FROM ventes_operations o WHERE o.user_id = v.user_id AND o.cle = 'annonce:leboncoin:' || v.annonce_id;

  v_q := greatest(coalesce(v.quantite, 1), 1);
  IF v.inventaire_id IS NOT NULL THEN
    SELECT * INTO i FROM inventaire WHERE id = v.inventaire_id AND user_id = v.user_id FOR UPDATE;
    IF i.id IS NOT NULL AND i.fusionne_dans IS NULL AND i.statut = 'vendu'
       AND NOT EXISTS (SELECT 1 FROM ventes x WHERE x.user_id = v.user_id AND x.inventaire_id = i.id) THEN
      UPDATE remises_en_vente SET statut = 'abandonnee', motif = 'transaction_annulee', traite_le = now()
       WHERE user_id = v.user_id AND inventaire_id = i.id AND statut = 'a_faire';
      UPDATE inventaire SET statut = 'stock', quantite = v_q WHERE id = i.id AND statut = 'vendu';
      v_rendue := 'fiche';
      FOR v_copie IN
        SELECT d.id AS retrait, d.status, d.platform, p.id AS depot, p.status AS depot_statut
          FROM cross_post_jobs d
          LEFT JOIN cross_post_jobs p ON p.id = nullif(d.platform_fields #>> '{arme_par,depot}', '')::uuid
         WHERE d.user_id = v.user_id AND d.inventaire_id = i.id AND d.action = 'delete'
           AND d.platform <> 'leboncoin'
           AND d.platform_fields #>> '{arme_par,chemin}' IN ('vente_article_serveur', 'vente_copie_prouvee')
           AND abs(extract(epoch FROM (nullif(d.platform_fields #>> '{arme_par,le}', '')::timestamptz - v.created_at))) <= 120
         ORDER BY d.platform
      LOOP
        IF v_copie.status IN ('pending', 'needs_user') THEN
          UPDATE cross_post_jobs SET status = 'cancelled',
                 error = 'Achat Leboncoin annulé : l''article est revenu dans ton stock, cette annonce reste en ligne.',
                 platform_fields = coalesce(platform_fields, '{}'::jsonb)
                   || jsonb_build_object('vente_annulee', jsonb_build_object('le', now(), 'vente', v.id, 'source', 'transaction_leboncoin'))
           WHERE id = v_copie.retrait AND status IN ('pending', 'needs_user');
          IF FOUND THEN v_arretes := v_arretes + 1; END IF;
        ELSIF v_copie.status = 'deleted' AND v_copie.depot IS NOT NULL AND v_copie.depot_statut = 'cancelled' THEN
          UPDATE cross_post_jobs SET platform_fields = coalesce(platform_fields, '{}'::jsonb)
                 || jsonb_build_object('vente_annulee_remise', jsonb_build_object('vente', v.id, 'source', 'transaction_leboncoin', 'le', now()))
           WHERE id = v_copie.depot;
          INSERT INTO remises_en_vente (user_id, inventaire_id, platform, job_vendu, prochain_essai, statut)
          VALUES (v.user_id, i.id, v_copie.platform, v_copie.depot, now(), 'proposee')
          ON CONFLICT (job_vendu) DO UPDATE
            SET statut = 'proposee', motif = NULL, prochain_essai = now(), traite_le = NULL, accepte_le = NULL
            WHERE remises_en_vente.statut <> 'faite';
          v_copies := v_copies + 1;
        ELSIF v_copie.status = 'processing' THEN
          v_en_cours := v_en_cours + 1;
        END IF;
      END LOOP;
      INSERT INTO inventaire_journal (user_id, inventaire_id, champ, avant, apres, source, motif, detail) VALUES
        (v.user_id, i.id, 'statut', i.statut, 'stock', 'releve_leboncoin', 'transaction_annulee',
         jsonb_build_object('vente', v.id, 'annonce', v.annonce_id, 'retraits_arretes', v_arretes, 'copies_remises', v_copies,
                            'retraits_en_cours', v_en_cours));
    ELSIF i.id IS NOT NULL AND i.fusionne_dans IS NULL AND i.statut = 'stock' THEN
      v_ms := floor(extract(epoch FROM v.created_at) * 1000)::bigint;
      SELECT h.id, to_jsonb(h) INTO v_hist, v_hist_ligne FROM inventaire h
       WHERE h.user_id = v.user_id AND h.statut = 'vendu' AND h.id BETWEEN v_ms - 2000 AND v_ms + 20000
         AND h.titre IS NOT DISTINCT FROM i.titre AND h.prix_vente IS NOT DISTINCT FROM v.prix_vente
         AND NOT EXISTS (SELECT 1 FROM ventes x WHERE x.inventaire_id = h.id)
         AND NOT EXISTS (SELECT 1 FROM cross_post_jobs c WHERE c.inventaire_id = h.id)
       ORDER BY abs(h.id - v_ms) LIMIT 1;
      UPDATE inventaire SET quantite = coalesce(quantite, 0) + v_q WHERE id = i.id;
      IF v_hist IS NOT NULL THEN DELETE FROM inventaire WHERE id = v_hist; END IF;
      v_rendue := 'exemplaire';
      SELECT * INTO v_rv FROM remises_en_vente WHERE job_vendu = j.id FOR UPDATE;
      IF v_rv.id IS NOT NULL THEN
        v_remise_avant := to_jsonb(v_rv);
        IF v_rv.statut = 'a_faire' THEN
          DELETE FROM remises_en_vente WHERE id = v_rv.id;
          v_remise_arretee := 'file';
        ELSIF v_rv.statut = 'faite' AND v_rv.job_cree IS NOT NULL THEN
          SELECT jsonb_build_object('id', c.id, 'status', c.status, 'error', c.error) INTO v_depot_avant
            FROM cross_post_jobs c WHERE c.id = v_rv.job_cree;
          UPDATE cross_post_jobs SET status = 'cancelled',
                 error = 'Achat Leboncoin annulé : l''annonce d''origine est de nouveau en ligne, cette remise en vente est arrêtée.',
                 platform_fields = coalesce(platform_fields, '{}'::jsonb)
                   || jsonb_build_object('remise_arretee', jsonb_build_object('le', now(), 'vente', v.id,
                        'source', 'transaction_leboncoin', 'job_vendu', j.id, 'avant', v_depot_avant))
           WHERE id = v_rv.job_cree AND status = 'pending';
          IF FOUND THEN
            DELETE FROM remises_en_vente WHERE id = v_rv.id;
            v_remise_arretee := 'depot';
          ELSE
            v_remise_arretee := 'deja_prise';
          END IF;
        END IF;
      END IF;
      INSERT INTO inventaire_journal (user_id, inventaire_id, champ, avant, apres, source, motif, detail) VALUES
        (v.user_id, i.id, 'quantite', i.quantite::text, (coalesce(i.quantite, 0) + v_q)::text, 'releve_leboncoin', 'transaction_annulee',
         jsonb_build_object('vente', v.id, 'annonce', v.annonce_id, 'copie_effacee', v_hist_ligne, 'remise_arretee', v_remise_arretee,
                            'avant', jsonb_build_object('quantite', i.quantite, 'remise', v_remise_avant, 'depot', v_depot_avant)));
    END IF;
  END IF;
  UPDATE cross_post_jobs SET status = 'published', sold_at = NULL,
         platform_fields = (coalesce(platform_fields, '{}'::jsonb)
           - ARRAY['sale_signal', 'unavailable_since', 'unavailable_pending_since', 'detected_price', 'vente_operation_cle'])
           || jsonb_build_object('vente_annulee', jsonb_build_object('le', now(), 'vente', v.id, 'annonce', 'en_ligne',
                                 'source', 'transaction_leboncoin', 'preuve', platform_fields -> 'sale_evidence'))
   WHERE id = j.id AND status = 'sold';
  RETURN jsonb_build_object('action', 'retiree', 'fiche', v_rendue, 'job', j.id, 'retraits_arretes', v_arretes,
                            'copies_remises', v_copies, 'retraits_en_cours', v_en_cours,
                            'copie_effacee', v_hist, 'remise_arretee', v_remise_arretee);
END;
$function$

CREATE OR REPLACE FUNCTION public.ventes_garde_annonce_de_la_vente()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_brut text;
  v_pf   text;
  v_inv  bigint;
  v_nb   integer;
begin
  begin
    v_brut := lower(coalesce(nullif(btrim(new.plateforme_code), ''), new.plateforme, ''));
    v_pf := case
      when v_brut like '%vinted%' then 'vinted'
      when v_brut like '%leboncoin%' or v_brut in ('lbc', 'le bon coin') then 'leboncoin'
      when v_brut like '%beebs%' then 'beebs'
      when v_brut like '%ebay%' then 'ebay'
      when v_brut like '%opla%' then 'opla'
      when v_brut like '%depop%' then 'depop'
      else null end;
    if v_pf is null then
      return new;
    end if;
    v_inv := new.inventaire_id;
    if v_inv is null then
      return new;
    end if;
    update public.cross_post_jobs d
       set status = 'cancelled',
           error = 'Retrait inutile : l''article a été vendu sur cette plateforme — l''annonce vendue n''est pas touchée.',
           platform_fields = coalesce(d.platform_fields, '{}'::jsonb) || jsonb_build_object(
             'retrait_non_envoye', jsonb_build_object('le', now(), 'motif', 'plateforme_de_la_vente',
               'vente', new.id, 'pose_par', 'ventes_garde_annonce_de_la_vente'))
     where d.user_id = new.user_id and d.inventaire_id = v_inv
       and d.platform = v_pf and d.action = 'delete' and d.status = 'pending'
       and d.platform_fields -> 'arme_par' ->> 'chemin' = 'vente_article_serveur'
       and d.created_at > now() - interval '15 minutes';
  exception when others then
    raise warning 'ventes_garde_annonce_de_la_vente (vente %) : %', new.id, sqlerrm;
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ventes_prouvees_tick(p_max integer DEFAULT 25, p_budget_ms integer DEFAULT 4000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '25s'
AS $function$
DECLARE
  v_debut   timestamptz := clock_timestamp();
  v_epoch   integer;
  v_depuis  timestamptz;
  v_max     integer := greatest(1, least(coalesce(p_max, 25), 100));
  v_budget  interval := make_interval(secs => greatest(500, least(coalesce(p_budget_ms, 4000), 15000)) / 1000.0);
  c         record;
  r         jsonb;
  v_issue   text;
  n_cand    integer := 0;
  n_ok      integer := 0;
  n_ref     integer := 0;
  n_rep     integer := 0;
  v_hors_budget boolean := false;
  v_detail  jsonb := '[]'::jsonb;
  v_reco    jsonb := NULL;
  v_ratt    jsonb := NULL;
BEGIN
  SELECT value INTO v_epoch FROM coin_config WHERE key = 'ventes_prouvees_auto_depuis';
  IF coalesce(v_epoch, 0) <= 0 THEN
    RETURN jsonb_build_object('issue', 'coupe');
  END IF;
  IF NOT pg_try_advisory_xact_lock(hashtextextended('ventes_prouvees_tick', 0)) THEN
    RETURN jsonb_build_object('issue', 'deja_en_cours');
  END IF;
  v_depuis := to_timestamp(v_epoch);
  FOR c IN SELECT * FROM ventes_prouvees_a_enregistrer(v_depuis, v_max) LOOP
    n_cand := n_cand + 1;
    IF clock_timestamp() - v_debut > v_budget THEN
      v_hors_budget := true; n_rep := n_rep + 1;
      CONTINUE;
    END IF;
    r := enregistrer_vente_prouvee(c.job_id);
    v_issue := r ->> 'issue';
    IF v_issue = 'enregistree' THEN n_ok := n_ok + 1;
    ELSIF v_issue IN ('refusee', 'erreur') THEN n_ref := n_ref + 1;
    ELSE n_rep := n_rep + 1;
    END IF;
    v_detail := v_detail || jsonb_build_array(jsonb_build_object(
      'job', c.job_id, 'user', left(c.user_id::text, 8), 'inv', c.inventaire_id, 'pf', c.platform,
      'preuve', c.preuve, 'preuve_le', c.preuve_le, 'issue', v_issue, 'raison', r ->> 'reason',
      'ventes', r -> 'ventes_ids', 'retraits', r -> 'retraitsArmes'));
  END LOOP;
  BEGIN
    v_reco := public.signaux_vente_reconcilier(40);
  EXCEPTION WHEN OTHERS THEN
    v_reco := jsonb_build_object('erreur', left(SQLERRM, 200));
  END;
  BEGIN
    v_ratt := public.ventes_relevees_sans_annonce_rattacher(25, 4000);
  EXCEPTION WHEN OTHERS THEN
    v_ratt := jsonb_build_object('erreur', left(SQLERRM, 200));
  END;
  INSERT INTO ventes_prouvees_passages (debut, fin, duree_ms, issue, candidates, enregistrees, refusees, reportees, budget_atteint, detail)
  VALUES (v_debut, clock_timestamp(), (extract(epoch FROM clock_timestamp() - v_debut) * 1000)::integer, 'fait',
          n_cand, n_ok, n_ref, n_rep, v_hors_budget,
          CASE WHEN n_cand > 0 OR coalesce((v_reco ->> 'dementis')::int, 0) + coalesce((v_reco ->> 'fusionnes')::int, 0) > 0 OR v_reco ? 'erreur'
                    OR coalesce((v_ratt ->> 'rattachees')::int, 0) + coalesce((v_ratt ->> 'refusees')::int, 0) > 0 OR v_ratt ? 'erreur'
               THEN v_detail || CASE WHEN v_reco IS NOT NULL THEN jsonb_build_array(jsonb_build_object('reconciliation', v_reco)) ELSE '[]'::jsonb END
                             || CASE WHEN v_ratt IS NOT NULL THEN jsonb_build_array(jsonb_build_object('rattachement', v_ratt)) ELSE '[]'::jsonb END END);
  DELETE FROM ventes_prouvees_passages
   WHERE id IN (SELECT id FROM ventes_prouvees_passages WHERE debut < now() - interval '14 days' ORDER BY id LIMIT 500);
  RETURN jsonb_build_object('issue', 'fait', 'candidates', n_cand, 'enregistrees', n_ok, 'refusees', n_ref,
                            'reportees', n_rep, 'budget_atteint', v_hors_budget, 'reconciliation', v_reco, 'rattachement', v_ratt,
                            'duree_ms', (extract(epoch FROM clock_timestamp() - v_debut) * 1000)::integer);
EXCEPTION WHEN OTHERS THEN
  INSERT INTO ventes_prouvees_passages (debut, fin, duree_ms, issue, candidates, enregistrees, refusees, reportees, detail)
  VALUES (v_debut, clock_timestamp(), (extract(epoch FROM clock_timestamp() - v_debut) * 1000)::integer, 'erreur',
          n_cand, 0, 0, 0, jsonb_build_object('erreur', left(SQLERRM, 300)));
  RETURN jsonb_build_object('issue', 'erreur', 'erreur', left(SQLERRM, 300));
END;
$function$

CREATE OR REPLACE FUNCTION public.ventes_relevees_sans_annonce_rattacher(p_max integer DEFAULT 25, p_budget_ms integer DEFAULT 4000, p_user uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '20s'
AS $function$
DECLARE
  v_debut   timestamptz := clock_timestamp();
  v_max     integer := greatest(1, least(coalesce(p_max, 25), 1000));
  v_budget  interval := make_interval(secs => greatest(500, least(coalesce(p_budget_ms, 4000), 15000)) / 1000.0);
  c         record;
  r         jsonb;
  n_vus     integer := 0;
  n_ok      integer := 0;
  n_ref     integer := 0;
  n_amb     integer := 0;
  v_budget_atteint boolean := false;
  v_detail  jsonb := '[]'::jsonb;
BEGIN
  FOR c IN SELECT * FROM public.ventes_relevees_sans_annonce_candidats(p_user) x ORDER BY x.vendu_le, x.vente_id LOOP
    IF NOT c.rattachable THEN n_amb := n_amb + 1; CONTINUE; END IF;
    IF n_vus >= v_max OR clock_timestamp() - v_debut > v_budget THEN v_budget_atteint := true; EXIT; END IF;
    n_vus := n_vus + 1;
    BEGIN
      UPDATE public.ventes SET inventaire_id = c.inventaire_id, annonce_id = c.annonce
       WHERE id = c.vente_id AND user_id = c.user_id AND inventaire_id IS NULL AND annonce_id IS NULL;
      IF NOT FOUND THEN RAISE EXCEPTION 'la vente a changé'; END IF;
      r := public.signal_vente_clore_vente_relevee(c.job_id, c.vente_id, 'ventes_relevees_sans_annonce_rattacher');
      IF coalesce(r ->> 'ok', 'false') <> 'true' THEN
        RAISE EXCEPTION 'carte non close : %', coalesce(r ->> 'reason', '?');
      END IF;
      INSERT INTO public.usage_logs (user_id, feature, metadata)
      VALUES (c.user_id, 'vente_relevee_rattachee', jsonb_build_object(
        'vente', c.vente_id, 'commande', c.commande_ref, 'inventaire_id', c.inventaire_id,
        'job', c.job_id, 'annonce', c.annonce, 'prix', c.prix, 'vendu_le', c.vendu_le,
        'fenetre', jsonb_build_object('debut', c.fenetre_debut, 'fin', c.fenetre_fin),
        'regle', 'vente_relevee_sans_annonce_unique', 'par', 'ventes_relevees_sans_annonce_rattacher',
        'fiche_vendue', r -> 'inventaireUpdated'));
      n_ok := n_ok + 1;
      v_detail := v_detail || jsonb_build_array(jsonb_build_object(
        'vente', c.vente_id, 'inv', c.inventaire_id, 'annonce', c.annonce, 'user', left(c.user_id::text, 8)));
    EXCEPTION WHEN OTHERS THEN
      n_ref := n_ref + 1;
      v_detail := v_detail || jsonb_build_array(jsonb_build_object(
        'vente', c.vente_id, 'inv', c.inventaire_id, 'annonce', c.annonce, 'user', left(c.user_id::text, 8),
        'refus', left(SQLERRM, 200)));
    END;
  END LOOP;
  RETURN jsonb_build_object('rattachees', n_ok, 'refusees', n_ref, 'ambigues', n_amb,
                            'budget_atteint', v_budget_atteint,
                            'duree_ms', (extract(epoch FROM clock_timestamp() - v_debut) * 1000)::integer)
      || CASE WHEN jsonb_array_length(v_detail) > 0 THEN jsonb_build_object('detail', v_detail) ELSE '{}'::jsonb END;
END;
$function$

CREATE OR REPLACE FUNCTION public.ventes_suppression_trace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF coalesce(OLD.commande_ref, OLD.annonce_id) IS NOT NULL THEN
    INSERT INTO ventes_supprimees (user_id, plateforme_code, commande_ref, annonce_id, titre, prix_vente, vendu_le, vente_id)
    VALUES (OLD.user_id,
            coalesce(OLD.plateforme_code, plateforme_normalisee(OLD.plateforme)),
            OLD.commande_ref, OLD.annonce_id, OLD.titre, OLD.prix_vente, OLD.vendu_le, OLD.id);
  END IF;
  RETURN OLD;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'ventes_suppression_trace (vente %) : %', OLD.id, SQLERRM;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.vinted_preuve_page_veilleur()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id  text := nullif(btrim(coalesce(new.platform_listing_id, '')), '');
  v_sig timestamptz := public._ts_ou_null(new.platform_fields ->> 'unavailable_since');
begin
  if v_id is null or v_sig is null or new.last_checked_at is null then return new; end if;
  if new.last_checked_at is not distinct from old.last_checked_at then return new; end if;
  if abs(extract(epoch from (new.last_checked_at - v_sig))) > 2 then return new; end if;
  if coalesce(substring(new.listing_url from '/items/([0-9]+)'), '') <> v_id then return new; end if;
  new.platform_fields := new.platform_fields || jsonb_build_object('sale_evidence', jsonb_build_object(
    'platform', 'vinted', 'listing_id', v_id, 'state', 'sold', 'exact', true,
    'source', 'page_annonce_veilleur', 'lu_le', new.platform_fields ->> 'unavailable_since',
    'pose_par', 'vinted_preuve_page_veilleur'));
  return new;
end;
$function$

